            .googleAPI: "Google API",
            .geminiModel: "Модель Gemini",
            .googleAPIBody: "Аудио загружается в Google и сначала превращается в слегка очищенную Raw-транскрипцию с помощью выбранной модели Gemini. Raw снова доступен в HUD. При выборе цели 1 или 2 соответствующий промпт из Настройки → Промпты затем выполняется отдельным текстовым запросом.",
