            .totalTokens: "Всего токенов",
            .selectedModel: "Выбранная модель",
            .resetStats: "Сбросить статистику",
            .noUsageData: "Статистики пока нет.",
            .accessibilityPermission: "Разрешение Accessibility",
            .accessibilityTrusted: "Выдано",
            .accessibilityNotTrusted: "Не выдано",
            .accessibilityPermissionDescription: "Нужно только для режима печати в активное приложение. Режим буфера обмена не требует Accessibility.",
            .requestAccessibilityPermission: "Запросить разрешение",
            .openAccessibilitySettings: "Открыть настройки Accessibility",
            .refreshPermissionStatus: "Обновить статус",
            // —— Справка (основная) ——
            .helpHeroTitle: "Справка SmartScribe",
            .helpHeroSubtitle: "Диктуйте в любом приложении на Mac. Речь распознаётся локально через Whisper; текст можно оставить как есть, почистить или переписать — и скопировать или впечатать туда, где вы работали.",
            .helpStartTitle: "С чего начать (первые 5 минут)",
            .helpStart1: "Разрешите микрофон, когда macOS спросит. Без него запись не начнётся.",
            .helpStart2: "Настройки → Локальные модели: скачайте Whisper (Large v3 Full — лучший универсальный выбор) и нажмите «Использовать».",
            .helpStart3: "Настройки → Горячая клавиша: включите hotkeys. Primary (по умолчанию Option+S) — диктовка. Хоткей окна перевода (по умолчанию Option+1) открывает полную плавающую панель перевода; быстрый перевод (по умолчанию Option+2) показывает только результат; «Открыть настройки» (по умолчанию Option+~) открывает настройки. Для диктовки выберите Target (Raw / Вариант 1 / Вариант 2) и Mode (буфер или печать в активное приложение).",
            .helpStart4: "По желанию: в API Providers добавьте облачный ключ (можно несколько на провайдера), выберите модель, отметьте избранное ★, затем Use for Polishing — или поставьте локальную MLX. Без движка доводки/перевода Варианты 1/2 и принудительный неанглийский язык не улучшат текст.",
            .helpStart5: "Диктовка: фокус в любом приложении → Option+S → говорите → Option+S снова (красный HUD = запись, зелёный = обработка). Быстрый перевод: выделите текст → Option+1 → плавающая панель захватывает selection/буфер и переводит (Option+2 показывает только результат).",
            .helpModesTitle: "Четыре режима работы",
            .helpModeWindowTitle: "Главное окно",
            .helpModeWindowBody: "Блокнот заметок: запись или импорт аудио, просмотр Raw / Вариант 1 / Вариант 2, доводка, перевод и копирование. Удобно, когда нужна правка и история.",
            .helpModeHotkeyTitle: "Hotkey + Overlay HUD",
            .helpModeHotkeyBody: "Оставайтесь в другом приложении. Primary hotkey (Option+S) пишет с плавающим HUD: режим языка (A / буква) и цель вывода (R / 1 / 2). Пока виден HUD, прокрутка переключает провайдера обработки, а правый клик по провайдеру открывает меню выбора конкретной модели. Во время диктовки фокус клавиатуры не забирается.",
            .helpModeFloatTitle: "Floating Translation Window",
            .helpModeFloatBody: "Хоткей окна перевода (по умолчанию Option+1) открывает панель перевода поверх всех окон. Захватывает выделенный текст из активного приложения (быстрый Command-C), заполняет Original и может сразу перевести. Нужна смена языка без полной диктовки.",
            .helpWindowTitle: "Главное окно",
            .helpWindowBody: "Слева — список заметок. Справа — выбранная заметка: аудио, меню провайдера/модели доводки, вкладки текста и панель действий.",
            .helpWindowNotes: "Сайдбар: выбор заметки, «Копировать все» или «Очистить все» (безвозвратно: все заметки и оставшиеся файлы записей на диске).",
            .helpWindowTabs: "Вкладки: Raw — чистый транскрипт. Вариант 1 — лёгкая чистка (слова-паразиты, повторы). Вариант 2 — более сильная переработка. Markdown на отполированной вкладке структурирует текст. Слоты D/1/2/3/4 переключают кастомный промпт варианта.",
            .helpWindowActions: "Нижняя панель: Запись / Стоп, пустая заметка, Импорт аудио (или перетащите файл), Перевод, Доводка, Копировать. Settings открывает настройки.",
            .helpWindowPolishingMenus: "Над редактором можно сменить Polishing Provider (Disabled / Quick Cleanup / локальный MLX / облако) и Polishing Model (модели выбранного облачного провайдера или локальные MLX). Это то же, что Settings → API Providers / Polishing, но без ухода из заметки.",
            .helpHUDTitle: "Overlay HUD (плавающая капсула)",
            .helpHUDIntro: "После нажатия глобальной горячей клавиши поверх любого приложения появляется маленькая плавающая капсула. Это не обычное окно: она поверх всех, не забирает фокус клавиатуры и показывает только статус — не полный текст транскрипта.",
            .helpHUDAnatomy: "Слева направо: (1) кнопка языка  ·  (2) живая волна по центру  ·  (3) кнопка цели вывода. На экране часто выглядит так:  [ A ]  ≈≈≈  [ R ].",
            .helpHUDColorRed: "Средняя волна красная — идёт запись с микрофона. Говорите, пока она красная.",
            .helpHUDColorGreen: "После стопа (hotkey ещё раз) волна зелёная: идут транскрибация, при необходимости доводка и доставка текста. Дождитесь, пока HUD скроется.",
            .helpHUDLeftTitle: "Левая кнопка — режим языка (A ↔ буква)",
            .helpHUDLeftA: "A = Auto. SmartScribe оставляет / автоопределяет язык, на котором вы говорили. Без принудительного перевода. Нужен транскрипт на том же языке, что и речь — оставляйте A.",
            .helpHUDLeftLetter: "Буква вместо A значит «принудительный целевой язык». Буква — первая буква английского названия языка: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German и т.д. Какая буква видна, зависит от Настройки → Горячая клавиша → Язык транскрибации (или Glossary Auto Translation Language, если в Hotkey стоит Auto).",
            .helpHUDLeftTap: "Нажмите левую кнопку: A → буква (принудительная цель), ещё раз: буква → A. Выбор запоминается для следующих сессий.",
            .helpHUDRightTitle: "Правая кнопка — цель вывода (R → 1 → 2)",
            .helpHUDRightR: "R = Raw (черновик). Доставляется голый транскрипт без доводки Вариант 1 / 2. Самый быстрый путь; при левой кнопке E всё равно может сработать Whisper translate в English.",
            .helpHUDRightCycle: "1 = Вариант 1 (лёгкая чистка). 2 = Вариант 2 (сильная переработка). Нужен активный движок доводки (облако или локальный MLX). Выбор 1 или 2 снова включает доводку, если она была выключена.",
            .helpHUDRightTap: "Нажимайте правую кнопку, чтобы циклически менять R → 1 → 2 → R. Выбор становится новым Target по умолчанию в настройках Hotkey.",
            .helpHUDControlLanguage: "Слева: A = авто / язык речи. Буква (E, S, R, …) = принудительный целевой язык. Тап переключает A ↔ буква.",
            .helpHUDControlTarget: "Справа: R = Raw, 1 = Вариант 1, 2 = Вариант 2. Тап циклически: R → 1 → 2 → R.",
            .helpHUDDrag: "Перетаскивание: зажмите капсулу (не обязательно кнопки) и тащите в любое место на любом мониторе — в угол, над Dock, рядом с полем ввода — куда удобно.",
            .helpHUDSize: "Размер и прозрачность: Настройки → Общие → Оверлей (Overlay HUD). Ползунок Size масштабирует всю капсулу (и число полосок волны). Transparency делает «стекло» более или менее прозрачным.",
            .helpHUDSound: "Звуки: там же, Общие → Оверлей. Включите «Звук при старте/завершении», выставьте громкость, «Проверить звуки HUD» — без записи. Сигналы играют при старте записи и при завершении обработки.",
            .helpHUDSettingsPath: "Внешний вид HUD — в Настройки → Общие → Оверлей (размер, прозрачность, звук, громкость). Позиция сохраняется сама после перетаскивания.",
            .helpHUDPosition: "После перетаскивания SmartScribe запоминает место и в следующий раз открывает HUD там же.",
            .helpHUDDuration: "Короткого искусственного лимита на длину речи нет. Говорите, пока волна красная; hotkey снова — стоп и обработка.",
            .helpLangTitle: "Режимы языка подробно",
            .helpLangIntro: "Язык задаётся левой кнопкой HUD и пунктом Настройки → Горячая клавиша → Язык транскрибации. Они работают вместе.",
            .helpLangAuto: "A (авто): транскрипт на языке, на котором вы говорили. Удобно для заметок без перевода.",
            .helpLangForced: "Буква (принудительная цель): после распознавания SmartScribe стремится к выбранному языку вывода. Говорите по-русски — получите English; по-английски — Spanish — в зависимости от настройки.",
            .helpLangEnglishNote: "Цель English + мультиязычный Whisper: для Raw используется встроенный Whisper translate в English на устройстве (быстро). Для качества берите Large v3 Full; Turbo легче, но менее надёжен на длинной или смешанной речи.",
            .helpLangOtherNote: "Любая неанглийская цель всегда требует LLM после Whisper (облако или локальный MLX). Без активного пути доводки принудительный Spanish/Russian/… не сменит язык.",
            .helpLangWhere: "Задайте цель в Hotkey → Язык транскрибации (English, Spanish, Russian, …). Если там Auto, режим буквы берёт Glossary → Auto Translation Language, иначе English. Буква на HUD обновляется из этого выбора.",
            .helpModelsTitle: "Локальные модели транскрибации",
            .helpModelsIntro: "Настройки → Локальные модели: WhisperKit Core ML превращает аудио в текст на Apple Silicon. Это отдельно от моделей доводки.",
            .helpModelsCatalog: "English-only (Small/Medium .en): быстро, если говорите только по-английски. Multilingual Small/Medium: легче для нескольких языков. Large v3 Turbo (~1.6 ГБ): быстрая large. Large v3 Full (~3 ГБ, Best quality): рекомендуемый выбор по точности и English translate.",
            .helpModelsRecommend: "Для смешанных языков и принудительного English (буква E на HUD) нужна мультиязычная модель — лучше Large v3 Full. English-only модели не умеют нативно переводить другие языки в English.",
            .helpModelsUse: "Скачать → Использовать (активна одна). Удалить стирает файлы с Mac. Apple Speech не используется — только Local Whisper (со скачанной моделью) или Cloud · Google Gemini (нужен Google API key).",
            .helpHotkeyTitle: "Настройки горячей клавиши",
            .helpHotkeyIntro: "Настройки → Горячая клавиша включает четыре независимых глобальных shortcut. Сначала включите Enable hotkey — иначе ни один не сработает.",
            .helpHotkeyPrimary: "Primary (по умолчанию Option+S (⌥S)): старт/стоп диктовки в Overlay HUD. Первое нажатие — запись (красный), второе — обработка (зелёный) и доставка Raw / Вариант 1 / Вариант 2.",
            .helpHotkeySecondary: "Окно перевода (по умолчанию Option+1): открывает полную плавающую панель перевода. Это не запись — захват selection/буфера и перевод. Стрелка сброса возвращает Option+1.",
            .helpHotkeyTertiary: "Быстрый перевод (по умолчанию Option+2): открывает минимальное окно только с результатом перевода (только чтение). Нажмите хоткей снова или Escape, чтобы закрыть.",
            .helpHotkeySettings: "Открыть настройки (по умолчанию Option+~): открывает окно настроек SmartScribe откуда угодно — можно сменить модель или язык, не выходя из приложения.",
            .helpModeQuickTitle: "Окно быстрого перевода",
            .helpModeQuickBody: "Третий хоткей (по умолчанию Option+2) открывает минимальное окно поверх всех окон только с результатом перевода — без исходного текста и кнопок. Прочитали — нажмите Escape, чтобы закрыть. Для правок или повторного перевода используйте полное окно перевода.",
            .helpFloatQuick: "Два окна перевода: плавающее окно перевода (Option+1) — полная панель с исходным текстом, меню провайдера/модели и элементами управления; быстрый перевод (Option+2) — минимальное окно только с результатом. Быстрый перевод удобен, когда нужно просто прочитать перевод.",
            .helpHotkeyTarget: "Target диктовки: какой текст доставляется после записи — Raw, Вариант 1 или Вариант 2. То же, что правая кнопка HUD (R / 1 / 2).",
            .helpHotkeyMode: "Mode диктовки: Clipboard копирует результат; Type into Active App впечатывает в поле, которое было в фокусе при старте записи.",
            .helpHotkeyAccess: "Type into Active App требует Accessibility (та же страница). Clipboard и Floating Translation Window не требуют Accessibility, чтобы показать текст в панели — но захват текста из других приложений через Command-C надёжнее, когда приложению доверяют.",
            .helpFloatTitle: "Floating Translation Window",
            .helpFloatIntro: "Изменяемая по размеру панель поверх всех окон (SmartScribe Translation), отдельно от блокнота заметок. Удобна для быстрой смены языка в браузере, почте или чате.",
            .helpFloatHotkey: "Открывается хоткеем окна перевода (Настройки → Горячая клавиша → Окно перевода, по умолчанию Option+1). Перевод из нижней панели главного окна использует тот же UI.",
            .helpFloatCapture: "При открытии SmartScribe кратко шлёт Command-C во frontmost app, чтобы скопировать выделение; если вы внутри SmartScribe — берётся selection заметки, иначе буфер. Если текст есть и выбран провайдер перевода — перевод стартует сразу.",
            .helpFloatPanel: "В панели: Provider и Model, Target Language, правка Original, Translate / Translate Again или короткая запись для перевода. Панель плавает над другими приложениями и масштабируется.",
            .helpFloatFavorites: "Список моделей в переводе предпочитает избранные (★) из Настройки → API Providers (поиск по моделям). Если избранных нет — показывается текущая выбранная модель.",
            .helpFloatDoubleClick: "Двойной клик по полю Original (источник) вставляет текст из буфера и сразу запускает перевод — удобно после ручного Copy.",
            .helpFloatEscape: "Escape или кнопка закрытия скрывает панель. SmartScribe при этом не выходит.",
            .helpCloudTitle: "Облачные API-провайдеры",
            .helpCloudIntro: "Настройки → API Providers: облачные LLM для доводки и перевода — не для Whisper. Сверху dropdown провайдера, карточка настроек, внизу usage stats.",
            .helpCloudProviders: "Порядок: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic в UI не показывается.) Бейдж Active — движок доводки.",
            .helpCloudConfigure: "Выберите провайдера, введите ключ(и), Browse models (поиск), выберите текстовую модель, затем Use for Polishing. Get API Key открывает консоль. Чипы модели: context length и, где есть, цены input/output.",
            .helpCloudKeys: "Несколько API-ключей: до 10 на провайдера (Add Key). Глаз показывает/скрывает ключ. Для запросов используется первый непустой; остальные — ротация или work/personal.",
            .helpCloudFavorites: "В picker моделей ставьте ★ на избранные. Они поднимаются вверх и предпочитаются в меню Floating Translation Window. Избранное хранится на этом Mac.",
            .helpCloudOpenRouter: "OpenRouter: живой баланс (цвет остатка USD), каталог с context и ценами $/M токенов, кнопка обновления. Смотрите баланс перед длинными сессиями.",
            .helpCloudBudget: "Слайдер budget у OpenRouter — личный ориентир «сколько планирую тратить», сам API не отключает. Реальный остаток — в баннере balance.",
            .helpCloudCustom: "Custom: любой OpenAI-compatible Base URL + ключ (прокси, свой сервер, вендорные endpoint). Модели грузятся с endpoint после ключа и URL.",
            .helpCloudStats: "Статистика токенов внизу API Providers: последняя операция и итоги по выбранной модели. Reset Stats сбрасывает счётчики.",
            .helpPolishTitle: "Доводка, MLX и промпты",
            .helpPolishIntro: "Транскрибация превращает речь в текст. Доводка переписывает этот текст. Это разные модели и разные настройки.",
            .helpPolishEngines: "Движки: Polishing Disabled (только Raw) · Quick Local Cleanup (правила, без LLM, офлайн) · локальная MLX · облако из API Providers. Провайдер/модель можно сменить и в toolbar заметки, и в Settings.",
            .helpPolishMLX: "Настройки → Доводка: скачивание из каталога или Scan for Local Models на диске. Лучше instruct без reasoning; thinking-модели медленнее и могут «протекать» рассуждениями в заметку.",
            .helpPolishPrompts: "Настройки → Промпты: Вариант 1, Вариант 2 и Markdown. В каждом промпте должен остаться плейсхолдер \(PromptTemplate.transcriptionPlaceholder). Reset возвращает встроенный шаблон.",
            .helpMoreTitle: "Глоссарий, импорт и перевод",
            .helpMoreGlossary: "Glossary — локальный словарь предпочтительных написаний и терминов (источник → перевод, варианты, категории). Whisper не обучается; текст переписывается после распознавания/перевода. Включите, добавьте записи или выделите текст в заметке → Add to Glossary. Экспортируйте JSON перед Clear. Auto Translation Language здесь поддерживает режим буквы на HUD, если в Hotkey язык = Auto.",
            .helpMoreImport: "Импорт аудио или перетаскивание файла на окно создаёт транскрибированную заметку активной речевой моделью.",
            .helpMoreTranslate: "Перевод из главного окна или через плавающую панель Option+1 (Option+2 показывает только результат): selection / буфер / живая диктовка → провайдер + модель + целевой язык. Перевод меняет язык намеренно; Варианты 1/2 язык сохраняют. Режим буквы на HUD для не-English цели тоже использует translation engine.",
            .helpPrivacyTitle: "Приватность, хранение и диагностика",
            .helpPrivacyLocal: "Whisper, Quick Local Cleanup и локальная MLX-доводка остаются на этом Mac. Записи лежат в локальных папках данных приложения.",
            .helpPrivacyCloud: "Облачная доводка и перевод отправляют текст (и промпты) выбранному провайдеру. Для приватности используйте локальные движки.",
            .helpPrivacyClear: "«Очистить все» безвозвратно удаляет все заметки и очищает папку записей, включая «осиротевшее» аудио после прерванных сессий. Сначала экспортируйте важное.",
            .helpPrivacyLogs: "Общие → Экспортировать системные логи — диагностический файл. Debug-уровень только на время отладки. Тема, масштаб UI, размер/звуки HUD и язык интерфейса — тоже в Общих.",
            .helpTipsTitle: "Частые советы",
            .helpTipEnglish: "Нужен English из других языков? Мультиязычный Whisper + буква E на HUD (или Язык транскрибации = English) + Large v3 Full.",
            .helpTipNonEnglish: "Нужен Spanish/Russian/… на выходе? Задайте язык в Hotkey, переключите HUD на букву и держите активным облачный или MLX-движок доводки.",
            .helpTipDisk: "Мало места? Удалите ненужные Whisper-модели в Локальных моделях; «Очистить все» — только если готовы стереть заметки и оставшиеся .caf.",
            .helpTipStuck: "Hotkey или печать «зависли»? Проверьте, что hotkey включён, микрофон работает в главном окне, Accessibility выдан для Type mode, затем Refresh status. Если не помогло — экспортируйте логи.",
            // —— Legacy-ключи ——
            .helpWelcomeTitle: "Справка SmartScribe",
            .helpWelcomeBody: "Диктуйте в любом приложении на Mac. Речь распознаётся локально через Whisper; текст можно оставить как есть, почистить или переписать — и скопировать или впечатать туда, где вы работали.",
            .helpQuickStart: "С чего начать (первые 5 минут)",
            .helpRecordStep: "Кликните в другое приложение → hotkey (по умолчанию Option+S) → говорите → снова hotkey. Красный HUD — запись, зелёный — обработка.",
            .helpVariantsStep: "Raw — транскрипт. Вариант 1 — лёгкая чистка. Вариант 2 — сильная переработка. Markdown структурирует отполированный текст.",
            .helpCopyStep: "Копируйте текущую вкладку, все заметки из сайдбара или доставляйте через hotkey Clipboard / Type into Active App.",
            .helpRecordingTitle: "Overlay HUD",
            .helpHUDStep: "HUD: [A|буква] волна [R|1|2]. Слева A↔E, справа R→1→2. Тащите куда угодно; размер/звук — Общие → Оверлей.",
            .helpOfflineTranscription: "Локальные модели транскрибации",
            .helpOfflineModelStep: "Настройки → Локальные модели: скачайте WhisperKit. Для качества и English translate предпочтителен Large v3 Full.",
            .helpOfflineActivateStep: "Нажмите «Использовать» у загруженной модели. «Удалить» освобождает место. Fallback: Apple Speech.",
            .helpImportTitle: "Импорт и перевод",
            .helpImportStep: "Импорт аудио или перетаскивание файла создаёт новую транскрибированную заметку.",
            .helpTranslateStep: "Окно перевода: выделение, буфер или короткая запись → провайдер + целевой язык.",
            .helpPolishingProviders: "Движки доводки",
            .helpPolishingProviderStep: "Disabled, Quick Local Cleanup, локальный MLX или облачный API из API Providers.",
            .helpPromptsStep: "Настройки → Промпты: Вариант 1, Вариант 2 и Markdown. Сохраняйте плейсхолдер транскрипта.",
            .helpHotkeyStep: "Настройки → Горячая клавиша: включите Option+S, выберите Target и Mode; Accessibility нужен только для печати в приложения.",
            .helpPermissionsTitle: "Разрешения",
            .helpMicrophoneStep: "Микрофон нужен для записи в окне и через HUD.",
            .helpAccessibilityStep: "Accessibility нужен только для Type into Active App.",
            .helpPermissionRefreshStep: "Если печать не работает — обновите Accessibility в настройках hotkey или откройте System Settings.",
