            .onboardingAccessibility: "Универсальный доступ — для вставки текста в другие приложения и перехвата горячих клавиш.",
            .onboardingModesTitle: "Четыре режима работы",
            .onboardingModesBody: "Главное окно для заметок и редактирования. Hotkey + HUD для диктовки в любом приложении. Option+1 — полная панель перевода, Option+2 — быстрое окно только с результатом.",
            .onboardingGlossaryTitle: "Глоссарий",
            .onboardingGlossaryBody: "Создайте глоссарий для %@, чтобы улучшить точность имён и специальных терминов.",
            .onboardingGlossaryExplanation: "Глоссарий помогает SmartScribe правильно писать имена, специальные термины, сокращения и слова, которые часто распознаются с ошибками. Добавьте правильное написание и распространённые варианты — после транскрибации или перевода SmartScribe автоматически заменит их на выбранную вами форму. Глоссарий хранится на этом Mac, и его можно изменить в любой момент в Настройках.",
            .onboardingThemeTitle: "Настройте под себя",
