            .googleAPIBody: "El audio se sube a Google y primero se convierte en una transcripción Raw ligeramente depurada con el modelo Gemini elegido. Raw está disponible en el HUD. Si eliges el destino 1 o 2, su prompt de Ajustes → Prompts se ejecuta después como una solicitud de texto separada.",
