            .accessibilityPermission: "Permiso de accesibilidad",
            .accessibilityTrusted: "Concedido",
            .accessibilityNotTrusted: "No concedido",
            .accessibilityPermissionDescription: "Solo se necesita para Escribir en la app activa. El modo Portapapeles no requiere permiso de accesibilidad.",
            .requestAccessibilityPermission: "Solicitar permiso",
            .openAccessibilitySettings: "Abrir ajustes de accesibilidad",
            .refreshPermissionStatus: "Actualizar estado",
            .helpHeroTitle: "Ayuda de SmartScribe",
            .helpHeroSubtitle: "Dicta en cualquier parte de tu Mac. La voz se transcribe en el dispositivo con Whisper; el texto puede quedar tal cual, limpiarse o reescribirse, y luego copiarse o escribirse en la app que estabas usando.",
            .helpStartTitle: "Empieza aquí (primeros 5 minutos)",
            .helpStart1: "Permite el micrófono cuando macOS lo pida. Sin él, la grabación no puede comenzar.",
            .helpStart2: "Abre Ajustes → Modelos locales, descarga un modelo de Whisper (Large v3 Full es la mejor opción multiuso) y pulsa Usar.",
            .helpStart3: "Abre Ajustes → Atajo de teclado y activa los atajos. Primary (por defecto Option+S) es el dictado. El atajo de la ventana de traducción (por defecto Option+1) abre el panel de traducción completo; Traducción rápida (por defecto Option+2) muestra solo el resultado; Abrir ajustes (por defecto Option+~) abre las preferencias. Para el dictado, elige Destino (Raw / Variante 1 / Variante 2) y Modo (Portapapeles o Escribir en la app activa).",
            .helpStart4: "Opcional: en Proveedores de API añade una clave en la nube (puedes guardar varias por proveedor), elige un modelo, marca favoritos y pulsa Usar para pulido, o instala un modelo MLX local. Sin un motor de pulido/traducción, Variante 1/2 y el idioma forzado distinto del inglés no mejorarán el texto.",
            .helpStart5: "Dictado: pon el foco en cualquier app → Option+S → habla → Option+S de nuevo (HUD rojo = grabando, verde = procesando). Traducción instantánea: selecciona texto en otra app → Option+1 → el panel flotante captura la selección/portapapeles y traduce (Option+2 muestra solo el resultado).",
            .helpModesTitle: "Cuatro formas de trabajar",
            .helpModeWindowTitle: "Ventana principal",
            .helpModeWindowBody: "Un cuaderno para tus notas: graba o importa audio, revisa Raw / Variante 1 / Variante 2, pule, traduce y copia. Ideal cuando quieres editar y conservar el historial.",
            .helpModeHotkeyTitle: "Atajo + HUD superpuesto",
            .helpModeHotkeyBody: "Quédate en otra app. El atajo principal (Option+S) graba con el HUD flotante: modo de idioma (A / letra) y destino de salida (R / 1 / 2). Con el HUD visible, desplázate para cambiar el proveedor de pulido y haz clic derecho en un proveedor para elegir un modelo específico. No roba el foco del teclado mientras dictas.",
            .helpModeFloatTitle: "Ventana de traducción flotante",
            .helpModeFloatBody: "El atajo de la ventana de traducción (por defecto Option+1) abre un panel de traducción siempre visible. Captura el texto seleccionado de la app activa (con un Command-C rápido), rellena el Original y puede traducir al instante. Úsalo cuando necesites cambiar de idioma sin un dictado completo.",
            .helpWindowTitle: "Ventana principal",
            .helpWindowBody: "Izquierda: lista de notas. Derecha: la nota seleccionada — información del audio, menús de proveedor/modelo de pulido, pestañas de texto y la barra de acciones.",
            .helpWindowNotes: "Barra lateral: selecciona una nota, Copiar todo o Borrar todo (permanente: elimina todas las notas y los archivos de grabación sobrantes del disco).",
            .helpWindowTabs: "Pestañas: Raw = transcripción pura. Variante 1 = limpieza ligera (muletillas, repeticiones). Variante 2 = reescritura más profunda para mayor claridad. Usa la acción Markdown en una pestaña pulida para estructurar el texto. Las ranuras de prompt D/1/2/3/4 cambian qué prompt personalizado está activo para esa variante.",
            .helpWindowActions: "Barra inferior: Grabar / Detener, Nota en blanco, Importar audio (o arrastra un archivo a la ventana), Traducir, Pulir, Copiar. Ajustes abre las Preferencias.",
            .helpWindowPolishingMenus: "Sobre el editor puedes cambiar el Proveedor de pulido (Desactivado / Limpieza rápida / MLX local / nube) y el Modelo de pulido (modelos del proveedor en la nube seleccionado, o tarjetas MLX locales). Equivale a Ajustes → Proveedores de API / Pulido sin salir de la nota.",
            .helpHUDTitle: "HUD superpuesto (la cápsula flotante)",
            .helpHUDIntro: "Al pulsar el atajo global aparece una pequeña cápsula flotante sobre todas las apps. No es una ventana normal: permanece encima, no roba el foco del teclado y muestra solo el estado, no la transcripción completa.",
            .helpHUDAnatomy: "Distribución de izquierda a derecha: (1) botón de idioma · (2) forma de onda en vivo en el centro · (3) botón de destino de salida. En pantalla suele verse así: [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "La forma de onda central se pone roja mientras el micrófono graba. Habla mientras esté roja.",
            .helpHUDColorGreen: "Al detener (atajo de nuevo), la forma de onda se pone verde: SmartScribe está transcribiendo, puliendo si hace falta y entregando el texto. Espera a que el HUD se oculte.",
            .helpHUDLeftTitle: "Botón izquierdo — modo de idioma (A ↔ letra)",
            .helpHUDLeftA: "A = Auto. SmartScribe conserva / detecta automáticamente el idioma en que hablaste. Sin traducción forzada. Úsalo cuando quieras la transcripción en el mismo idioma que tu voz.",
            .helpHUDLeftLetter: "Una letra en lugar de A significa “forzar idioma de destino”. La letra es la inicial del nombre inglés de ese idioma: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German, etc. La letra que aparece depende de Ajustes → Atajo → Idioma de transcripción (o del Idioma de traducción automática del Glosario si el Atajo está en Auto).",
            .helpHUDLeftTap: "Toca una vez el botón izquierdo para cambiar A → letra (destino forzado) y otra vez para cambiar letra → A. La elección se recuerda para la próxima sesión.",
            .helpHUDRightTitle: "Botón derecho — destino de salida (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. Entrega la transcripción simple sin pulido de Variante 1 / Variante 2. Es la vía más rápida; aun así puede usar la traducción al inglés de Whisper cuando el botón izquierdo es E.",
            .helpHUDRightCycle: "1 = Variante 1 (limpieza ligera). 2 = Variante 2 (reescritura más profunda). Requieren un motor de pulido activo (nube o MLX local). Elegir 1 o 2 reactiva el pulido si estaba desactivado.",
            .helpHUDRightTap: "Toca el botón derecho para alternar R → 1 → 2 → R. La selección se convierte en el nuevo Destino por defecto en los ajustes del Atajo para futuros dictados.",
            .helpHUDControlLanguage: "Izquierda: A = auto / mismo idioma que la voz. Letra (E, S, R, …) = forzar ese idioma de destino. Toca para alternar A ↔ letra.",
            .helpHUDControlTarget: "Derecha: R = transcripción Raw, 1 = Variante 1, 2 = Variante 2. Toca para alternar R → 1 → 2 → R.",
            .helpHUDDrag: "Arrastrar: haz clic y mantén pulsado en cualquier parte de la cápsula (no solo en los botones) y muévela a cualquier lugar de cualquier pantalla. Ponla cerca de una esquina, sobre el dock o junto a la app en la que escribes, donde prefieras.",
            .helpHUDSize: "Tamaño y transparencia: Ajustes → General → HUD superpuesto. El control de Tamaño escala toda la cápsula (y cuántas barras del espectro ves). La transparencia atenúa el fondo de cristal para que el contenido del escritorio se vea más o menos a través.",
            .helpHUDSound: "Sonidos: en la misma sección General → HUD superpuesto. Activa “Reproducir sonido al iniciar/terminar”, ajusta el Volumen y usa Probar sonidos del HUD para preescuchar sin grabar. Las señales suenan al empezar la grabación y al terminar el procesamiento.",
            .helpHUDSettingsPath: "Todo el aspecto del HUD está en Ajustes → General → HUD superpuesto (tamaño, transparencia, sonido, volumen). La posición se guarda automáticamente tras arrastrar.",
            .helpHUDPosition: "Tras arrastrar el HUD, SmartScribe recuerda ese punto y lo reabre ahí la próxima vez.",
            .helpHUDDuration: "No hay un límite artificial corto sobre cuánto puedes hablar. Sigue hablando mientras la forma de onda esté roja; pulsa el atajo de nuevo al terminar.",
            .helpLangTitle: "Modos de idioma en detalle",
            .helpLangIntro: "El control de idioma es el botón izquierdo del HUD más Ajustes → Atajo → Idioma de transcripción. Funcionan juntos.",
            .helpLangAuto: "A (auto): la transcripción se queda en el idioma en que hablaste. Ideal para notas en tu idioma nativo sin traducción.",
            .helpLangForced: "Letra (destino forzado): tras el reconocimiento de voz, SmartScribe apunta a un idioma de salida concreto. Habla ruso y obtén inglés; habla inglés y obtén español, según el destino configurado.",
            .helpLangEnglishNote: "Destino inglés + Whisper multilingüe: Raw usa la traducción al inglés integrada de Whisper en el dispositivo (rápida). Prefiere Large v3 Full por calidad; Turbo es más ligero pero menos fiable con voz larga o mixta.",
            .helpLangOtherNote: "Cualquier destino distinto del inglés siempre necesita un LLM tras Whisper (nube o MLX local). Sin una vía de pulido activa, el español/ruso/… forzado no puede convertir el idioma.",
            .helpLangWhere: "Configura el destino en Atajo → Idioma de transcripción (English, Spanish, Russian, …). Si está en Auto, el modo letra usa Glosario → Idioma de traducción automática y, si no, recurre al inglés. La letra del HUD se actualiza según esa elección.",
            .helpModelsTitle: "Modelos de transcripción locales",
            .helpModelsIntro: "Ajustes → Modelos locales gestiona los modelos WhisperKit Core ML que convierten audio en texto en Apple Silicon. Esto es independiente de los modelos de pulido.",
            .helpModelsCatalog: "Solo inglés (Small/Medium .en): rápido si solo hablas inglés. Multilingüe Small/Medium: multiidioma más ligero. Large v3 Turbo (~1.6 GB): modelo grande y rápido. Large v3 Full (~3 GB, mejor calidad): recomendado por defecto por precisión y traducción al inglés.",
            .helpModelsRecommend: "Para idiomas mixtos e inglés forzado (letra E del HUD), usa un modelo multilingüe, idealmente Large v3 Full. Los modelos solo inglés no pueden traducir de forma nativa otros idiomas al inglés.",
            .helpModelsUse: "Descargar → Usar (solo uno activo). Eliminar borra los archivos de este Mac. No hay respaldo de Apple Speech: elige Whisper local (con un modelo descargado) o Nube · Google Gemini (requiere clave API de Google).",
            .helpHotkeyTitle: "Ajustes del atajo",
            .helpHotkeyIntro: "Ajustes → Atajo de teclado activa cuatro atajos globales independientes. Activa “Activar atajo” antes de que cualquiera de ellos funcione.",
            .helpHotkeyPrimary: "Primary (por defecto Option+S (⌥S)): inicia/detiene el dictado en el HUD superpuesto. La primera pulsación graba (rojo), la segunda procesa (verde) y entrega Raw / Variante 1 / Variante 2.",
            .helpHotkeySecondary: "Ventana de traducción (por defecto Option+1): abre el panel de traducción flotante completo. No es un atajo de grabación: captura la selección/portapapeles y traduce. La flecha de restablecer devuelve Option+1.",
            .helpHotkeyTertiary: "Traducción rápida (por defecto Option+2): abre una ventana mínima de solo lectura con el resultado traducido. Pulsa el atajo de nuevo o Escape para cerrarla.",
            .helpHotkeySettings: "Abrir ajustes (por defecto Option+~): abre la ventana de ajustes de SmartScribe desde cualquier lugar, para cambiar de modelo o idioma sin salir de tu app.",
            .helpModeQuickTitle: "Ventana de traducción rápida",
            .helpModeQuickBody: "El tercer atajo (por defecto Option+2) abre una ventana mínima siempre visible que muestra solo el resultado traducido, sin panel de origen ni botones. Léelo y pulsa Escape para cerrarla. Para editar o volver a traducir, usa la ventana de traducción completa.",
            .helpFloatQuick: "Dos ventanas de traducción: la Ventana de traducción flotante (Option+1) es el panel completo con texto de origen, menús de proveedor/modelo y controles; la Traducción rápida (Option+2) es una ventana mínima de solo lectura que muestra solo el resultado. Usa la Traducción rápida cuando solo necesites leer una traducción.",
            .helpHotkeyTarget: "Destino del dictado: qué texto se entrega tras la grabación — Raw, Variante 1 o Variante 2. La misma elección que el botón derecho del HUD (R / 1 / 2).",
            .helpHotkeyMode: "Modo del dictado: Portapapeles copia el resultado para que lo pegues; Escribir en la app activa lo inserta en el campo que estaba en foco al empezar la grabación.",
            .helpHotkeyAccess: "Escribir en la app activa necesita permiso de Accesibilidad (la misma página de ajustes). El modo Portapapeles y la Ventana de traducción flotante no requieren Accesibilidad para pegar en el panel, pero capturar texto de otras apps con Command-C funciona mejor cuando la app es de confianza.",
            .helpFloatTitle: "Ventana de traducción flotante",
            .helpFloatIntro: "Un panel utilitario redimensionable y siempre visible (SmartScribe Translation), independiente del cuaderno principal. Ideal para un cambio rápido de idioma mientras sigues en el navegador, el correo o el chat.",
            .helpFloatHotkey: "Ábrelo con el atajo de la ventana de traducción (Ajustes → Atajo de teclado → Ventana de traducción, por defecto Option+1). También puedes abrir Traducir desde la barra inferior de la ventana principal; el panel flotante comparte la misma interfaz.",
            .helpFloatCapture: "Al abrirlo, SmartScribe envía brevemente Command-C a la app en primer plano para copiar la selección; luego prefiere la selección de la nota si estás dentro de SmartScribe y, si no, el texto del portapapeles. Si se capturó algo y hay un proveedor de traducción configurado, la traducción empieza automáticamente.",
            .helpFloatPanel: "Dentro del panel: elige Proveedor y Modelo, define el Idioma de destino, edita el Original, ejecuta Traducir / Traducir de nuevo o graba un clip corto para traducir. El panel sigue flotando sobre otras apps y puede redimensionarse.",
            .helpFloatFavorites: "La lista de modelos de la interfaz de traducción prefiere los modelos que marcaste como favoritos en Ajustes → Proveedores de API (selector con búsqueda ★). Si no tienes favoritos para ese proveedor, se muestra el modelo seleccionado actualmente.",
            .helpFloatDoubleClick: "Haz doble clic en el área de texto Original (origen) para pegar del portapapeles y traducir al instante, útil tras copiar texto tú mismo.",
            .helpFloatEscape: "Pulsa Escape o el botón de cerrar para ocultar el panel flotante. Cerrarlo no cierra SmartScribe.",
            .helpCloudTitle: "Proveedores de API en la nube",
            .helpCloudIntro: "Ajustes → Proveedores de API configura LLM en la nube para pulido y traducción, no para el reconocimiento de voz de Whisper. Distribución: desplegable de proveedor arriba, tarjeta de detalles y luego estadísticas de uso.",
            .helpCloudProviders: "Orden del desplegable: Google Gemini → OpenAI → Qwen → OpenRouter → Personalizado. (Anthropic no aparece en la interfaz actual.) La insignia Activo marca el motor usado para el pulido.",
            .helpCloudConfigure: "Selecciona un proveedor, introduce la(s) clave(s), abre Explorar modelos (hoja con búsqueda), elige un modelo de texto y pulsa Usar para pulido. Obtener clave API abre la consola del proveedor cuando está disponible. Las fichas de modelo muestran la longitud de contexto y, si existen, los precios de entrada/salida.",
            .helpCloudKeys: "Varias claves API: cada proveedor puede guardar hasta 10 claves (Añadir clave). El icono del ojo muestra/oculta una clave. La primera clave no vacía se usa para las peticiones; las adicionales ayudan a rotarlas o a separar claves personales y de trabajo.",
            .helpCloudFavorites: "En el selector de modelos, marca modelos como favoritos (★). Los favoritos se ordenan arriba y se prefieren en el menú de modelos de la Ventana de traducción flotante. Los favoritos se guardan en este Mac.",
            .helpCloudOpenRouter: "OpenRouter: saldo de cuenta en vivo (USD restantes con color), catálogo con búsqueda con contexto y precios de $/M tokens, y control de actualización. Comprueba el saldo antes de sesiones largas.",
            .helpCloudBudget: "El control de presupuesto de OpenRouter es una ayuda de límite flexible personal en Ajustes (una guía visual de cuánto piensas gastar); no corta la API por sí solo. Vigila el banner de saldo real para ver el crédito restante.",
            .helpCloudCustom: "Personalizado: cualquier URL base + clave compatible con OpenAI (proxies, autoalojados o endpoints de proveedor). Los modelos se cargan desde ese endpoint tras configurar la clave y la URL.",
            .helpCloudStats: "Estadísticas de uso al final de Proveedores de API: tokens de la última transacción y totales del modelo seleccionado. Restablecer estadísticas borra esos contadores.",
            .helpPolishTitle: "Pulido, MLX y prompts",
            .helpPolishIntro: "La transcripción convierte la voz en texto. El pulido reescribe ese texto. Usan modelos y ajustes distintos.",
            .helpPolishEngines: "Motores: Pulido desactivado (solo Raw) · Limpieza local rápida (reglas, sin LLM, totalmente offline) · Modelo MLX local · Proveedor en la nube desde Proveedores de API. Puedes cambiar proveedor/modelo desde la barra de la nota principal y desde Ajustes.",
            .helpPolishMLX: "Ajustes → Pulido: descarga modelos del catálogo o Busca modelos locales en el disco. Prefiere modelos instruct sin razonamiento; los modelos de razonamiento son más lentos y pueden filtrar su cadena de pensamiento en la nota.",
            .helpPolishPrompts: "Ajustes → Prompts: edita Variante 1, Variante 2 y Markdown. Cada prompt debe conservar el marcador \(PromptTemplate.transcriptionPlaceholder). Restablecer recupera la plantilla integrada.",
            .helpMoreTitle: "Glosario, importación y traducción",
            .helpMoreGlossary: "El Glosario es un diccionario local de grafías y términos preferidos (origen → traducción, variantes, categorías). No reentrena Whisper; reescribe el texto tras el reconocimiento/traducción. Actívalo, añade entradas o selecciona texto en una nota → Añadir al glosario. Exporta JSON antes de Borrar. El Idioma de traducción automática de aquí respalda el modo letra del HUD cuando el idioma del Atajo es Auto.",
            .helpMoreImport: "Importa audio o suelta un archivo en la ventana para crear una nota transcrita con el modelo de voz activo.",
            .helpMoreTranslate: "Traduce desde la ventana principal o con el panel flotante Option+1 (Option+2 muestra solo el resultado): selección / portapapeles / dictado en vivo → proveedor + modelo + idioma de destino. La traducción cambia el idioma a propósito; Variante 1/2 mantienen el mismo idioma. El modo letra del HUD usa el motor de traducción cuando el destino no es inglés.",
            .helpPrivacyTitle: "Privacidad, almacenamiento y diagnóstico",
            .helpPrivacyLocal: "La transcripción de Whisper, la Limpieza local rápida y el pulido MLX local permanecen en este Mac. Las grabaciones se guardan en las carpetas de datos locales de la app.",
            .helpPrivacyCloud: "El pulido en la nube y la traducción en la nube envían tu texto (y prompts) al proveedor seleccionado. Usa motores locales cuando las notas deban seguir siendo privadas.",
            .helpPrivacyClear: "Borrar todo elimina permanentemente todas las notas y vacía la carpeta de grabaciones, incluido el audio huérfano de sesiones interrumpidas. Exporta antes si te importa el contenido.",
            .helpPrivacyLogs: "General → Exportar registros del sistema para obtener un archivo de diagnóstico. Usa el nivel de registro Debug solo al resolver problemas. El tema, la escala de la interfaz, el tamaño/sonidos del HUD y el idioma de la interfaz también están en General.",
            .helpTipsTitle: "Consejos habituales",
            .helpTipEnglish: "¿Necesitas salida en inglés desde otros idiomas? Whisper multilingüe + letra E del HUD (o Idioma de transcripción = English) + Large v3 Full.",
            .helpTipNonEnglish: "¿Necesitas salida en español/ruso/…? Configura ese idioma en el Atajo, cambia el HUD a la letra y mantén activo un motor de pulido en la nube o MLX.",
            .helpTipDisk: "¿Disco lleno de modelos o grabaciones? Elimina los modelos de Whisper que no uses en Modelos locales; usa Borrar todo solo cuando quieras eliminar notas y archivos .caf sobrantes.",
            .helpTipStuck: "¿Atajo o escritura atascados? Confirma que el Atajo está activado, que el micrófono funciona en la ventana principal y que la Accesibilidad está concedida para el modo Escribir; luego prueba Actualizar estado. Exporta los registros si sigue fallando.",
            .helpWelcomeTitle: "Ayuda de SmartScribe",
            .helpWelcomeBody: "Dicta en cualquier parte de tu Mac. La voz se transcribe en el dispositivo con Whisper; el texto puede quedar tal cual, limpiarse o reescribirse, y luego copiarse o escribirse en la app que estabas usando.",
            .helpQuickStart: "Empieza aquí (primeros 5 minutos)",
            .helpRecordStep: "Haz clic en otra app → pulsa el atajo (por defecto Option+S) → habla → pulsa de nuevo para detener. HUD rojo = grabando, verde = procesando.",
            .helpVariantsStep: "Raw es la transcripción. Variante 1 es una limpieza ligera. Variante 2 es una reescritura más profunda. Markdown estructura el texto pulido.",
            .helpCopyStep: "Copia la pestaña actual, Copiar todas las notas desde la barra lateral, o entrega mediante el atajo Portapapeles / Escribir en la app activa.",
            .helpRecordingTitle: "HUD superpuesto",
            .helpHUDStep: "HUD: [A|letra] forma de onda [R|1|2]. Toca a la izquierda A↔E, a la derecha R→1→2. Arrastra a cualquier sitio; tamaño/sonido en General → HUD superpuesto.",
            .helpOfflineTranscription: "Modelos de transcripción locales",
            .helpOfflineModelStep: "Ajustes → Modelos locales: descarga modelos WhisperKit. Prefiere Large v3 Full por calidad y traducción al inglés.",
            .helpOfflineActivateStep: "Pulsa Usar en un modelo descargado. Eliminar libera espacio en disco. Respaldo: Apple Speech.",
            .helpImportTitle: "Importación y traducción",
            .helpImportStep: "Importa audio o arrastra un archivo a la ventana para transcribirlo como una nota nueva.",
            .helpTranslateStep: "Modal de traducción: selección, portapapeles o grabación corta → proveedor + idioma de destino.",
            .helpPolishingProviders: "Motores de pulido",
            .helpPolishingProviderStep: "Desactivado, Limpieza local rápida, MLX local o un proveedor de API en la nube desde Proveedores de API.",
            .helpPromptsStep: "Ajustes → Prompts para Variante 1, Variante 2 y Markdown. Conserva el marcador de transcripción.",
            .helpHotkeyStep: "Ajustes → Atajo de teclado: activa Option+S, elige Destino y Modo, y concede Accesibilidad solo para escribir en apps.",
            .helpPermissionsTitle: "Permisos",
            .helpMicrophoneStep: "El micrófono se necesita para grabar en la ventana y mediante el HUD.",
            .helpAccessibilityStep: "La Accesibilidad solo se necesita para Escribir en la app activa.",
            .helpPermissionRefreshStep: "Si la escritura falla, actualiza la Accesibilidad en los ajustes del Atajo o abre Ajustes del Sistema.",
            .helpPrivacyLocalStep: "Whisper local y el pulido local permanecen en el dispositivo.",
            .helpLogsStep: "General → Exportar registros del sistema cuando necesites un archivo de diagnóstico.",
