            .onboardingGlossaryTitle: "Glosario",
            .onboardingGlossaryBody: "Crea un glosario para %@ para mejorar la precisión de nombres y términos especiales.",
            .onboardingGlossaryExplanation: "Un glosario ayuda a SmartScribe a escribir nombres, términos especializados, abreviaturas y palabras que suele reconocer mal exactamente como prefieres. Añade la escritura correcta y sus variantes habituales; después de transcribir o traducir, SmartScribe sustituirá automáticamente esas variantes por tu forma preferida. El glosario permanece en este Mac y puedes editarlo cuando quieras en Ajustes.",
