            .localModelsHint: "Lade unten ein Whisper-Modell herunter und drücke Verwenden — oder wechsle zu Cloud · Google Gemini. Apple Speech wird nicht verwendet.",
            .googleAPI: "Google API",
            .geminiModel: "Gemini-Modell",
            .googleAPIBody: "Audio wird zu Google hochgeladen und mit dem gewählten Gemini-Modell zuerst in ein leicht bereinigtes Raw-Transkript umgewandelt. Raw ist im HUD verfügbar. Bei Ziel 1 oder 2 wird der jeweilige Prompt aus Einstellungen → Prompts anschließend als separater Textdurchlauf ausgeführt.",
            .scanForLocalModels: "Nach lokalen Modellen suchen",
            .scanForLocalModelsBody: "Durchsucht ~/Documents, ~/Downloads und den HuggingFace-Cache nach MLX-Modellen",
