            .scan: "Suchen",
            .skippedUnsupportedModels: "%@ nicht unterstützte Modelle übersprungen",
            .localPolishingSupportHint: "Für lokales Polieren werden nur MLX-Modelle zur Texterzeugung mit kompatiblem Tokenizer unterstützt.",
            .markdown: "Markdown",
            .remove: "Entfernen",
