            .copied: "Kopiert!",
            .defaultModelName: "Standard",
            .removeCustomModelHelp: "Entfernt nur aus der Liste. Dateien auf der Festplatte werden nicht gelöscht.",
            .noNewModelsFound: "Keine neuen Modelle gefunden",
