            .selectedModel: "Ausgewähltes Modell",
            .resetStats: "Statistiken zurücksetzen",
            .noUsageData: "Noch keine Nutzungsdaten.",
            .accessibilityPermission: "Bedienungshilfen-Berechtigung",
            .accessibilityTrusted: "Erteilt",
            .accessibilityNotTrusted: "Nicht erteilt",
            .accessibilityPermissionDescription: "Nur für „In aktive App eingeben“ erforderlich. Der Zwischenablage-Modus benötigt keine Bedienungshilfen-Berechtigung.",
            .requestAccessibilityPermission: "Berechtigung anfordern",
            .openAccessibilitySettings: "Bedienungshilfen-Einstellungen öffnen",
            .refreshPermissionStatus: "Status aktualisieren",
            .helpHeroTitle: "SmartScribe-Hilfe",
            .helpHeroSubtitle: "Diktiere überall auf deinem Mac. Sprache wird mit Whisper auf dem Gerät transkribiert; Text kann raw bleiben, bereinigt oder umgeschrieben werden — und wird dann kopiert oder in die genutzte App eingegeben.",
            .helpStartTitle: "Hier starten (erste 5 Minuten)",
            .helpStart1: "Erlaube das Mikrofon, wenn macOS danach fragt. Ohne es kann die Aufnahme nicht starten.",
            .helpStart2: "Öffne Einstellungen → Lokale Modelle, lade ein Whisper-Modell herunter (Large v3 Full ist die beste Allround-Wahl) und drücke Verwenden.",
            .helpStart3: "Öffne Einstellungen → Kurzbefehl und schalte Kurzbefehle ein. Primär (Standard Option+S) ist Diktat. Der Übersetzungsfenster-Kurzbefehl (Standard Option+1) öffnet das vollständige schwebende Übersetzungspanel; Schnellübersetzung (Standard Option+2) zeigt nur das Ergebnis; Einstellungen öffnen (Standard Option+~) öffnet die Einstellungen. Wähle fürs Diktat Ziel (Raw / Variante 1 / Variante 2) und Modus (Zwischenablage oder In aktive App eingeben).",
            .helpStart4: "Optional: Füge unter API-Anbieter einen Cloud-Schlüssel hinzu (du kannst mehrere pro Anbieter speichern), wähle ein Modell, markiere Favoriten und nutze Verwenden für Polierung — oder installiere ein lokales MLX-Modell. Ohne Polier-/Übersetzungs-Engine verbessern Variante 1/2 und erzwungene Nicht-Englisch-Sprache den Text nicht.",
            .helpStart5: "Diktat: beliebige App fokussieren → Option+S → sprechen → erneut Option+S (rotes HUD = Aufnahme, grün = Verarbeitung). Sofortübersetzung: Text anderswo auswählen → Option+1 → das schwebende Panel erfasst Auswahl/Zwischenablage und übersetzt (Option+2 zeigt nur das Ergebnis).",
            .helpModesTitle: "Vier Arbeitsweisen",
            .helpModeWindowTitle: "Hauptfenster",
            .helpModeWindowBody: "Ein Notizbuch für Notizen: Audio aufnehmen oder importieren, Raw / Variante 1 / Variante 2 prüfen, polieren, übersetzen und kopieren. Ideal, wenn du bearbeiten und Verlauf behalten möchtest.",
            .helpModeHotkeyTitle: "Kurzbefehl + Overlay-HUD",
            .helpModeHotkeyBody: "Bleibe in einer anderen App. Der primäre Kurzbefehl (Option+S) nimmt mit dem schwebenden HUD auf: Sprachmodus (A / Buchstabe) und Ausgabeziel (R / 1 / 2). Während das HUD sichtbar ist, wechselst du per Scrollen den Polishing-Anbieter und per Rechtsklick auf einen Anbieter wählst du ein bestimmtes Modell. Stiehlt beim Diktieren nicht den Tastaturfokus.",
            .helpModeFloatTitle: "Schwebendes Übersetzungsfenster",
            .helpModeFloatBody: "Der Übersetzungsfenster-Kurzbefehl (Standard Option+1) öffnet ein immer sichtbares Übersetzungspanel. Es erfasst ausgewählten Text aus der aktiven App (per kurzem Command-C), füllt Original und kann sofort übersetzen. Nützlich für einen Sprachwechsel ohne volles Diktat.",
            .helpWindowTitle: "Hauptfenster",
            .helpWindowBody: "Links: Notizliste. Rechts: die ausgewählte Notiz — Audio-Info, Menüs für Polier-Anbieter/-Modell, Text-Tabs und Aktionsleiste.",
            .helpWindowNotes: "Seitenleiste: Notiz auswählen, Alle kopieren oder Alle löschen (dauerhaft: löscht jede Notiz und verbliebene Aufnahmedateien auf der Festplatte).",
            .helpWindowTabs: "Tabs: Raw = reine Transkription. Variante 1 = leichte Bereinigung (Füllwörter, Wiederholungen). Variante 2 = stärkere Umschreibung für Klarheit. Nutze die Markdown-Aktion auf einem polierten Tab, um den Text zu strukturieren. Prompt-Slots D/1/2/3/4 wechseln, welcher eigene Prompt für diese Variante aktiv ist.",
            .helpWindowActions: "Untere Leiste: Aufnehmen / Stopp, Leere Notiz, Audio importieren (oder Datei ins Fenster ziehen), Übersetzen, Polieren, Kopieren. Einstellungen öffnet die Einstellungen.",
            .helpWindowPolishingMenus: "Über dem Editor kannst du Polier-Anbieter (Deaktiviert / Schnellbereinigung / lokales MLX / Cloud) und Polier-Modell (Modelle des gewählten Cloud-Anbieters oder lokale MLX-Karten) wechseln. Das entspricht Einstellungen → API-Anbieter / Polierung, ohne die Notiz zu verlassen.",
            .helpHUDTitle: "Overlay-HUD (die schwebende Kapsel)",
            .helpHUDIntro: "Wenn du den globalen Kurzbefehl drückst, erscheint eine kleine schwebende Kapsel über jeder App. Sie ist kein normales Fenster: Sie bleibt im Vordergrund, stiehlt nicht den Tastaturfokus und zeigt nur den Status — nicht die volle Transkription.",
            .helpHUDAnatomy: "Aufbau links → rechts: (1) Sprach-Taste · (2) Live-Wellenform in der Mitte · (3) Ausgabeziel-Taste. Auf deinem Bildschirm sieht es oft so aus: [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "Die mittlere Wellenform wird rot, während das Mikrofon aufnimmt. Sprich, solange sie rot ist.",
            .helpHUDColorGreen: "Nach dem Stopp (Kurzbefehl erneut) wird die Wellenform grün: SmartScribe transkribiert, poliert bei Bedarf und liefert den Text. Warte, bis das HUD verschwindet.",
            .helpHUDLeftTitle: "Linke Taste — Sprachmodus (A ↔ Buchstabe)",
            .helpHUDLeftA: "A = Auto. SmartScribe behält / erkennt automatisch die gesprochene Sprache. Keine erzwungene Übersetzung. Nutze dies, wenn die Transkription in derselben Sprache wie deine Sprache sein soll.",
            .helpHUDLeftLetter: "Ein Buchstabe statt A bedeutet „Zielsprache erzwingen“. Der Buchstabe ist der erste Buchstabe des englischen Namens der Sprache: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German usw. Welcher Buchstabe erscheint, hängt ab von Einstellungen → Kurzbefehl → Transkriptionssprache (oder Glossar-Auto-Übersetzungssprache, wenn Kurzbefehl auf Auto steht).",
            .helpHUDLeftTap: "Tippe einmal auf die linke Taste, um A → Buchstabe (erzwungenes Ziel) zu wechseln, erneut für Buchstabe → A. Die Wahl wird für die nächste Sitzung gemerkt.",
            .helpHUDRightTitle: "Rechte Taste — Ausgabeziel (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. Liefert die reine Transkription ohne Variante-1-/Variante-2-Polierung. Schnellster Weg; kann dennoch Whisper-Englisch-Übersetzung nutzen, wenn die linke Taste E ist.",
            .helpHUDRightCycle: "1 = Variante 1 (leichte Bereinigung). 2 = Variante 2 (stärkere Umschreibung). Diese brauchen eine aktive Polier-Engine (Cloud oder lokales MLX). Wahl von 1 oder 2 schaltet die Polierung wieder ein, falls sie deaktiviert war.",
            .helpHUDRightTap: "Tippe auf die rechte Taste, um R → 1 → 2 → R zu wechseln. Die Auswahl wird das neue Standard-Ziel in den Kurzbefehl-Einstellungen für künftige Diktate.",
            .helpHUDControlLanguage: "Links: A = auto / dieselbe Sprache wie gesprochen. Buchstabe (E, S, R, …) = diese Zielsprache erzwingen. Tippen wechselt A ↔ Buchstabe.",
            .helpHUDControlTarget: "Rechts: R = Raw-Transkription, 1 = Variante 1, 2 = Variante 2. Tippen wechselt R → 1 → 2 → R.",
            .helpHUDDrag: "Ziehen: Klicke und halte irgendwo auf der Kapsel (nicht nur die Tasten) und bewege sie an jede Stelle auf jedem Display. Setze sie in eine Ecke, über das Dock oder neben die App, in die du schreibst — wohin du willst.",
            .helpHUDSize: "Größe & Transparenz: Einstellungen → Allgemein → Overlay-HUD. Der Größen-Regler skaliert die ganze Kapsel (und wie viele Spektrumbalken du siehst). Transparenz blendet den Glas-Hintergrund, sodass Schreibtisch-Inhalte mehr oder weniger durchscheinen.",
            .helpHUDSound: "Töne: derselbe Abschnitt Allgemein → Overlay-HUD. Schalte „Ton bei Start/Ende abspielen“ um, stelle die Lautstärke ein und nutze HUD-Töne testen für eine Vorschau ohne Aufnahme. Signale erklingen beim Start der Aufnahme und beim Ende der Verarbeitung.",
            .helpHUDSettingsPath: "Das gesamte HUD-Design findet sich unter Einstellungen → Allgemein → Overlay-HUD (Größe, Transparenz, Ton, Lautstärke). Die Position wird nach dem Ziehen automatisch gespeichert.",
            .helpHUDPosition: "Nachdem du das HUD gezogen hast, merkt sich SmartScribe die Stelle und öffnet es dort beim nächsten Mal.",
            .helpHUDDuration: "Keine kurze künstliche Begrenzung der Sprechdauer. Sprich weiter, solange die Wellenform rot ist; drücke den Kurzbefehl erneut, wenn du fertig bist.",
            .helpLangTitle: "Sprachmodi im Detail",
            .helpLangIntro: "Die Sprachsteuerung ist die linke HUD-Taste plus Einstellungen → Kurzbefehl → Transkriptionssprache. Sie arbeiten zusammen.",
            .helpLangAuto: "A (Auto): Transkription bleibt in der gesprochenen Sprache. Ideal für Notizen in deiner Muttersprache ohne Übersetzung.",
            .helpLangForced: "Buchstabe (erzwungenes Ziel): nach der Spracherkennung zielt SmartScribe auf eine bestimmte Ausgabesprache. Sprich Russisch, erhalte Englisch; sprich Englisch, erhalte Spanisch — je nach konfiguriertem Ziel.",
            .helpLangEnglishNote: "Ziel Englisch + mehrsprachiges Whisper: Raw nutzt Whispers eingebaute Übersetzung ins Englische auf dem Gerät (schnell). Bevorzuge Large v3 Full für Qualität; Turbo ist leichter, aber weniger zuverlässig bei langer oder gemischter Sprache.",
            .helpLangOtherNote: "Jedes nicht-englische Ziel braucht immer ein LLM nach Whisper (Cloud oder lokales MLX). Ohne aktiven Polier-Pfad kann erzwungenes Spanisch/Russisch/… die Sprache nicht umwandeln.",
            .helpLangWhere: "Setze das Ziel unter Kurzbefehl → Transkriptionssprache (English, Spanish, Russian, …). Steht diese auf Auto, nutzt der Buchstaben-Modus Glossar → Auto-Übersetzungssprache und fällt dann auf Englisch zurück. Der HUD-Buchstabe aktualisiert sich aus dieser Wahl.",
            .helpModelsTitle: "Lokale Transkriptionsmodelle",
            .helpModelsIntro: "Einstellungen → Lokale Modelle verwaltet WhisperKit-Core-ML-Modelle, die auf Apple Silicon Audio in Text umwandeln. Das ist getrennt von Polier-Modellen.",
            .helpModelsCatalog: "Nur Englisch (Small/Medium .en): schnell, wenn du nur Englisch sprichst. Mehrsprachig Small/Medium: leichtere Mehrsprachigkeit. Large v3 Turbo (~1,6 GB): schnelles großes Modell. Large v3 Full (~3 GB, beste Qualität): empfohlener Standard für Genauigkeit und Englisch-Übersetzung.",
            .helpModelsRecommend: "Für gemischte Sprachen und erzwungenes Englisch (HUD-Buchstabe E) nutze ein mehrsprachiges Modell — idealerweise Large v3 Full. Nur-Englisch-Modelle können andere Sprachen nicht nativ ins Englische übersetzen.",
            .helpModelsUse: "Herunterladen → Verwenden (nur eines aktiv). Löschen entfernt Dateien von diesem Mac. Es gibt keinen Apple-Speech-Fallback — wähle Lokales Whisper (mit heruntergeladenem Modell) oder Cloud · Google Gemini (Google-API-Schlüssel erforderlich).",
            .helpHotkeyTitle: "Kurzbefehl-Einstellungen",
            .helpHotkeyIntro: "Einstellungen → Kurzbefehl aktiviert vier unabhängige globale Kurzbefehle. Schalte Kurzbefehl aktivieren ein, bevor einer davon ausgelöst wird.",
            .helpHotkeyPrimary: "Primär (Standard Option+S (⌥S)): Diktat ins Overlay-HUD starten/stoppen. Erster Druck nimmt auf (rot), zweiter Druck verarbeitet (grün) und liefert Raw / Variante 1 / Variante 2.",
            .helpHotkeySecondary: "Übersetzungsfenster (Standard Option+1): öffnet das vollständige schwebende Übersetzungspanel. Kein Aufnahme-Kurzbefehl — es erfasst Auswahl/Zwischenablage und übersetzt. Der Zurücksetzen-Pfeil stellt Option+1 wieder her.",
            .helpHotkeyTertiary: "Schnellübersetzung (Standard Option+2): öffnet ein minimales Nur-Lese-Fenster mit nur dem Übersetzungsergebnis. Drücke den Kurzbefehl erneut oder Escape, um es zu schließen.",
            .helpHotkeySettings: "Einstellungen öffnen (Standard Option+~): öffnet das SmartScribe-Einstellungsfenster von überall, damit du Modelle oder Sprachen wechseln kannst, ohne deine App zu verlassen.",
            .helpModeQuickTitle: "Schnellübersetzungsfenster",
            .helpModeQuickBody: "Der tertiäre Kurzbefehl (Standard Option+2) öffnet ein minimales Immer-im-Vordergrund-Fenster, das nur das Übersetzungsergebnis zeigt — kein Quellbereich, keine Tasten. Lies es und drücke dann Escape zum Schließen. Zum Bearbeiten oder erneuten Übersetzen nutze stattdessen das vollständige Schwebende Übersetzungsfenster.",
            .helpFloatQuick: "Zwei Übersetzungsfenster: Das Schwebende Übersetzungsfenster (Option+1) ist das vollständige Panel mit Quelltext, Anbieter-/Modell-Menüs und Steuerung; Schnellübersetzung (Option+2) ist ein minimales Nur-Lese-Fenster, das nur das Ergebnis zeigt. Nutze Schnellübersetzung, wenn du eine Übersetzung nur lesen willst.",
            .helpHotkeyTarget: "Diktat-Ziel: welcher Text nach der Aufnahme geliefert wird — Raw, Variante 1 oder Variante 2. Dieselbe Wahl wie die rechte HUD-Taste (R / 1 / 2).",
            .helpHotkeyMode: "Diktat-Modus: Zwischenablage kopiert das Ergebnis zum Einfügen; In aktive App eingeben fügt in das Feld ein, das bei Aufnahmebeginn fokussiert war.",
            .helpHotkeyAccess: "In aktive App eingeben braucht Bedienungshilfen-Berechtigung (dieselbe Einstellungsseite). Zwischenablage-Modus und Schwebendes Übersetzungsfenster benötigen keine Bedienungshilfen fürs Einfügen ins Panel — aber das Erfassen von Text aus anderen Apps per Command-C funktioniert am besten, wenn die App vertrauenswürdig ist.",
            .helpFloatTitle: "Schwebendes Übersetzungsfenster",
            .helpFloatIntro: "Ein skalierbares, immer sichtbares Utility-Panel (SmartScribe Translation), getrennt vom Haupt-Notizbuch. Ideal für schnellen Sprachwechsel, während du in Browser, Mail oder Chat bleibst.",
            .helpFloatHotkey: "Öffne es mit dem Übersetzungsfenster-Kurzbefehl (Einstellungen → Kurzbefehl → Übersetzungsfenster, Standard Option+1). Du kannst Übersetzen auch aus der unteren Leiste des Hauptfensters öffnen; das schwebende Panel teilt dieselbe UI.",
            .helpFloatCapture: "Beim Öffnen sendet SmartScribe kurz Command-C an die vorderste App, um eine Auswahl zu kopieren, bevorzugt dann Notiz-Auswahl, wenn du in SmartScribe bist, sonst Zwischenablage-Text. Wurde etwas erfasst und ein Übersetzungsanbieter ist gesetzt, startet die Übersetzung automatisch.",
            .helpFloatPanel: "Im Panel: wähle Anbieter und Modell, setze Zielsprache, bearbeite Original, starte Übersetzen / Erneut übersetzen oder nimm einen kurzen Clip zur Übersetzung auf. Das Panel bleibt über anderen Apps und ist skalierbar.",
            .helpFloatFavorites: "Die Modellliste in der Übersetzungs-UI bevorzugt Modelle, die du in Einstellungen → API-Anbieter als Favoriten markiert hast (durchsuchbare Auswahl ★). Hast du keine Favoriten für diesen Anbieter, wird das aktuell gewählte Modell gezeigt.",
            .helpFloatDoubleClick: "Doppelklicke auf den Original- (Quell-)Textbereich, um aus der Zwischenablage einzufügen und sofort zu übersetzen — praktisch, nachdem du selbst Text kopiert hast.",
            .helpFloatEscape: "Drücke Escape oder die Schließen-Taste, um das schwebende Panel zu schließen. Schließen beendet SmartScribe nicht.",
            .helpCloudTitle: "Cloud-API-Anbieter",
            .helpCloudIntro: "Einstellungen → API-Anbieter konfiguriert Cloud-LLMs für Polierung und Übersetzung — nicht für Whisper-Spracherkennung. Aufbau: Anbieter-Aufklappmenü oben, Detailkarte, dann Nutzungsstatistiken.",
            .helpCloudProviders: "Reihenfolge des Aufklappmenüs: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic wird in der aktuellen UI nicht angezeigt.) Ein Aktiv-Badge markiert die für Polierung genutzte Engine.",
            .helpCloudConfigure: "Wähle einen Anbieter, gib Schlüssel ein, öffne Modelle durchsuchen (durchsuchbares Sheet), wähle ein Textmodell, dann Verwenden für Polierung. API-Schlüssel erhalten öffnet die Anbieter-Konsole, falls verfügbar. Modell-Chips zeigen Kontextlänge und, falls verfügbar, Ein-/Ausgabepreise.",
            .helpCloudKeys: "Mehrere API-Schlüssel: jeder Anbieter kann bis zu 10 Schlüssel speichern (Schlüssel hinzufügen). Das Augensymbol blendet einen Schlüssel ein/aus. Der erste nicht-leere Schlüssel wird für Anfragen genutzt; zusätzliche helfen beim Rotieren oder Trennen von privaten und Arbeits-Schlüsseln.",
            .helpCloudFavorites: "In der Modellauswahl kannst du Modelle als Favoriten markieren (★). Favoriten sortieren nach oben und werden im Modellmenü des Schwebenden Übersetzungsfensters bevorzugt. Favoriten werden auf diesem Mac gespeichert.",
            .helpCloudOpenRouter: "OpenRouter: Live-Kontostand (farbcodierte verbleibende USD), durchsuchbarer Katalog mit Kontext- und $/M-Token-Preisen sowie Aktualisieren-Steuerung. Prüfe den Kontostand vor langen Sitzungen.",
            .helpCloudBudget: "Der OpenRouter-Budget-Regler ist eine persönliche Soft-Limit-Hilfe in den Einstellungen (visuelle Orientierung, wie viel du ausgeben willst) — er kappt die API nicht von selbst. Achte auf das echte Kontostand-Banner für verbleibendes Guthaben.",
            .helpCloudCustom: "Custom: jede OpenAI-kompatible Basis-URL + Schlüssel (Proxys, selbst gehostet oder Anbieter-Endpunkte). Modelle laden von diesem Endpunkt, nachdem Schlüssel und URL gesetzt sind.",
            .helpCloudStats: "Nutzungsstatistiken unten bei API-Anbieter: Tokens der letzten Transaktion und Summen für das gewählte Modell. Statistiken zurücksetzen löscht diese Zähler.",
            .helpPolishTitle: "Polierung, MLX & Prompts",
            .helpPolishIntro: "Transkription wandelt Sprache in Text um. Polierung schreibt diesen Text um. Sie nutzen unterschiedliche Modelle und Einstellungen.",
            .helpPolishEngines: "Engines: Polierung deaktiviert (nur Raw) · Schnelle lokale Bereinigung (Regeln, kein LLM, vollständig offline) · Lokales MLX-Modell · Cloud-Anbieter aus API-Anbieter. Du kannst Anbieter/Modell sowohl in der Haupt-Notiz-Symbolleiste als auch in den Einstellungen wechseln.",
            .helpPolishMLX: "Einstellungen → Polierung: lade Katalog-Modelle herunter oder suche mit Nach lokalen Modellen suchen auf der Festplatte. Bevorzuge Nicht-Reasoning-Instruct-Modelle; Reasoning-/Thinking-Modelle sind langsamer und können Gedankengänge in die Notiz lecken.",
            .helpPolishPrompts: "Einstellungen → Prompts: bearbeite Variante 1, Variante 2 und Markdown. Jeder Prompt muss den Platzhalter \(PromptTemplate.transcriptionPlaceholder) behalten. Zurücksetzen stellt die eingebaute Vorlage wieder her.",
            .helpMoreTitle: "Glossar, Import & Übersetzung",
            .helpMoreGlossary: "Das Glossar ist ein lokales Wörterbuch bevorzugter Schreibweisen und Begriffe (Quelle → Übersetzung, Varianten, Kategorien). Es trainiert Whisper nicht neu; es schreibt Text nach Erkennung/Übersetzung um. Aktiviere es, füge Einträge hinzu oder wähle Text in einer Notiz → Zum Glossar hinzufügen. Exportiere JSON vor dem Löschen. Die Auto-Übersetzungssprache hier stützt den HUD-Buchstaben-Modus, wenn die Kurzbefehl-Sprache Auto ist.",
            .helpMoreImport: "Importiere Audio oder ziehe eine Datei ins Fenster, um eine transkribierte Notiz mit dem aktiven Sprachmodell zu erstellen.",
            .helpMoreTranslate: "Übersetze aus dem Hauptfenster oder über das schwebende Option+1-Panel (Option+2 zeigt nur das Ergebnis): Auswahl / Zwischenablage / Live-Diktat → Anbieter + Modell + Zielsprache. Übersetzung ändert die Sprache absichtlich; Variante 1/2 behalten dieselbe Sprache. Der HUD-Buchstaben-Modus nutzt die Übersetzungs-Engine, wenn das Ziel nicht Englisch ist.",
            .helpPrivacyTitle: "Privatsphäre, Speicherung & Diagnose",
            .helpPrivacyLocal: "Whisper-Transkription, Schnelle lokale Bereinigung und lokale MLX-Polierung bleiben auf diesem Mac. Aufnahmen werden in den lokalen Datenordnern der App gespeichert.",
            .helpPrivacyCloud: "Cloud-Polierung und Cloud-Übersetzung senden deinen Text (und Prompts) an den gewählten Anbieter. Nutze lokale Engines, wenn Notizen privat bleiben müssen.",
            .helpPrivacyClear: "Alle löschen entfernt dauerhaft alle Notizen und leert den Aufnahmeordner, einschließlich verwaister Audios aus unterbrochenen Sitzungen. Exportiere zuerst, wenn dir der Inhalt wichtig ist.",
            .helpPrivacyLogs: "Allgemein → Systemprotokolle exportieren für eine Diagnosedatei. Nutze die Debug-Protokollstufe nur bei der Fehlersuche. Erscheinungsbild, UI-Skalierung, HUD-Größe/-Töne und Sprache der Oberfläche finden sich ebenfalls unter Allgemein.",
            .helpTipsTitle: "Häufige Tipps",
            .helpTipEnglish: "Englische Ausgabe aus anderen Sprachen nötig? Mehrsprachiges Whisper + HUD-Buchstabe E (oder Transkriptionssprache = English) + Large v3 Full.",
            .helpTipNonEnglish: "Spanische/russische/… Ausgabe nötig? Setze diese Sprache unter Kurzbefehl, schalte das HUD auf den Buchstaben und halte eine Cloud- oder MLX-Polier-Engine aktiv.",
            .helpTipDisk: "Festplatte voll mit Modellen oder Aufnahmen? Lösche ungenutzte Whisper-Modelle unter Lokale Modelle; nutze Alle löschen nur, wenn du Notizen und verbliebene .caf-Dateien entfernen willst.",
            .helpTipStuck: "Kurzbefehl oder Eingabe hängt? Prüfe, dass Kurzbefehl aktiviert ist, das Mikrofon im Hauptfenster funktioniert, Bedienungshilfen für den Eingabe-Modus erteilt sind, und versuche dann Status aktualisieren. Exportiere Protokolle, falls es weiter fehlschlägt.",
            .helpWelcomeTitle: "SmartScribe-Hilfe",
            .helpWelcomeBody: "Diktiere überall auf deinem Mac. Sprache wird mit Whisper auf dem Gerät transkribiert; Text kann raw bleiben, bereinigt oder umgeschrieben werden — und wird dann kopiert oder in die genutzte App eingegeben.",
            .helpQuickStart: "Hier starten (erste 5 Minuten)",
            .helpRecordStep: "Klicke in eine andere App → drücke den Kurzbefehl (Standard Option+S) → sprich → drücke erneut zum Stoppen. Rotes HUD = Aufnahme, grün = Verarbeitung.",
            .helpVariantsStep: "Raw ist die Transkription. Variante 1 ist leichte Bereinigung. Variante 2 ist eine stärkere Umschreibung. Markdown strukturiert polierten Text.",
            .helpCopyStep: "Kopiere den aktuellen Tab, Alle kopieren aus der Seitenleiste oder liefere per Kurzbefehl Zwischenablage / In aktive App eingeben.",
            .helpRecordingTitle: "Overlay-HUD",
            .helpHUDStep: "HUD: [A|Buchstabe] Wellenform [R|1|2]. Tippe links A↔E, rechts R→1→2. Ziehe beliebig; Größe/Ton unter Allgemein → Overlay-HUD.",
            .helpOfflineTranscription: "Lokale Transkriptionsmodelle",
            .helpOfflineModelStep: "Einstellungen → Lokale Modelle: lade WhisperKit-Modelle herunter. Bevorzuge Large v3 Full für Qualität und Englisch-Übersetzung.",
            .helpOfflineActivateStep: "Drücke Verwenden bei einem heruntergeladenen Modell. Löschen gibt Speicherplatz frei. Fallback: Apple Speech.",
            .helpImportTitle: "Import & Übersetzung",
            .helpImportStep: "Importiere Audio oder ziehe eine Datei ins Fenster, um sie als neue Notiz zu transkribieren.",
            .helpTranslateStep: "Übersetzen-Dialog: Auswahl, Zwischenablage oder kurze Aufnahme → Anbieter + Zielsprache.",
            .helpPolishingProviders: "Polier-Engines",
            .helpPolishingProviderStep: "Deaktiviert, Schnelle lokale Bereinigung, lokales MLX oder ein Cloud-API-Anbieter aus API-Anbieter.",
            .helpPromptsStep: "Einstellungen → Prompts für Variante 1, Variante 2 und Markdown. Behalte den Transkriptions-Platzhalter.",
            .helpHotkeyStep: "Einstellungen → Kurzbefehl: aktiviere Option+S, wähle Ziel und Modus, erteile Bedienungshilfen nur für die Eingabe in Apps.",
            .helpPermissionsTitle: "Berechtigungen",
            .helpMicrophoneStep: "Das Mikrofon wird für die Aufnahme im Fenster und über das HUD benötigt.",
            .helpAccessibilityStep: "Bedienungshilfen werden nur für In aktive App eingeben benötigt.",
            .helpPermissionRefreshStep: "Wenn die Eingabe fehlschlägt, aktualisiere Bedienungshilfen in den Kurzbefehl-Einstellungen oder öffne die Systemeinstellungen.",
            .helpPrivacyLocalStep: "Lokales Whisper und lokale Polierung bleiben auf dem Gerät.",
            .helpLogsStep: "Allgemein → Systemprotokolle exportieren, wenn du eine Diagnosedatei brauchst.",
