            .onboardingHowToTranscribe: "Wie möchtest du transkribieren?",
            .onboardingLocalTitle: "Lokal (Parakeet + Whisper)",
            .onboardingLocalBody: "Auf dem Gerät, privat, funktioniert offline. Lade einmal ein Modell herunter und du bist startklar.",
            .onboardingCloudTitle: "Cloud (Google)",
            .onboardingCloudBody: "Keine Downloads. Transkription, Polierung und Übersetzung über die Google-Gemini-API.",
            .onboardingSetupTitle: "Einrichten",
            .onboardingSetupLocalBody: "Gehe zu Einstellungen → Lokale Modelle, lade ein Whisper-Modell herunter und drücke Verwenden.",
            .onboardingSetupCloudBody: "Gehe zu Einstellungen → API-Anbieter, wähle Google, gib deinen API-Schlüssel ein und wähle ein Modell.",
            .onboardingOpenSettings: "Einstellungen öffnen",
            .onboardingPermissionsTitle: "Berechtigungen",
            .onboardingPermissionsBody: "SmartScribe benötigt zwei Berechtigungen, um richtig zu funktionieren.",
            .onboardingMicrophone: "Mikrofon — um deine Sprache aufzunehmen.",
            .onboardingAccessibility: "Bedienungshilfen — um Text in andere Apps einzufügen und Kurzbefehle zu erfassen.",
            .onboardingModesTitle: "Vier Arbeitsweisen",
            .onboardingModesBody: "Hauptfenster für Notizen und Bearbeitung. Kurzbefehl + HUD zum Diktieren in jeder App. Option+1 für das vollständige Übersetzungspanel, Option+2 für ein schnelles Nur-Ergebnis-Fenster.",
            .onboardingGlossaryTitle: "Glossar",
            .onboardingGlossaryBody: "Erstelle ein Glossar für %@, um die Genauigkeit von Namen und Fachbegriffen zu verbessern.",
            .onboardingGlossaryExplanation: "Ein Glossar hilft SmartScribe, Namen, Fachbegriffe, Abkürzungen und häufig falsch erkannte Wörter genau so zu schreiben, wie du es möchtest. Füge die richtige Schreibweise und gebräuchliche Varianten hinzu; nach der Transkription oder Übersetzung ersetzt SmartScribe diese Varianten automatisch durch deine bevorzugte Form. Das Glossar bleibt auf diesem Mac und kann jederzeit in den Einstellungen bearbeitet werden.",
            .onboardingThemeTitle: "Mach es zu deinem",
            .onboardingThemeBody: "Wähle ein Erscheinungsbild. Du kannst dies jederzeit in den Einstellungen ändern.",
