            .engine: "Moteur",
            .localModelsHint: "Téléchargez un modèle Whisper ci-dessous et appuyez sur Utiliser — ou passez à Cloud · Google Gemini. Apple Speech n'est pas utilisé.",
            .googleAPI: "Google API",
            .geminiModel: "Modèle Gemini",
            .googleAPIBody: "L'audio est envoyé à Google et devient d'abord une transcription Raw légèrement nettoyée avec le modèle Gemini choisi. Raw est disponible dans le HUD. Si vous choisissez la cible 1 ou 2, son prompt de Réglages → Prompts s'exécute ensuite dans une requête texte distincte.",
            .scanForLocalModels: "Rechercher des modèles locaux",
            .scanForLocalModelsBody: "Recherche des modèles MLX dans ~/Documents, ~/Downloads et le cache HuggingFace",
            .scanning: "Analyse…",
            .scan: "Analyser",
            .skippedUnsupportedModels: "%@ modèles non pris en charge ignorés",
            .localPolishingSupportHint: "Seuls les modèles MLX de génération de texte avec un tokenizer compatible sont pris en charge pour le polissage local.",
            .markdown: "Markdown",
            .remove: "Supprimer",
