            .copied: "Copié !",
            .defaultModelName: "Par défaut",
            .removeCustomModelHelp: "Supprime uniquement de la liste. Les fichiers sur le disque ne sont pas supprimés.",
            .noNewModelsFound: "Aucun nouveau modèle trouvé",
            .foundModelsCount: "%@ modèles trouvés",
            .cloudDictationUsesGemini: "La dictée cloud utilise Google Gemini",
            .settingsGeneral: "Général",
            .settingsAPIProviders: "Fournisseurs d'API",
            .settingsHotkey: "Raccourci",
            .settingsLocalModels: "Modèles locaux",
            .settingsPolishing: "Polissage",
            .settingsPrompts: "Prompts",
            .settingsStatistics: "Statistiques",
            .settingsHelp: "Aide",
            .lastUsage: "Dernière utilisation",
            .totalUsageLabel: "Utilisation totale",
            .lastTransactionDetails: "Détails de la dernière transaction",
            .totalUsageFor: "Utilisation totale pour %@",
            .promptTokens: "Tokens de prompt",
            .completionTokens: "Tokens de complétion",
            .totalTokens: "Total des tokens",
            .selectedModel: "Modèle sélectionné",
            .resetStats: "Réinitialiser les stats",
            .noUsageData: "Pas encore de données d'utilisation.",
            .accessibilityPermission: "Autorisation d'accessibilité",
            .accessibilityTrusted: "Accordée",
            .accessibilityNotTrusted: "Non accordée",
            .accessibilityPermissionDescription: "Requis uniquement pour Saisir dans l'app active. Le mode presse-papiers n'a pas besoin de l'autorisation d'accessibilité.",
            .requestAccessibilityPermission: "Demander l'autorisation",
            .openAccessibilitySettings: "Ouvrir les réglages d'accessibilité",
            .refreshPermissionStatus: "Actualiser l'état",
            .helpHeroTitle: "Aide SmartScribe",
            .helpHeroSubtitle: "Dictez n'importe où sur votre Mac. La voix est transcrite sur l'appareil avec Whisper ; le texte peut rester brut, être nettoyé ou réécrit — puis copié ou saisi dans l'app que vous utilisiez.",
            .helpStartTitle: "Commencez ici (5 premières minutes)",
            .helpStart1: "Autorisez le microphone quand macOS le demande. Sans lui, l'enregistrement ne peut pas démarrer.",
            .helpStart2: "Ouvrez Réglages → Modèles locaux, téléchargez un modèle Whisper (Large v3 Full est le meilleur choix polyvalent), puis appuyez sur Utiliser.",
            .helpStart3: "Ouvrez Réglages → Raccourci et activez les raccourcis. Principal (Option+S par défaut) est la dictée. Le raccourci Fenêtre de traduction (Option+1 par défaut) ouvre le panneau de traduction flottant complet ; Traduction rapide (Option+2 par défaut) affiche seulement le résultat ; Ouvrir les réglages (Option+~ par défaut) ouvre les préférences. Pour la dictée, choisissez la Cible (Raw / Variante 1 / Variante 2) et le Mode (Presse-papiers ou Saisir dans l'app active).",
            .helpStart4: "Facultatif : dans Fournisseurs d'API, ajoutez une clé cloud (vous pouvez en stocker plusieurs par fournisseur), choisissez un modèle, marquez des favoris, puis Utiliser pour le polissage — ou installez un modèle MLX local. Sans moteur de polissage/traduction, Variante 1/2 et une langue forcée non anglaise n'amélioreront pas le texte.",
            .helpStart5: "Dictée : focus sur une app → Option+S → parlez → Option+S à nouveau (HUD rouge = enregistrement, vert = traitement). Traduction instantanée : sélectionnez du texte ailleurs → Option+1 → le panneau flottant capture la sélection/le presse-papiers et traduit (Option+2 affiche seulement le résultat).",
            .helpModesTitle: "Quatre façons de travailler",
            .helpModeWindowTitle: "Fenêtre principale",
            .helpModeWindowBody: "Un carnet pour les notes : enregistrez ou importez de l'audio, consultez Raw / Variante 1 / Variante 2, polissez, traduisez et copiez. Idéal quand vous voulez modifier et conserver l'historique.",
            .helpModeHotkeyTitle: "Raccourci + HUD superposé",
            .helpModeHotkeyBody: "Restez dans une autre app. Le raccourci principal (Option+S) enregistre avec le HUD flottant : mode de langue (A / lettre) et cible de sortie (R / 1 / 2). HUD visible, faites défiler pour changer de fournisseur de reformulation et faites un clic droit sur un fournisseur pour choisir un modèle précis. Ne vole pas le focus clavier pendant la dictée.",
            .helpModeFloatTitle: "Fenêtre de traduction flottante",
            .helpModeFloatBody: "Le raccourci Fenêtre de traduction (Option+1 par défaut) ouvre un panneau de traduction toujours au premier plan. Il capture le texte sélectionné dans l'app active (via un Command-C rapide), remplit Original et peut traduire immédiatement. Utile pour un changement de langue sans dictée complète.",
            .helpWindowTitle: "Fenêtre principale",
            .helpWindowBody: "Gauche : liste des notes. Droite : la note sélectionnée — infos audio, menus de fournisseur/modèle de polissage, onglets de texte et barre d'actions.",
            .helpWindowNotes: "Barre latérale : sélectionnez une note, Copier tout ou Effacer tout (définitif : supprime chaque note et les fichiers d'enregistrement restants sur le disque).",
            .helpWindowTabs: "Onglets : Raw = transcription pure. Variante 1 = nettoyage léger (tics de langage, répétitions). Variante 2 = réécriture plus forte pour la clarté. Utilisez l'action Markdown sur un onglet poli pour structurer le texte. Les emplacements de prompt D/1/2/3/4 changent le prompt personnalisé actif pour cette variante.",
            .helpWindowActions: "Barre inférieure : Enregistrer / Arrêter, Note vierge, Importer audio (ou faites glisser un fichier dans la fenêtre), Traduire, Polir, Copier. Réglages ouvre les préférences.",
            .helpWindowPolishingMenus: "Au-dessus de l'éditeur, vous pouvez changer le Fournisseur de polissage (Désactivé / Nettoyage rapide / MLX local / cloud) et le Modèle de polissage (modèles du fournisseur cloud sélectionné, ou cartes MLX locales). Cela correspond à Réglages → Fournisseurs d'API / Polissage sans quitter la note.",
            .helpHUDTitle: "HUD superposé (la capsule flottante)",
            .helpHUDIntro: "Quand vous appuyez sur le raccourci global, une petite capsule flottante apparaît au-dessus de chaque app. Ce n'est pas une fenêtre normale : elle reste au premier plan, ne vole pas le focus clavier et affiche seulement l'état — pas la transcription complète.",
            .helpHUDAnatomy: "Disposition gauche → droite : (1) bouton de langue · (2) forme d'onde en direct au milieu · (3) bouton de cible de sortie. Sur votre écran, cela ressemble souvent à [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "La forme d'onde centrale devient rouge pendant que le microphone enregistre. Parlez pendant qu'elle est rouge.",
            .helpHUDColorGreen: "Après l'arrêt (raccourci à nouveau), la forme d'onde devient verte : SmartScribe transcrit, polit si besoin et livre le texte. Attendez que le HUD se masque.",
            .helpHUDLeftTitle: "Bouton gauche — mode de langue (A ↔ lettre)",
            .helpHUDLeftA: "A = Auto. SmartScribe conserve / détecte automatiquement la langue parlée. Pas de traduction forcée. Utilisez ceci quand vous voulez la transcription dans la même langue que votre voix.",
            .helpHUDLeftLetter: "Une lettre au lieu de A signifie « forcer la langue cible ». La lettre est la première lettre du nom anglais de cette langue : E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German, etc. La lettre affichée dépend de Réglages → Raccourci → Langue de transcription (ou Langue de traduction automatique du glossaire si le raccourci est sur Auto).",
            .helpHUDLeftTap: "Touchez une fois le bouton gauche pour passer A → lettre (cible forcée), touchez à nouveau pour passer lettre → A. Le choix est mémorisé pour la session suivante.",
            .helpHUDRightTitle: "Bouton droit — cible de sortie (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. Livre la transcription brute sans polissage Variante 1 / Variante 2. Chemin le plus rapide ; peut tout de même utiliser la traduction anglaise de Whisper quand le bouton gauche est E.",
            .helpHUDRightCycle: "1 = Variante 1 (nettoyage léger). 2 = Variante 2 (réécriture plus forte). Ceux-ci nécessitent un moteur de polissage actif (cloud ou MLX local). Choisir 1 ou 2 réactive le polissage s'il était désactivé.",
            .helpHUDRightTap: "Touchez le bouton droit pour faire défiler R → 1 → 2 → R. La sélection devient la nouvelle Cible par défaut dans les réglages du raccourci pour les dictées futures.",
            .helpHUDControlLanguage: "Gauche : A = auto / même langue que la voix. Lettre (E, S, R, …) = forcer cette langue cible. Touchez pour basculer A ↔ lettre.",
            .helpHUDControlTarget: "Droite : R = transcription Raw, 1 = Variante 1, 2 = Variante 2. Touchez pour faire défiler R → 1 → 2 → R.",
            .helpHUDDrag: "Glisser : cliquez et maintenez n'importe où sur la capsule (pas seulement les boutons) et déplacez-la où vous voulez sur n'importe quel écran. Placez-la près d'un coin, au-dessus du dock ou à côté de l'app où vous saisissez — où vous voulez.",
            .helpHUDSize: "Taille et transparence : Réglages → Général → HUD superposé. Le curseur Taille met à l'échelle toute la capsule (et le nombre de barres de spectre visibles). La transparence estompe l'arrière-plan en verre pour laisser transparaître plus ou moins le contenu du bureau.",
            .helpHUDSound: "Sons : même section Général → HUD superposé. Activez « Lire un son au début/à la fin », réglez le Volume sonore et utilisez Tester les sons du HUD pour un aperçu sans enregistrer. Des signaux retentissent au début de l'enregistrement et à la fin du traitement.",
            .helpHUDSettingsPath: "Tout l'aspect du HUD se trouve sous Réglages → Général → HUD superposé (taille, transparence, son, volume). La position est enregistrée automatiquement après un glissement.",
            .helpHUDPosition: "Après avoir glissé le HUD, SmartScribe mémorise cet emplacement et le rouvre là la fois suivante.",
            .helpHUDDuration: "Pas de limite artificielle courte sur la durée de parole. Continuez à parler tant que la forme d'onde est rouge ; appuyez à nouveau sur le raccourci quand vous avez terminé.",
            .helpLangTitle: "Modes de langue en détail",
            .helpLangIntro: "Le contrôle de langue est le bouton gauche du HUD plus Réglages → Raccourci → Langue de transcription. Ils fonctionnent ensemble.",
            .helpLangAuto: "A (auto) : la transcription reste dans la langue parlée. Idéal pour des notes dans votre langue maternelle sans traduction.",
            .helpLangForced: "Lettre (cible forcée) : après la reconnaissance vocale, SmartScribe vise une langue de sortie spécifique. Parlez russe, obtenez anglais ; parlez anglais, obtenez espagnol — selon la cible configurée.",
            .helpLangEnglishNote: "Cible anglais + Whisper multilingue : Raw utilise la traduction intégrée vers l'anglais de Whisper sur l'appareil (rapide). Préférez Large v3 Full pour la qualité ; Turbo est plus léger mais moins fiable sur la voix longue ou mixte.",
            .helpLangOtherNote: "Toute cible non anglaise nécessite toujours un LLM après Whisper (cloud ou MLX local). Sans chemin de polissage actif, l'espagnol/russe/… forcé ne peut pas convertir la langue.",
            .helpLangWhere: "Définissez la cible sous Raccourci → Langue de transcription (English, Spanish, Russian, …). Si elle est sur Auto, le mode lettre utilise Glossaire → Langue de traduction automatique, puis retombe sur l'anglais. La lettre du HUD se met à jour selon ce choix.",
            .helpModelsTitle: "Modèles de transcription locaux",
            .helpModelsIntro: "Réglages → Modèles locaux gère les modèles WhisperKit Core ML qui transforment l'audio en texte sur Apple Silicon. Ceci est séparé des modèles de polissage.",
            .helpModelsCatalog: "Anglais uniquement (Small/Medium .en) : rapide si vous ne parlez qu'anglais. Small/Medium multilingues : multilingue plus léger. Large v3 Turbo (~1,6 Go) : grand modèle rapide. Large v3 Full (~3 Go, meilleure qualité) : défaut recommandé pour la précision et la traduction anglaise.",
            .helpModelsRecommend: "Pour les langues mixtes et l'anglais forcé (lettre E du HUD), utilisez un modèle multilingue — idéalement Large v3 Full. Les modèles anglais uniquement ne peuvent pas traduire nativement d'autres langues vers l'anglais.",
            .helpModelsUse: "Télécharger → Utiliser (un seul actif). Supprimer retire les fichiers de ce Mac. Il n'y a pas de repli Apple Speech — choisissez Whisper local (avec un modèle téléchargé) ou Cloud · Google Gemini (clé API Google requise).",
            .helpHotkeyTitle: "Réglages du raccourci",
            .helpHotkeyIntro: "Réglages → Raccourci active quatre raccourcis globaux indépendants. Activez Activer le raccourci avant que l'un d'eux ne se déclenche.",
            .helpHotkeyPrimary: "Principal (Option+S par défaut (⌥S)) : démarre/arrête la dictée dans le HUD superposé. Le premier appui enregistre (rouge), le second traite (vert) et livre Raw / Variante 1 / Variante 2.",
            .helpHotkeySecondary: "Fenêtre de traduction (Option+1 par défaut) : ouvre le panneau de traduction flottant complet. Pas un raccourci d'enregistrement — il capture la sélection/le presse-papiers et traduit. La flèche de réinitialisation restaure Option+1.",
            .helpHotkeyTertiary: "Traduction rapide (Option+2 par défaut) : ouvre une fenêtre minimale en lecture seule avec seulement le résultat traduit. Appuyez à nouveau sur le raccourci ou sur Échap pour la fermer.",
            .helpHotkeySettings: "Ouvrir les réglages (Option+~ par défaut) : ouvre la fenêtre des réglages de SmartScribe de n'importe où, pour changer de modèle ou de langue sans quitter votre app.",
            .helpModeQuickTitle: "Fenêtre de traduction rapide",
            .helpModeQuickBody: "Le raccourci tertiaire (Option+2 par défaut) ouvre une fenêtre minimale toujours au premier plan qui affiche seulement le résultat traduit — pas de volet source, pas de boutons. Lisez-le, puis appuyez sur Échap pour la fermer. Pour modifier ou retraduire, utilisez plutôt la Fenêtre de traduction flottante complète.",
            .helpFloatQuick: "Deux fenêtres de traduction : la Fenêtre de traduction flottante (Option+1) est le panneau complet avec texte source, menus fournisseur/modèle et commandes ; la Traduction rapide (Option+2) est une fenêtre minimale en lecture seule affichant seulement le résultat. Utilisez la Traduction rapide quand vous avez juste besoin de lire une traduction.",
            .helpHotkeyTarget: "Cible de dictée : quel texte est livré après l'enregistrement — Raw, Variante 1 ou Variante 2. Même choix que le bouton droit du HUD (R / 1 / 2).",
            .helpHotkeyMode: "Mode de dictée : Presse-papiers copie le résultat à coller ; Saisir dans l'app active insère dans le champ qui était actif au début de l'enregistrement.",
            .helpHotkeyAccess: "Saisir dans l'app active nécessite l'autorisation d'accessibilité (même page de réglages). Le mode presse-papiers et la Fenêtre de traduction flottante n'ont pas besoin de l'accessibilité pour coller dans le panneau — mais capturer du texte d'autres apps via Command-C fonctionne mieux quand l'app est approuvée.",
            .helpFloatTitle: "Fenêtre de traduction flottante",
            .helpFloatIntro: "Un panneau utilitaire redimensionnable, toujours au premier plan (SmartScribe Translation), séparé du carnet principal. Idéal pour un changement de langue rapide tout en restant dans le navigateur, le mail ou le chat.",
            .helpFloatHotkey: "Ouvrez-le avec le raccourci Fenêtre de traduction (Réglages → Raccourci → Fenêtre de traduction, Option+1 par défaut). Vous pouvez aussi ouvrir Traduire depuis la barre inférieure de la fenêtre principale ; le panneau flottant partage la même interface.",
            .helpFloatCapture: "À l'ouverture, SmartScribe envoie brièvement Command-C à l'app au premier plan pour copier toute sélection, puis préfère la sélection de note si vous êtes dans SmartScribe, sinon le texte du presse-papiers. Si quelque chose a été capturé et qu'un fournisseur de traduction est défini, la traduction démarre automatiquement.",
            .helpFloatPanel: "Dans le panneau : choisissez Fournisseur et Modèle, définissez la Langue cible, modifiez Original, lancez Traduire / Traduire à nouveau, ou enregistrez un court clip à traduire. Le panneau reste flottant au-dessus des autres apps et peut être redimensionné.",
            .helpFloatFavorites: "La liste de modèles de l'interface de traduction préfère les modèles marqués favoris dans Réglages → Fournisseurs d'API (sélecteur consultable ★). Si vous n'avez aucun favori pour ce fournisseur, le modèle actuellement sélectionné est affiché.",
            .helpFloatDoubleClick: "Double-cliquez sur la zone de texte Original (source) pour coller depuis le presse-papiers et traduire immédiatement — pratique après avoir copié du texte vous-même.",
            .helpFloatEscape: "Appuyez sur Échap ou sur le bouton de fermeture pour fermer le panneau flottant. Fermer ne quitte pas SmartScribe.",
            .helpCloudTitle: "Fournisseurs d'API cloud",
            .helpCloudIntro: "Réglages → Fournisseurs d'API configure les LLM cloud pour le polissage et la traduction — pas pour la reconnaissance vocale Whisper. Disposition : menu déroulant de fournisseur en haut, carte de détails, puis statistiques d'utilisation.",
            .helpCloudProviders: "Ordre du menu déroulant : Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic n'est pas affiché dans l'interface actuelle.) Un badge Actif marque le moteur utilisé pour le polissage.",
            .helpCloudConfigure: "Sélectionnez un fournisseur, saisissez la/les clé(s), ouvrez Parcourir les modèles (feuille consultable), choisissez un modèle de texte, puis Utiliser pour le polissage. Obtenir la clé API ouvre la console du fournisseur si disponible. Les puces de modèle affichent la longueur de contexte et, si disponibles, les prix d'entrée/sortie.",
            .helpCloudKeys: "Plusieurs clés API : chaque fournisseur peut stocker jusqu'à 10 clés (Ajouter une clé). L'icône œil affiche/masque une clé. La première clé non vide est utilisée pour les requêtes ; les supplémentaires aident à alterner ou séparer clés personnelle et professionnelle.",
            .helpCloudFavorites: "Dans le sélecteur de modèles, marquez des modèles favoris (★). Les favoris remontent en haut et sont préférés dans le menu de modèles de la Fenêtre de traduction flottante. Les favoris sont stockés sur ce Mac.",
            .helpCloudOpenRouter: "OpenRouter : solde de compte en direct (USD restants code couleur), catalogue consultable avec contexte et prix de tokens $/M, et commande d'actualisation. Vérifiez le solde avant les longues sessions.",
            .helpCloudBudget: "Le curseur de budget OpenRouter est une aide de limite souple personnelle dans les Réglages (guide visuel de ce que vous comptez dépenser) — il ne coupe pas l'API lui-même. Surveillez la bannière de solde réel pour le crédit restant.",
            .helpCloudCustom: "Custom : toute URL de base compatible OpenAI + clé (proxys, auto-hébergé ou endpoints fournisseur). Les modèles se chargent depuis cet endpoint une fois la clé et l'URL définies.",
            .helpCloudStats: "Statistiques d'utilisation en bas de Fournisseurs d'API : tokens de la dernière transaction et totaux pour le modèle sélectionné. Réinitialiser les stats efface ces compteurs.",
            .helpPolishTitle: "Polissage, MLX et prompts",
            .helpPolishIntro: "La transcription transforme la voix en texte. Le polissage réécrit ce texte. Ils utilisent des modèles et réglages différents.",
            .helpPolishEngines: "Moteurs : Polissage désactivé (Raw uniquement) · Nettoyage local rapide (règles, sans LLM, entièrement hors ligne) · Modèle MLX local · Fournisseur cloud depuis Fournisseurs d'API. Vous pouvez changer fournisseur/modèle depuis la barre d'outils de la note principale ainsi que depuis les Réglages.",
            .helpPolishMLX: "Réglages → Polissage : téléchargez des modèles du catalogue ou Recherchez des modèles locaux sur le disque. Préférez les modèles instruct sans raisonnement ; les modèles de raisonnement/réflexion sont plus lents et peuvent laisser fuir leur chaîne de pensée dans la note.",
            .helpPolishPrompts: "Réglages → Prompts : modifiez Variante 1, Variante 2 et Markdown. Chaque prompt doit conserver l'espace réservé \(PromptTemplate.transcriptionPlaceholder). Réinitialiser restaure le modèle intégré.",
            .helpMoreTitle: "Glossaire, import et traduction",
            .helpMoreGlossary: "Le glossaire est un dictionnaire local d'orthographes et de termes préférés (source → traduction, variantes, catégories). Il ne réentraîne pas Whisper ; il réécrit le texte après reconnaissance/traduction. Activez-le, ajoutez des entrées, ou sélectionnez du texte dans une note → Ajouter au glossaire. Exportez JSON avant d'effacer. La Langue de traduction automatique ici soutient le mode lettre du HUD quand la langue du raccourci est Auto.",
            .helpMoreImport: "Importez de l'audio ou déposez un fichier dans la fenêtre pour créer une note transcrite avec le modèle vocal actif.",
            .helpMoreTranslate: "Traduisez depuis la fenêtre principale ou via le panneau flottant Option+1 (Option+2 affiche seulement le résultat) : sélection / presse-papiers / dictée en direct → fournisseur + modèle + langue cible. La traduction change la langue volontairement ; Variante 1/2 gardent la même langue. Le mode lettre du HUD utilise le moteur de traduction quand la cible n'est pas l'anglais.",
            .helpPrivacyTitle: "Confidentialité, stockage et diagnostic",
            .helpPrivacyLocal: "La transcription Whisper, le Nettoyage local rapide et le polissage MLX local restent sur ce Mac. Les enregistrements sont stockés dans les dossiers de données locaux de l'app.",
            .helpPrivacyCloud: "Le polissage cloud et la traduction cloud envoient votre texte (et vos prompts) au fournisseur sélectionné. Utilisez des moteurs locaux quand les notes doivent rester privées.",
            .helpPrivacyClear: "Effacer tout supprime définitivement toutes les notes et vide le dossier d'enregistrements, y compris l'audio orphelin laissé par des sessions interrompues. Exportez d'abord si le contenu vous importe.",
            .helpPrivacyLogs: "Général → Exporter les journaux système pour un fichier de diagnostic. Utilisez le niveau de journal Debug uniquement en dépannage. Le thème, l'échelle de l'interface, la taille/sons du HUD et la langue de l'interface sont aussi sous Général.",
            .helpTipsTitle: "Astuces courantes",
            .helpTipEnglish: "Besoin d'une sortie anglaise depuis d'autres langues ? Whisper multilingue + lettre E du HUD (ou Langue de transcription = English) + Large v3 Full.",
            .helpTipNonEnglish: "Besoin d'une sortie espagnole/russe/… ? Définissez cette langue sous Raccourci, passez le HUD sur la lettre et gardez un moteur de polissage cloud ou MLX actif.",
            .helpTipDisk: "Disque plein de modèles ou d'enregistrements ? Supprimez les modèles Whisper inutilisés dans Modèles locaux ; utilisez Effacer tout uniquement si vous voulez effacer notes et fichiers .caf restants.",
            .helpTipStuck: "Raccourci ou saisie bloqué ? Vérifiez que le raccourci est activé, que le microphone fonctionne dans la fenêtre principale, que l'accessibilité est accordée pour le mode Saisie, puis essayez Actualiser l'état. Exportez les journaux si cela échoue encore.",
            .helpWelcomeTitle: "Aide SmartScribe",
            .helpWelcomeBody: "Dictez n'importe où sur votre Mac. La voix est transcrite sur l'appareil avec Whisper ; le texte peut rester brut, être nettoyé ou réécrit — puis copié ou saisi dans l'app que vous utilisiez.",
            .helpQuickStart: "Commencez ici (5 premières minutes)",
            .helpRecordStep: "Cliquez dans une autre app → appuyez sur le raccourci (Option+S par défaut) → parlez → appuyez à nouveau pour arrêter. HUD rouge = enregistrement, vert = traitement.",
            .helpVariantsStep: "Raw est la transcription. Variante 1 est un nettoyage léger. Variante 2 est une réécriture plus forte. Markdown structure le texte poli.",
            .helpCopyStep: "Copiez l'onglet actuel, Copier toutes les notes depuis la barre latérale, ou livrez via le raccourci Presse-papiers / Saisir dans l'app active.",
            .helpRecordingTitle: "HUD superposé",
            .helpHUDStep: "HUD : [A|lettre] forme d'onde [R|1|2]. Touchez à gauche A↔E, à droite R→1→2. Glissez où vous voulez ; taille/son sous Général → HUD superposé.",
            .helpOfflineTranscription: "Modèles de transcription locaux",
            .helpOfflineModelStep: "Réglages → Modèles locaux : téléchargez des modèles WhisperKit. Préférez Large v3 Full pour la qualité et la traduction anglaise.",
            .helpOfflineActivateStep: "Appuyez sur Utiliser sur un modèle téléchargé. Supprimer libère de l'espace disque. Repli : Apple Speech.",
            .helpImportTitle: "Import et traduction",
            .helpImportStep: "Importez de l'audio ou faites glisser un fichier dans la fenêtre pour le transcrire en nouvelle note.",
            .helpTranslateStep: "Fenêtre Traduire : sélection, presse-papiers ou court enregistrement → fournisseur + langue cible.",
            .helpPolishingProviders: "Moteurs de polissage",
            .helpPolishingProviderStep: "Désactivé, Nettoyage local rapide, MLX local, ou un fournisseur d'API cloud depuis Fournisseurs d'API.",
            .helpPromptsStep: "Réglages → Prompts pour Variante 1, Variante 2 et Markdown. Conservez l'espace réservé de transcription.",
            .helpHotkeyStep: "Réglages → Raccourci : activez Option+S, choisissez Cible et Mode, accordez l'accessibilité uniquement pour la saisie dans les apps.",
            .helpPermissionsTitle: "Autorisations",
            .helpMicrophoneStep: "Le microphone est requis pour l'enregistrement dans la fenêtre et via le HUD.",
            .helpAccessibilityStep: "L'accessibilité est requise uniquement pour Saisir dans l'app active.",
            .helpPermissionRefreshStep: "Si la saisie échoue, actualisez l'accessibilité dans les réglages du raccourci ou ouvrez les Réglages Système.",
            .helpPrivacyLocalStep: "Whisper local et polissage local restent sur l'appareil.",
