            .openSettingsDesc: "Apre la finestra delle impostazioni di SmartScribe",
            .transcriptionEngine: "MOTORE DI TRASCRIZIONE",
            .engine: "Motore",
            .localModelsHint: "Scarica un modello Whisper qui sotto e premi Usa — oppure passa a Cloud · Google Gemini. Apple Speech non è usato.",
            .googleAPI: "Google API",
            .geminiModel: "Modello Gemini",
            .googleAPIBody: "L'audio viene caricato su Google e diventa prima una trascrizione Raw leggermente ripulita con il modello Gemini scelto. Raw è disponibile nell'HUD. Se scegli la destinazione 1 o 2, il relativo prompt da Impostazioni → Prompt viene eseguito dopo come richiesta di solo testo separata.",
            .scanForLocalModels: "Cerca modelli locali",
            .scanForLocalModelsBody: "Cerca modelli MLX in ~/Documents, ~/Downloads e nella cache HuggingFace",
            .scanning: "Scansione…",
            .scan: "Scansiona",
            .skippedUnsupportedModels: "%@ modelli non supportati saltati",
            .localPolishingSupportHint: "Per la rifinitura locale sono supportati solo modelli MLX di generazione testo con un tokenizer compatibile.",
            .markdown: "Markdown",
            .remove: "Rimuovi",
            .keyConfigured: "Chiave configurata",
