            .copied: "Copiato!",
            .defaultModelName: "Predefinito",
            .removeCustomModelHelp: "Rimuove solo dall'elenco. I file su disco non vengono eliminati.",
            .noNewModelsFound: "Nessun nuovo modello trovato",
            .foundModelsCount: "%@ modelli trovati",
            .cloudDictationUsesGemini: "La dettatura cloud usa Google Gemini",
            .settingsGeneral: "Generale",
            .settingsAPIProviders: "Provider API",
            .settingsHotkey: "Scorciatoia",
            .settingsLocalModels: "Modelli locali",
            .settingsPolishing: "Rifinitura",
            .settingsPrompts: "Prompt",
            .settingsStatistics: "Statistiche",
            .settingsHelp: "Aiuto",
            .lastUsage: "Ultimo utilizzo",
            .totalUsageLabel: "Utilizzo totale",
            .lastTransactionDetails: "Dettagli dell'ultima transazione",
            .totalUsageFor: "Utilizzo totale per %@",
            .promptTokens: "Token di prompt",
            .completionTokens: "Token di completamento",
            .totalTokens: "Token totali",
            .selectedModel: "Modello selezionato",
            .resetStats: "Ripristina statistiche",
            .noUsageData: "Ancora nessun dato di utilizzo.",
            .accessibilityPermission: "Permesso di accessibilità",
            .accessibilityTrusted: "Concesso",
            .accessibilityNotTrusted: "Non concesso",
            .accessibilityPermissionDescription: "Richiesto solo per Digita nell'app attiva. La modalità appunti non richiede il permesso di accessibilità.",
            .requestAccessibilityPermission: "Richiedi permesso",
            .openAccessibilitySettings: "Apri impostazioni accessibilità",
            .refreshPermissionStatus: "Aggiorna stato",
            .helpHeroTitle: "Aiuto di SmartScribe",
            .helpHeroSubtitle: "Detta ovunque sul tuo Mac. La voce viene trascritta sul dispositivo con Whisper; il testo può restare grezzo, essere ripulito o riscritto — poi copiato o digitato nell'app che stavi usando.",
            .helpStartTitle: "Inizia qui (primi 5 minuti)",
            .helpStart1: "Consenti il microfono quando macOS lo chiede. Senza di esso, la registrazione non può iniziare.",
            .helpStart2: "Apri Impostazioni → Modelli locali, scarica un modello Whisper (Large v3 Full è la scelta migliore a tutto tondo), poi premi Usa.",
            .helpStart3: "Apri Impostazioni → Scorciatoia e attiva le scorciatoie. Principale (default Option+S) è la dettatura. La scorciatoia Finestra di traduzione (default Option+1) apre il pannello di traduzione mobile completo; Traduzione rapida (default Option+2) mostra solo il risultato; Apri impostazioni (default Option+~) apre le preferenze. Per la dettatura scegli Destinazione (Raw / Variante 1 / Variante 2) e Modalità (Appunti o Digita nell'app attiva).",
            .helpStart4: "Facoltativo: in Provider API aggiungi una chiave cloud (puoi memorizzarne più per provider), scegli un modello, segna i preferiti, poi Usa per la rifinitura — oppure installa un modello MLX locale. Senza un motore di rifinitura/traduzione, Variante 1/2 e una lingua forzata non inglese non miglioreranno il testo.",
            .helpStart5: "Dettatura: focus su un'app → Option+S → parla → Option+S di nuovo (HUD rosso = registrazione, verde = elaborazione). Traduzione istantanea: seleziona testo altrove → Option+1 → il pannello mobile cattura selezione/appunti e traduce (Option+2 mostra solo il risultato).",
            .helpModesTitle: "Quattro modi di lavorare",
            .helpModeWindowTitle: "Finestra principale",
            .helpModeWindowBody: "Un quaderno per le note: registra o importa audio, controlla Raw / Variante 1 / Variante 2, rifinisci, traduci e copia. Ideale quando vuoi modificare e conservare la cronologia.",
            .helpModeHotkeyTitle: "Scorciatoia + HUD in sovrimpressione",
            .helpModeHotkeyBody: "Resta dentro un'altra app. La scorciatoia principale (Option+S) registra con l'HUD mobile: modalità lingua (A / lettera) e destinazione di output (R / 1 / 2). Con l'HUD visibile, scorri per cambiare il provider di rifinitura e fai clic destro su un provider per scegliere un modello specifico. Non ruba il focus della tastiera mentre detti.",
            .helpModeFloatTitle: "Finestra di traduzione mobile",
            .helpModeFloatBody: "La scorciatoia Finestra di traduzione (default Option+1) apre un pannello di traduzione sempre in primo piano. Cattura il testo selezionato dall'app attiva (con un rapido Command-C), riempie Originale e può tradurre subito. Utile per un cambio di lingua senza dettatura completa.",
            .helpWindowTitle: "Finestra principale",
            .helpWindowBody: "Sinistra: elenco note. Destra: la nota selezionata — info audio, menu provider/modello di rifinitura, schede di testo e barra delle azioni.",
            .helpWindowNotes: "Barra laterale: seleziona una nota, Copia tutto o Cancella tutto (permanente: elimina ogni nota e i file di registrazione rimasti su disco).",
            .helpWindowTabs: "Schede: Raw = trascrizione pura. Variante 1 = pulizia leggera (intercalari, ripetizioni). Variante 2 = riscrittura più forte per chiarezza. Usa l'azione Markdown su una scheda rifinita per strutturare il testo. Gli slot di prompt D/1/2/3/4 cambiano quale prompt personalizzato è attivo per quella variante.",
            .helpWindowActions: "Barra inferiore: Registra / Ferma, Nota vuota, Importa audio (o trascina un file nella finestra), Traduci, Rifinisci, Copia. Impostazioni apre le preferenze.",
            .helpWindowPolishingMenus: "Sopra l'editor puoi cambiare Provider di rifinitura (Disattivato / Pulizia rapida / MLX locale / cloud) e Modello di rifinitura (modelli del provider cloud selezionato, o schede MLX locali). Corrisponde a Impostazioni → Provider API / Rifinitura senza lasciare la nota.",
            .helpHUDTitle: "HUD in sovrimpressione (la capsula mobile)",
            .helpHUDIntro: "Quando premi la scorciatoia globale, appare una piccola capsula mobile sopra ogni app. Non è una finestra normale: resta in primo piano, non ruba il focus della tastiera e mostra solo lo stato — non la trascrizione completa.",
            .helpHUDAnatomy: "Layout sinistra → destra: (1) pulsante lingua · (2) forma d'onda live al centro · (3) pulsante destinazione di output. Sul tuo schermo spesso appare come [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "La forma d'onda centrale diventa rossa mentre il microfono registra. Parla finché è rossa.",
            .helpHUDColorGreen: "Dopo lo stop (di nuovo la scorciatoia), la forma d'onda diventa verde: SmartScribe trascrive, rifinisce se necessario e consegna il testo. Attendi finché l'HUD si nasconde.",
            .helpHUDLeftTitle: "Pulsante sinistro — modalità lingua (A ↔ lettera)",
            .helpHUDLeftA: "A = Auto. SmartScribe mantiene / rileva automaticamente la lingua parlata. Nessuna traduzione forzata. Usalo quando vuoi la trascrizione nella stessa lingua della tua voce.",
            .helpHUDLeftLetter: "Una lettera al posto di A significa «forza la lingua di destinazione». La lettera è la prima lettera del nome inglese di quella lingua: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German, e così via. Quale lettera appare dipende da Impostazioni → Scorciatoia → Lingua di trascrizione (o Lingua di traduzione automatica del Glossario se la Scorciatoia è Auto).",
            .helpHUDLeftTap: "Tocca una volta il pulsante sinistro per passare A → lettera (destinazione forzata), tocca di nuovo per passare lettera → A. La scelta è ricordata per la sessione successiva.",
            .helpHUDRightTitle: "Pulsante destro — destinazione di output (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. Consegna la trascrizione semplice senza rifinitura Variante 1 / Variante 2. Percorso più veloce; può comunque usare la traduzione inglese di Whisper quando il pulsante sinistro è E.",
            .helpHUDRightCycle: "1 = Variante 1 (pulizia leggera). 2 = Variante 2 (riscrittura più forte). Questi richiedono un motore di rifinitura attivo (cloud o MLX locale). Scegliere 1 o 2 riattiva la rifinitura se era disattivata.",
            .helpHUDRightTap: "Tocca il pulsante destro per scorrere R → 1 → 2 → R. La selezione diventa la nuova Destinazione predefinita nelle impostazioni della Scorciatoia per le dettature future.",
            .helpHUDControlLanguage: "Sinistra: A = auto / stessa lingua della voce. Lettera (E, S, R, …) = forza quella lingua di destinazione. Tocca per alternare A ↔ lettera.",
            .helpHUDControlTarget: "Destra: R = trascrizione Raw, 1 = Variante 1, 2 = Variante 2. Tocca per scorrere R → 1 → 2 → R.",
            .helpHUDDrag: "Trascinare: clicca e tieni premuto ovunque sulla capsula (non solo i pulsanti) e spostala in qualsiasi punto su qualsiasi display. Mettila vicino all'angolo, sopra il dock o accanto all'app in cui digiti — dove preferisci.",
            .helpHUDSize: "Dimensioni e trasparenza: Impostazioni → Generale → HUD in sovrimpressione. Il cursore Dimensioni scala l'intera capsula (e quante barre dello spettro vedi). La trasparenza attenua lo sfondo in vetro così il contenuto della scrivania traspare più o meno.",
            .helpHUDSound: "Suoni: stessa sezione Generale → HUD in sovrimpressione. Attiva «Riproduci suono all'inizio/alla fine», imposta Volume audio e usa Prova suoni HUD per un'anteprima senza registrare. I segnali suonano all'inizio della registrazione e alla fine dell'elaborazione.",
            .helpHUDSettingsPath: "Tutto l'aspetto dell'HUD è sotto Impostazioni → Generale → HUD in sovrimpressione (dimensioni, trasparenza, suono, volume). La posizione è salvata automaticamente dopo il trascinamento.",
            .helpHUDPosition: "Dopo aver trascinato l'HUD, SmartScribe ricorda quel punto e lo riapre lì la volta successiva.",
            .helpHUDDuration: "Nessun limite artificiale breve su quanto puoi parlare. Continua a parlare finché la forma d'onda è rossa; premi di nuovo la scorciatoia quando hai finito.",
            .helpLangTitle: "Modalità lingua in dettaglio",
            .helpLangIntro: "Il controllo della lingua è il pulsante sinistro dell'HUD più Impostazioni → Scorciatoia → Lingua di trascrizione. Lavorano insieme.",
            .helpLangAuto: "A (auto): la trascrizione resta nella lingua parlata. Ideale per note nella tua lingua madre senza traduzione.",
            .helpLangForced: "Lettera (destinazione forzata): dopo il riconoscimento vocale, SmartScribe punta a una lingua di output specifica. Parla russo, ottieni inglese; parla inglese, ottieni spagnolo — a seconda della destinazione configurata.",
            .helpLangEnglishNote: "Destinazione inglese + Whisper multilingue: Raw usa la traduzione integrata in inglese di Whisper sul dispositivo (veloce). Preferisci Large v3 Full per la qualità; Turbo è più leggero ma meno affidabile su voce lunga o mista.",
            .helpLangOtherNote: "Qualsiasi destinazione non inglese richiede sempre un LLM dopo Whisper (cloud o MLX locale). Senza un percorso di rifinitura attivo, spagnolo/russo/… forzato non può convertire la lingua.",
            .helpLangWhere: "Imposta la destinazione sotto Scorciatoia → Lingua di trascrizione (English, Spanish, Russian, …). Se è Auto, la modalità lettera usa Glossario → Lingua di traduzione automatica, poi ripiega sull'inglese. La lettera dell'HUD si aggiorna da quella scelta.",
            .helpModelsTitle: "Modelli di trascrizione locali",
            .helpModelsIntro: "Impostazioni → Modelli locali gestisce i modelli WhisperKit Core ML che trasformano l'audio in testo su Apple Silicon. È separato dai modelli di rifinitura.",
            .helpModelsCatalog: "Solo inglese (Small/Medium .en): veloce se parli solo inglese. Small/Medium multilingue: multilingue più leggero. Large v3 Turbo (~1,6 GB): modello grande veloce. Large v3 Full (~3 GB, qualità migliore): default consigliato per precisione e traduzione inglese.",
            .helpModelsRecommend: "Per lingue miste e inglese forzato (lettera E dell'HUD), usa un modello multilingue — idealmente Large v3 Full. I modelli solo inglese non possono tradurre nativamente altre lingue in inglese.",
            .helpModelsUse: "Scarica → Usa (solo uno attivo). Elimina rimuove i file da questo Mac. Non c'è fallback Apple Speech — scegli Whisper locale (con un modello scaricato) o Cloud · Google Gemini (chiave API Google richiesta).",
            .helpHotkeyTitle: "Impostazioni della scorciatoia",
            .helpHotkeyIntro: "Impostazioni → Scorciatoia abilita quattro scorciatoie globali indipendenti. Attiva Abilita scorciatoia prima che una qualsiasi si attivi.",
            .helpHotkeyPrimary: "Principale (default Option+S (⌥S)): avvia/ferma la dettatura nell'HUD in sovrimpressione. La prima pressione registra (rosso), la seconda elabora (verde) e consegna Raw / Variante 1 / Variante 2.",
            .helpHotkeySecondary: "Finestra di traduzione (default Option+1): apre il pannello di traduzione mobile completo. Non è una scorciatoia di registrazione — cattura selezione/appunti e traduce. La freccia di ripristino ripristina Option+1.",
            .helpHotkeyTertiary: "Traduzione rapida (default Option+2): apre una finestra minima in sola lettura con solo il risultato tradotto. Premi di nuovo la scorciatoia o Esc per chiuderla.",
            .helpHotkeySettings: "Apri impostazioni (default Option+~): apre la finestra delle impostazioni di SmartScribe da qualsiasi punto, così puoi cambiare modelli o lingue senza lasciare la tua app.",
            .helpModeQuickTitle: "Finestra di traduzione rapida",
            .helpModeQuickBody: "La scorciatoia terziaria (default Option+2) apre una finestra minima sempre in primo piano che mostra solo il risultato tradotto — niente riquadro sorgente, niente pulsanti. Leggilo, poi premi Esc per chiuderla. Per modificare o ritradurre, usa invece la Finestra di traduzione mobile completa.",
            .helpFloatQuick: "Due finestre di traduzione: la Finestra di traduzione mobile (Option+1) è il pannello completo con testo sorgente, menu provider/modello e controlli; Traduzione rapida (Option+2) è una finestra minima in sola lettura che mostra solo il risultato. Usa Traduzione rapida quando ti serve solo leggere una traduzione.",
            .helpHotkeyTarget: "Destinazione dettatura: quale testo viene consegnato dopo la registrazione — Raw, Variante 1 o Variante 2. Stessa scelta del pulsante destro dell'HUD (R / 1 / 2).",
            .helpHotkeyMode: "Modalità dettatura: Appunti copia il risultato da incollare; Digita nell'app attiva inserisce nel campo che era attivo all'inizio della registrazione.",
            .helpHotkeyAccess: "Digita nell'app attiva richiede il permesso di accessibilità (stessa pagina delle impostazioni). La modalità appunti e la Finestra di traduzione mobile non richiedono l'accessibilità per incollare nel pannello — ma catturare testo da altre app con Command-C funziona meglio quando l'app è affidabile.",
            .helpFloatTitle: "Finestra di traduzione mobile",
            .helpFloatIntro: "Un pannello utility ridimensionabile, sempre in primo piano (SmartScribe Translation), separato dal quaderno principale. Ideale per un cambio di lingua rapido mentre resti nel browser, nella mail o in chat.",
            .helpFloatHotkey: "Aprilo con la scorciatoia Finestra di traduzione (Impostazioni → Scorciatoia → Finestra di traduzione, default Option+1). Puoi anche aprire Traduci dalla barra inferiore della finestra principale; il pannello mobile condivide la stessa UI.",
            .helpFloatCapture: "All'apertura, SmartScribe invia brevemente Command-C all'app in primo piano per copiare qualsiasi selezione, poi preferisce la selezione della nota se sei dentro SmartScribe, altrimenti il testo degli appunti. Se qualcosa è stato catturato e un provider di traduzione è impostato, la traduzione inizia automaticamente.",
            .helpFloatPanel: "Dentro il pannello: scegli Provider e Modello, imposta Lingua di destinazione, modifica Originale, esegui Traduci / Traduci di nuovo, o registra una breve clip da tradurre. Il pannello resta mobile sopra le altre app e può essere ridimensionato.",
            .helpFloatFavorites: "L'elenco modelli nell'UI di traduzione preferisce i modelli che hai segnato come preferiti in Impostazioni → Provider API (selettore ricercabile ★). Se non hai preferiti per quel provider, viene mostrato il modello attualmente selezionato.",
            .helpFloatDoubleClick: "Fai doppio clic sull'area di testo Originale (sorgente) per incollare dagli appunti e tradurre subito — comodo dopo che copi tu stesso del testo.",
            .helpFloatEscape: "Premi Esc o il pulsante di chiusura per chiudere il pannello mobile. Chiudere non esce da SmartScribe.",
            .helpCloudTitle: "Provider API cloud",
            .helpCloudIntro: "Impostazioni → Provider API configura LLM cloud per rifinitura e traduzione — non per il riconoscimento vocale Whisper. Layout: menu a discesa del provider in alto, scheda dettagli, poi statistiche di utilizzo.",
            .helpCloudProviders: "Ordine del menu a discesa: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic non è mostrato nell'UI attuale.) Un badge Attivo segna il motore usato per la rifinitura.",
            .helpCloudConfigure: "Seleziona un provider, inserisci le chiavi, apri Sfoglia modelli (foglio ricercabile), scegli un modello di testo, poi Usa per la rifinitura. Ottieni chiave API apre la console del provider quando disponibile. I chip del modello mostrano la lunghezza del contesto e, se disponibili, i prezzi di input/output.",
            .helpCloudKeys: "Più chiavi API: ogni provider può memorizzare fino a 10 chiavi (Aggiungi chiave). L'icona occhio mostra/nasconde una chiave. La prima chiave non vuota è usata per le richieste; quelle extra aiutano a ruotare o separare chiavi personali e di lavoro.",
            .helpCloudFavorites: "Nel selettore modelli, segna i modelli come preferiti (★). I preferiti vanno in cima e sono preferiti nel menu modelli della Finestra di traduzione mobile. I preferiti sono memorizzati su questo Mac.",
            .helpCloudOpenRouter: "OpenRouter: saldo del conto in tempo reale (USD rimanenti con codice colore), catalogo ricercabile con contesto e prezzi token $/M, e controllo di aggiornamento. Controlla il saldo prima di sessioni lunghe.",
            .helpCloudBudget: "Il cursore del budget OpenRouter è un aiuto personale di limite morbido nelle Impostazioni (guida visiva su quanto intendi spendere) — non interrompe l'API da solo. Guarda il banner del saldo reale per il credito rimanente.",
            .helpCloudCustom: "Custom: qualsiasi URL di base compatibile OpenAI + chiave (proxy, self-hosted o endpoint di fornitori). I modelli si caricano da quell'endpoint dopo che chiave e URL sono impostati.",
            .helpCloudStats: "Statistiche di utilizzo in fondo a Provider API: token dell'ultima transazione e totali per il modello selezionato. Ripristina statistiche azzera quei contatori.",
            .helpPolishTitle: "Rifinitura, MLX e prompt",
            .helpPolishIntro: "La trascrizione trasforma la voce in testo. La rifinitura riscrive quel testo. Usano modelli e impostazioni diversi.",
            .helpPolishEngines: "Motori: Rifinitura disattivata (solo Raw) · Pulizia locale rapida (regole, nessun LLM, completamente offline) · Modello MLX locale · Provider cloud da Provider API. Puoi cambiare provider/modello dalla barra strumenti della nota principale oltre che dalle Impostazioni.",
            .helpPolishMLX: "Impostazioni → Rifinitura: scarica modelli dal catalogo o Cerca modelli locali sul disco. Preferisci modelli instruct senza ragionamento; i modelli di ragionamento/pensiero sono più lenti e possono far trapelare la catena di pensiero nella nota.",
            .helpPolishPrompts: "Impostazioni → Prompt: modifica Variante 1, Variante 2 e Markdown. Ogni prompt deve mantenere il segnaposto \(PromptTemplate.transcriptionPlaceholder). Ripristina ripristina il modello integrato.",
            .helpMoreTitle: "Glossario, import e traduzione",
            .helpMoreGlossary: "Il Glossario è un dizionario locale di grafie e termini preferiti (sorgente → traduzione, varianti, categorie). Non riaddestra Whisper; riscrive il testo dopo riconoscimento/traduzione. Attivalo, aggiungi voci, o seleziona testo in una nota → Aggiungi al glossario. Esporta JSON prima di Cancella. La Lingua di traduzione automatica qui supporta la modalità lettera dell'HUD quando la lingua della Scorciatoia è Auto.",
            .helpMoreImport: "Importa audio o trascina un file nella finestra per creare una nota trascritta con il modello vocale attivo.",
            .helpMoreTranslate: "Traduci dalla finestra principale o con il pannello mobile Option+1 (Option+2 mostra solo il risultato): selezione / appunti / dettatura live → provider + modello + lingua di destinazione. La traduzione cambia lingua di proposito; Variante 1/2 mantengono la stessa lingua. La modalità lettera dell'HUD usa il motore di traduzione quando la destinazione non è inglese.",
            .helpPrivacyTitle: "Privacy, archiviazione e diagnostica",
            .helpPrivacyLocal: "La trascrizione Whisper, la Pulizia locale rapida e la rifinitura MLX locale restano su questo Mac. Le registrazioni sono memorizzate nelle cartelle dati locali dell'app.",
            .helpPrivacyCloud: "La rifinitura cloud e la traduzione cloud inviano il tuo testo (e i prompt) al provider selezionato. Usa motori locali quando le note devono restare private.",
            .helpPrivacyClear: "Cancella tutto elimina permanentemente tutte le note e svuota la cartella delle registrazioni, incluso l'audio orfano lasciato da sessioni interrotte. Esporta prima se ti interessa il contenuto.",
            .helpPrivacyLogs: "Generale → Esporta registri di sistema per un file diagnostico. Usa il livello di registro Debug solo durante la risoluzione dei problemi. Tema, scala UI, dimensioni/suoni HUD e lingua dell'interfaccia sono anche sotto Generale.",
            .helpTipsTitle: "Suggerimenti comuni",
            .helpTipEnglish: "Ti serve output in inglese da altre lingue? Whisper multilingue + lettera E dell'HUD (o Lingua di trascrizione = English) + Large v3 Full.",
            .helpTipNonEnglish: "Ti serve output in spagnolo/russo/…? Imposta quella lingua sotto Scorciatoia, passa l'HUD alla lettera e tieni attivo un motore di rifinitura cloud o MLX.",
            .helpTipDisk: "Disco pieno di modelli o registrazioni? Elimina i modelli Whisper inutilizzati in Modelli locali; usa Cancella tutto solo quando intendi cancellare note e file .caf rimasti.",
            .helpTipStuck: "Scorciatoia o digitazione bloccate? Conferma che la Scorciatoia è abilitata, il microfono funziona nella finestra principale, l'Accessibilità è concessa per la modalità Digita, poi prova Aggiorna stato. Esporta i registri se ancora non va.",
            .helpWelcomeTitle: "Aiuto di SmartScribe",
            .helpWelcomeBody: "Detta ovunque sul tuo Mac. La voce viene trascritta sul dispositivo con Whisper; il testo può restare grezzo, essere ripulito o riscritto — poi copiato o digitato nell'app che stavi usando.",
            .helpQuickStart: "Inizia qui (primi 5 minuti)",
            .helpRecordStep: "Clicca in un'altra app → premi la scorciatoia (default Option+S) → parla → premi di nuovo per fermare. HUD rosso = registrazione, verde = elaborazione.",
            .helpVariantsStep: "Raw è la trascrizione. Variante 1 è pulizia leggera. Variante 2 è una riscrittura più forte. Markdown struttura il testo rifinito.",
            .helpCopyStep: "Copia la scheda corrente, Copia tutto le note dalla barra laterale, o consegna con la scorciatoia Appunti / Digita nell'app attiva.",
            .helpRecordingTitle: "HUD in sovrimpressione",
            .helpHUDStep: "HUD: [A|lettera] forma d'onda [R|1|2]. Tocca a sinistra A↔E, a destra R→1→2. Trascina ovunque; dimensioni/suono in Generale → HUD in sovrimpressione.",
            .helpOfflineTranscription: "Modelli di trascrizione locali",
            .helpOfflineModelStep: "Impostazioni → Modelli locali: scarica modelli WhisperKit. Preferisci Large v3 Full per qualità e traduzione inglese.",
            .helpOfflineActivateStep: "Premi Usa su un modello scaricato. Elimina libera spazio su disco. Fallback: Apple Speech.",
            .helpImportTitle: "Import e traduzione",
            .helpImportStep: "Importa audio o trascina un file nella finestra per trascriverlo come nuova nota.",
            .helpTranslateStep: "Finestra Traduci: selezione, appunti o breve registrazione → provider + lingua di destinazione.",
            .helpPolishingProviders: "Motori di rifinitura",
            .helpPolishingProviderStep: "Disattivato, Pulizia locale rapida, MLX locale, o un provider API cloud da Provider API.",
            .helpPromptsStep: "Impostazioni → Prompt per Variante 1, Variante 2 e Markdown. Mantieni il segnaposto di trascrizione.",
            .helpHotkeyStep: "Impostazioni → Scorciatoia: abilita Option+S, scegli Destinazione e Modalità, concedi l'Accessibilità solo per digitare nelle app.",
            .helpPermissionsTitle: "Permessi",
            .helpMicrophoneStep: "Il microfono è richiesto per registrare nella finestra e con l'HUD.",
            .helpAccessibilityStep: "L'Accessibilità è richiesta solo per Digita nell'app attiva.",
            .helpPermissionRefreshStep: "Se la digitazione fallisce, aggiorna l'Accessibilità nelle impostazioni della Scorciatoia o apri Impostazioni di Sistema.",
            .helpPrivacyLocalStep: "Whisper locale e rifinitura locale restano sul dispositivo.",
            .helpLogsStep: "Generale → Esporta registri di sistema quando ti serve un file diagnostico.",
