            .pasteFromClipboard: "Colar da área de transferência",
            .pasteFromClipboardHelp: "Colar texto da área de transferência e traduzir automaticamente",
            .hotkeyOptionHint: "Use Option (⌥), não Alt. Exemplo: %@",
            .translationWindowLabel: "Janela de tradução",
            .translationWindowDesc: "Abre o painel de tradução completo com texto de origem e resultado",
            .quickTranslationLabel: "Tradução rápida",
            .quickTranslationDesc: "Abre uma janela mínima mostrando apenas o resultado traduzido",
            .openSettingsLabel: "Abrir ajustes",
            .openSettingsDesc: "Abre a janela de ajustes do SmartScribe",
            .transcriptionEngine: "MECANISMO DE TRANSCRIÇÃO",
            .engine: "Mecanismo",
            .localModelsHint: "Baixe um modelo Whisper abaixo e pressione Usar — ou mude para Cloud · Google Gemini. Apple Speech não é usado.",
            .googleAPI: "Google API",
            .geminiModel: "Modelo Gemini",
            .googleAPIBody: "O áudio é enviado ao Google e primeiro vira uma transcrição Raw levemente limpa com o modelo Gemini escolhido. Raw está disponível no HUD. Se você escolher o destino 1 ou 2, o prompt correspondente de Ajustes → Prompts é executado depois em uma solicitação de texto separada.",
            .scanForLocalModels: "Buscar modelos locais",
            .scanForLocalModelsBody: "Busca modelos MLX em ~/Documents, ~/Downloads e no cache HuggingFace",
            .scanning: "Buscando…",
            .scan: "Buscar",
            .skippedUnsupportedModels: "%@ modelos não suportados ignorados",
            .localPolishingSupportHint: "Apenas modelos MLX de geração de texto com tokenizer compatível são suportados para polimento local.",
            .markdown: "Markdown",
            .remove: "Remover",
            .keyConfigured: "Chave configurada",
            .noAPIKey: "Nenhuma chave de API",
            .copied: "Copiado!",
            .defaultModelName: "Padrão",
            .removeCustomModelHelp: "Remove apenas da lista. Arquivos no disco não são excluídos.",
            .noNewModelsFound: "Nenhum novo modelo encontrado",
            .foundModelsCount: "%@ modelos encontrados",
            .cloudDictationUsesGemini: "O ditado em nuvem usa Google Gemini",
            .settingsGeneral: "Geral",
            .settingsAPIProviders: "Provedores de API",
            .settingsHotkey: "Atalho",
            .settingsLocalModels: "Modelos locais",
            .settingsPolishing: "Polimento",
            .settingsPrompts: "Prompts",
            .settingsStatistics: "Estatísticas",
            .settingsHelp: "Ajuda",
            .lastUsage: "Último uso",
            .totalUsageLabel: "Uso total",
            .lastTransactionDetails: "Detalhes da última transação",
            .totalUsageFor: "Uso total de %@",
            .promptTokens: "Tokens de prompt",
            .completionTokens: "Tokens de conclusão",
            .totalTokens: "Total de tokens",
            .selectedModel: "Modelo selecionado",
            .resetStats: "Redefinir estatísticas",
            .noUsageData: "Ainda sem dados de uso.",
            .accessibilityPermission: "Permissão de acessibilidade",
            .accessibilityTrusted: "Concedida",
            .accessibilityNotTrusted: "Não concedida",
            .accessibilityPermissionDescription: "Necessária apenas para Digitar no app ativo. O modo área de transferência não precisa de permissão de acessibilidade.",
            .requestAccessibilityPermission: "Solicitar permissão",
            .openAccessibilitySettings: "Abrir ajustes de acessibilidade",
            .refreshPermissionStatus: "Atualizar status",
            .helpHeroTitle: "Ajuda do SmartScribe",
            .helpHeroSubtitle: "Dite em qualquer lugar do seu Mac. A fala é transcrita no dispositivo com Whisper; o texto pode ficar bruto, ser limpo ou reescrito — depois copiado ou digitado no app que você estava usando.",
            .helpStartTitle: "Comece aqui (primeiros 5 minutos)",
            .helpStart1: "Permita o microfone quando o macOS pedir. Sem ele, a gravação não pode iniciar.",
            .helpStart2: "Abra Ajustes → Modelos locais, baixe um modelo Whisper (Large v3 Full é a melhor escolha geral) e pressione Usar.",
            .helpStart3: "Abra Ajustes → Atalho e ative os atalhos. Primário (padrão Option+S) é o ditado. O atalho Janela de tradução (padrão Option+1) abre o painel de tradução flutuante completo; Tradução rápida (padrão Option+2) mostra apenas o resultado; Abrir ajustes (padrão Option+~) abre as preferências. Para o ditado escolha Destino (Raw / Variante 1 / Variante 2) e Modo (Área de transferência ou Digitar no app ativo).",
            .helpStart4: "Opcional: em Provedores de API adicione uma chave de nuvem (você pode guardar várias por provedor), escolha um modelo, marque favoritos, depois Usar para polimento — ou instale um modelo MLX local. Sem um mecanismo de polimento/tradução, Variante 1/2 e idioma forçado não inglês não melhorarão o texto.",
            .helpStart5: "Ditado: foque um app → Option+S → fale → Option+S de novo (HUD vermelho = gravando, verde = processando). Tradução instantânea: selecione texto em outro lugar → Option+1 → o painel flutuante captura seleção/área de transferência e traduz (Option+2 mostra apenas o resultado).",
            .helpModesTitle: "Quatro formas de trabalhar",
            .helpModeWindowTitle: "Janela principal",
            .helpModeWindowBody: "Um caderno para notas: grave ou importe áudio, revise Raw / Variante 1 / Variante 2, pula, traduza e copie. Ideal quando você quer editar e manter histórico.",
            .helpModeHotkeyTitle: "Atalho + HUD sobreposto",
            .helpModeHotkeyBody: "Fique dentro de outro app. O atalho primário (Option+S) grava com o HUD flutuante: modo de idioma (A / letra) e destino de saída (R / 1 / 2). Com o HUD visível, role para trocar o provedor de refinamento e clique com o botão direito em um provedor para escolher um modelo específico. Não rouba o foco do teclado enquanto você dita.",
            .helpModeFloatTitle: "Janela de tradução flutuante",
            .helpModeFloatBody: "O atalho Janela de tradução (padrão Option+1) abre um painel de tradução sempre no topo. Ele captura o texto selecionado do app ativo (com um Command-C rápido), preenche Original e pode traduzir imediatamente. Útil para uma mudança de idioma sem ditado completo.",
            .helpWindowTitle: "Janela principal",
            .helpWindowBody: "Esquerda: lista de notas. Direita: a nota selecionada — informações de áudio, menus de provedor/modelo de polimento, abas de texto e barra de ações.",
            .helpWindowNotes: "Barra lateral: selecione uma nota, Copiar tudo ou Limpar tudo (permanente: exclui cada nota e arquivos de gravação restantes no disco).",
            .helpWindowTabs: "Abas: Raw = transcrição pura. Variante 1 = limpeza leve (cacoetes, repetições). Variante 2 = reescrita mais forte para clareza. Use a ação Markdown em uma aba polida para estruturar o texto. Os slots de prompt D/1/2/3/4 trocam qual prompt personalizado está ativo para aquela variante.",
            .helpWindowActions: "Barra inferior: Gravar / Parar, Nota em branco, Importar áudio (ou arraste um arquivo para a janela), Traduzir, Polir, Copiar. Ajustes abre as preferências.",
            .helpWindowPolishingMenus: "Acima do editor você pode trocar o Provedor de polimento (Desativado / Limpeza rápida / MLX local / nuvem) e o Modelo de polimento (modelos do provedor de nuvem selecionado, ou cartões MLX locais). Isso corresponde a Ajustes → Provedores de API / Polimento sem sair da nota.",
            .helpHUDTitle: "HUD sobreposto (a cápsula flutuante)",
            .helpHUDIntro: "Quando você pressiona o atalho global, uma pequena cápsula flutuante aparece sobre cada app. Não é uma janela normal: fica no topo, não rouba o foco do teclado e mostra apenas o status — não a transcrição completa.",
            .helpHUDAnatomy: "Layout esquerda → direita: (1) botão de idioma · (2) forma de onda ao vivo no meio · (3) botão de destino de saída. Na sua tela geralmente aparece como [ A ] ≈≈≈ [ R ].",
            .helpHUDColorRed: "A forma de onda central fica vermelha enquanto o microfone grava. Fale enquanto estiver vermelha.",
            .helpHUDColorGreen: "Depois de parar (atalho de novo), a forma de onda fica verde: o SmartScribe está transcrevendo, polindo se necessário e entregando o texto. Espere até o HUD se ocultar.",
            .helpHUDLeftTitle: "Botão esquerdo — modo de idioma (A ↔ letra)",
            .helpHUDLeftA: "A = Auto. O SmartScribe mantém / detecta automaticamente o idioma falado. Sem tradução forçada. Use quando quiser a transcrição no mesmo idioma da sua fala.",
            .helpHUDLeftLetter: "Uma letra em vez de A significa “forçar idioma de destino”. A letra é a primeira letra do nome em inglês daquele idioma: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German, e assim por diante. Qual letra aparece depende de Ajustes → Atalho → Idioma de transcrição (ou Idioma de tradução automática do Glossário se o Atalho for Auto).",
            .helpHUDLeftTap: "Toque uma vez no botão esquerdo para trocar A → letra (destino forçado), toque de novo para trocar letra → A. A escolha é lembrada para a próxima sessão.",
            .helpHUDRightTitle: "Botão direito — destino de saída (R → 1 → 2)",
            .helpHUDRightR: "R = Raw. Entrega a transcrição simples sem polimento Variante 1 / Variante 2. Caminho mais rápido; ainda pode usar a tradução para inglês do Whisper quando o botão esquerdo é E.",
            .helpHUDRightCycle: "1 = Variante 1 (limpeza leve). 2 = Variante 2 (reescrita mais forte). Estes precisam de um mecanismo de polimento ativo (nuvem ou MLX local). Escolher 1 ou 2 reativa o polimento se estava desativado.",
            .helpHUDRightTap: "Toque no botão direito para alternar R → 1 → 2 → R. A seleção vira o novo Destino padrão nos ajustes do Atalho para ditados futuros.",
            .helpHUDControlLanguage: "Esquerda: A = auto / mesmo idioma da fala. Letra (E, S, R, …) = forçar aquele idioma de destino. Toque para alternar A ↔ letra.",
            .helpHUDControlTarget: "Direita: R = transcrição Raw, 1 = Variante 1, 2 = Variante 2. Toque para alternar R → 1 → 2 → R.",
            .helpHUDDrag: "Arrastar: clique e segure em qualquer lugar da cápsula (não só os botões) e mova para qualquer lugar em qualquer display. Coloque perto do canto, acima do dock ou ao lado do app em que digita — onde quiser.",
            .helpHUDSize: "Tamanho e transparência: Ajustes → Geral → HUD sobreposto. O controle Tamanho escala a cápsula inteira (e quantas barras de espectro você vê). A transparência desbota o fundo de vidro para o conteúdo da mesa aparecer mais ou menos.",
            .helpHUDSound: "Sons: mesma seção Geral → HUD sobreposto. Ative “Reproduzir som ao iniciar/terminar”, ajuste o Volume do som e use Testar sons do HUD para prévia sem gravar. Sinais tocam ao iniciar a gravação e ao terminar o processamento.",
            .helpHUDSettingsPath: "Todo o visual do HUD fica em Ajustes → Geral → HUD sobreposto (tamanho, transparência, som, volume). A posição é salva automaticamente depois de arrastar.",
            .helpHUDPosition: "Depois de arrastar o HUD, o SmartScribe lembra aquele ponto e reabre ali na próxima vez.",
            .helpHUDDuration: "Sem limite artificial curto de quanto você pode falar. Continue falando enquanto a forma de onda estiver vermelha; pressione o atalho de novo ao terminar.",
            .helpLangTitle: "Modos de idioma em detalhe",
            .helpLangIntro: "O controle de idioma é o botão esquerdo do HUD mais Ajustes → Atalho → Idioma de transcrição. Eles trabalham juntos.",
            .helpLangAuto: "A (auto): a transcrição fica no idioma falado. Ideal para notas no seu idioma nativo sem tradução.",
            .helpLangForced: "Letra (destino forçado): após o reconhecimento de fala, o SmartScribe mira um idioma de saída específico. Fale russo, receba inglês; fale inglês, receba espanhol — dependendo do destino configurado.",
            .helpLangEnglishNote: "Destino inglês + Whisper multilíngue: Raw usa a tradução integrada para inglês do Whisper no dispositivo (rápido). Prefira Large v3 Full para qualidade; Turbo é mais leve mas menos confiável em fala longa ou mista.",
            .helpLangOtherNote: "Qualquer destino não inglês sempre precisa de um LLM após o Whisper (nuvem ou MLX local). Sem um caminho de polimento ativo, espanhol/russo/… forçado não consegue converter o idioma.",
            .helpLangWhere: "Defina o destino em Atalho → Idioma de transcrição (English, Spanish, Russian, …). Se for Auto, o modo letra usa Glossário → Idioma de tradução automática, depois recai para inglês. A letra do HUD atualiza a partir dessa escolha.",
            .helpModelsTitle: "Modelos de transcrição locais",
            .helpModelsIntro: "Ajustes → Modelos locais gerencia modelos WhisperKit Core ML que transformam áudio em texto no Apple Silicon. Isso é separado dos modelos de polimento.",
            .helpModelsCatalog: "Somente inglês (Small/Medium .en): rápido quando você só fala inglês. Small/Medium multilíngues: multilíngue mais leve. Large v3 Turbo (~1,6 GB): modelo grande rápido. Large v3 Full (~3 GB, melhor qualidade): padrão recomendado para precisão e tradução para inglês.",
            .helpModelsRecommend: "Para idiomas mistos e inglês forçado (letra E do HUD), use um modelo multilíngue — idealmente Large v3 Full. Modelos somente inglês não conseguem traduzir nativamente outros idiomas para inglês.",
            .helpModelsUse: "Baixar → Usar (apenas um ativo). Excluir remove arquivos deste Mac. Não há fallback Apple Speech — escolha Whisper local (com um modelo baixado) ou Cloud · Google Gemini (chave de API Google necessária).",
            .helpHotkeyTitle: "Ajustes do atalho",
            .helpHotkeyIntro: "Ajustes → Atalho ativa quatro atalhos globais independentes. Ative Ativar atalho antes que qualquer um deles funcione.",
            .helpHotkeyPrimary: "Primário (padrão Option+S (⌥S)): inicia/para o ditado no HUD sobreposto. O primeiro toque grava (vermelho), o segundo processa (verde) e entrega Raw / Variante 1 / Variante 2.",
            .helpHotkeySecondary: "Janela de tradução (padrão Option+1): abre o painel de tradução flutuante completo. Não é um atalho de gravação — captura seleção/área de transferência e traduz. A seta de redefinição restaura Option+1.",
            .helpHotkeyTertiary: "Tradução rápida (padrão Option+2): abre uma janela mínima somente leitura com apenas o resultado traduzido. Pressione o atalho de novo ou Escape para fechar.",
            .helpHotkeySettings: "Abrir ajustes (padrão Option+~): abre a janela de ajustes do SmartScribe de qualquer lugar, para trocar modelos ou idiomas sem sair do seu app.",
            .helpModeQuickTitle: "Janela de tradução rápida",
            .helpModeQuickBody: "O atalho terciário (padrão Option+2) abre uma janela mínima sempre no topo que mostra apenas o resultado traduzido — sem painel de origem, sem botões. Leia e pressione Escape para dispensar. Para editar ou retraduzir, use a Janela de tradução flutuante completa.",
            .helpFloatQuick: "Duas janelas de tradução: a Janela de tradução flutuante (Option+1) é o painel completo com texto de origem, menus de provedor/modelo e controles; Tradução rápida (Option+2) é uma janela mínima somente leitura mostrando apenas o resultado. Use Tradução rápida quando só precisar ler uma tradução.",
            .helpHotkeyTarget: "Destino do ditado: qual texto é entregue após a gravação — Raw, Variante 1 ou Variante 2. Mesma escolha do botão direito do HUD (R / 1 / 2).",
            .helpHotkeyMode: "Modo do ditado: Área de transferência copia o resultado para você colar; Digitar no app ativo insere no campo que estava focado quando a gravação começou.",
            .helpHotkeyAccess: "Digitar no app ativo precisa de permissão de acessibilidade (mesma página de ajustes). O modo área de transferência e a Janela de tradução flutuante não exigem acessibilidade para colar no painel — mas capturar texto de outros apps com Command-C funciona melhor quando o app é confiável.",
            .helpFloatTitle: "Janela de tradução flutuante",
            .helpFloatIntro: "Um painel utilitário redimensionável, sempre no topo (SmartScribe Translation), separado do caderno principal. Ideal para mudança rápida de idioma enquanto você fica no navegador, e-mail ou chat.",
            .helpFloatHotkey: "Abra com o atalho Janela de tradução (Ajustes → Atalho → Janela de tradução, padrão Option+1). Você também pode abrir Traduzir na barra inferior da janela principal; o painel flutuante compartilha a mesma UI.",
            .helpFloatCapture: "Ao abrir, o SmartScribe envia brevemente Command-C ao app em primeiro plano para copiar qualquer seleção, depois prefere a seleção da nota se você estiver dentro do SmartScribe, senão o texto da área de transferência. Se algo foi capturado e um provedor de tradução está definido, a tradução inicia automaticamente.",
            .helpFloatPanel: "Dentro do painel: escolha Provedor e Modelo, defina Idioma de destino, edite Original, execute Traduzir / Traduzir de novo, ou grave um clipe curto para tradução. O painel fica flutuando sobre outros apps e pode ser redimensionado.",
            .helpFloatFavorites: "A lista de modelos na UI de tradução prefere modelos que você marcou como favoritos em Ajustes → Provedores de API (seletor buscável ★). Se não tiver favoritos para aquele provedor, o modelo atualmente selecionado é mostrado.",
            .helpFloatDoubleClick: "Dê clique duplo na área de texto Original (origem) para colar da área de transferência e traduzir imediatamente — prático depois que você mesmo copia texto.",
            .helpFloatEscape: "Pressione Escape ou o botão de fechar para dispensar o painel flutuante. Fechar não encerra o SmartScribe.",
            .helpCloudTitle: "Provedores de API de nuvem",
            .helpCloudIntro: "Ajustes → Provedores de API configura LLMs de nuvem para polimento e tradução — não para reconhecimento de fala Whisper. Layout: menu suspenso de provedor no topo, cartão de detalhes, depois estatísticas de uso.",
            .helpCloudProviders: "Ordem do menu suspenso: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic não é mostrado na UI atual.) Um selo Ativo marca o mecanismo usado para polimento.",
            .helpCloudConfigure: "Selecione um provedor, insira chave(s), abra Explorar modelos (folha buscável), escolha um modelo de texto, depois Usar para polimento. Obter chave de API abre o console do provedor quando disponível. Chips de modelo mostram comprimento de contexto e, quando disponíveis, preços de entrada/saída.",
            .helpCloudKeys: "Várias chaves de API: cada provedor pode guardar até 10 chaves (Adicionar chave). O ícone de olho mostra/oculta uma chave. A primeira chave não vazia é usada para requisições; extras ajudam a alternar ou separar chaves pessoais e de trabalho.",
            .helpCloudFavorites: "No seletor de modelos, marque modelos como favoritos (★). Favoritos vão para o topo e são preferidos no menu de modelos da Janela de tradução flutuante. Favoritos são guardados neste Mac.",
            .helpCloudOpenRouter: "OpenRouter: saldo da conta ao vivo (USD restantes com código de cores), catálogo buscável com contexto e preços de token $/M, e controle de atualização. Confira o saldo antes de sessões longas.",
            .helpCloudBudget: "O controle de orçamento do OpenRouter é um ajudante pessoal de limite suave nos Ajustes (guia visual de quanto você pretende gastar) — ele não corta a API por si só. Fique de olho no banner de saldo real para o crédito restante.",
            .helpCloudCustom: "Custom: qualquer URL base compatível com OpenAI + chave (proxies, auto-hospedado ou endpoints de fornecedor). Modelos carregam daquele endpoint após chave e URL definidos.",
            .helpCloudStats: "Estatísticas de uso no rodapé de Provedores de API: tokens da última transação e totais para o modelo selecionado. Redefinir estatísticas zera esses contadores.",
            .helpPolishTitle: "Polimento, MLX e prompts",
            .helpPolishIntro: "A transcrição transforma fala em texto. O polimento reescreve esse texto. Usam modelos e ajustes diferentes.",
            .helpPolishEngines: "Mecanismos: Polimento desativado (só Raw) · Limpeza local rápida (regras, sem LLM, totalmente offline) · Modelo MLX local · Provedor de nuvem de Provedores de API. Você pode trocar provedor/modelo na barra de ferramentas da nota principal e nos Ajustes.",
            .helpPolishMLX: "Ajustes → Polimento: baixe modelos do catálogo ou Busque modelos locais no disco. Prefira modelos instruct sem raciocínio; modelos de raciocínio/pensamento são mais lentos e podem vazar cadeia de pensamento na nota.",
            .helpPolishPrompts: "Ajustes → Prompts: edite Variante 1, Variante 2 e Markdown. Todo prompt deve manter o marcador \(PromptTemplate.transcriptionPlaceholder). Redefinir restaura o modelo embutido.",
            .helpMoreTitle: "Glossário, importação e tradução",
            .helpMoreGlossary: "O Glossário é um dicionário local de grafias e termos preferidos (origem → tradução, variantes, categorias). Ele não retreina o Whisper; reescreve o texto após reconhecimento/tradução. Ative-o, adicione entradas, ou selecione texto numa nota → Adicionar ao glossário. Exporte JSON antes de Limpar. O Idioma de tradução automática aqui dá suporte ao modo letra do HUD quando o idioma do Atalho é Auto.",
            .helpMoreImport: "Importe áudio ou solte um arquivo na janela para criar uma nota transcrita com o modelo de fala ativo.",
            .helpMoreTranslate: "Traduza da janela principal ou pelo painel flutuante Option+1 (Option+2 mostra só o resultado): seleção / área de transferência / ditado ao vivo → provedor + modelo + idioma de destino. A tradução muda o idioma de propósito; Variante 1/2 mantêm o mesmo idioma. O modo letra do HUD usa o mecanismo de tradução quando o destino não é inglês.",
            .helpPrivacyTitle: "Privacidade, armazenamento e diagnóstico",
            .helpPrivacyLocal: "Transcrição Whisper, Limpeza local rápida e polimento MLX local ficam neste Mac. Gravações são guardadas nas pastas de dados locais do app.",
            .helpPrivacyCloud: "Polimento em nuvem e tradução em nuvem enviam seu texto (e prompts) ao provedor selecionado. Use mecanismos locais quando as notas precisarem ficar privadas.",
            .helpPrivacyClear: "Limpar tudo exclui permanentemente todas as notas e esvazia a pasta de gravações, incluindo áudio órfão deixado por sessões interrompidas. Exporte antes se o conteúdo importar.",
            .helpPrivacyLogs: "Geral → Exportar registros do sistema para um arquivo de diagnóstico. Use o nível de registro Debug só ao solucionar problemas. Tema, escala da UI, tamanho/sons do HUD e idioma da interface também estão em Geral.",
            .helpTipsTitle: "Dicas comuns",
            .helpTipEnglish: "Precisa de saída em inglês de outros idiomas? Whisper multilíngue + letra E do HUD (ou Idioma de transcrição = English) + Large v3 Full.",
            .helpTipNonEnglish: "Precisa de saída em espanhol/russo/…? Defina esse idioma em Atalho, mude o HUD para a letra e mantenha um mecanismo de polimento em nuvem ou MLX ativo.",
            .helpTipDisk: "Disco cheio de modelos ou gravações? Exclua modelos Whisper não usados em Modelos locais; use Limpar tudo só quando pretender apagar notas e arquivos .caf restantes.",
            .helpTipStuck: "Atalho ou digitação travados? Confirme que o Atalho está ativado, o microfone funciona na janela principal, a Acessibilidade está concedida para o modo Digitar, depois tente Atualizar status. Exporte registros se ainda falhar.",
            .helpWelcomeTitle: "Ajuda do SmartScribe",
            .helpWelcomeBody: "Dite em qualquer lugar do seu Mac. A fala é transcrita no dispositivo com Whisper; o texto pode ficar bruto, ser limpo ou reescrito — depois copiado ou digitado no app que você estava usando.",
            .helpQuickStart: "Comece aqui (primeiros 5 minutos)",
