            .settingsHotkey: "快捷键",
            .settingsLocalModels: "本地模型",
            .settingsPolishing: "润色",
            .settingsPrompts: "提示词",
            .settingsStatistics: "统计",
            .settingsHelp: "帮助",
            .lastUsage: "最近使用",
            .totalUsageLabel: "总使用量",
            .lastTransactionDetails: "上次交易详情",
            .totalUsageFor: "%@ 的总使用量",
            .promptTokens: "提示 Token",
            .completionTokens: "补全 Token",
            .totalTokens: "总 Token",
            .selectedModel: "所选模型",
            .resetStats: "重置统计",
            .noUsageData: "暂无使用数据。",
            .accessibilityPermission: "辅助功能权限",
            .accessibilityTrusted: "已授予",
            .accessibilityNotTrusted: "未授予",
            .accessibilityPermissionDescription: "仅「输入到当前 App」需要。剪贴板模式不需要辅助功能权限。",
            .requestAccessibilityPermission: "请求权限",
            .openAccessibilitySettings: "打开辅助功能设置",
            .refreshPermissionStatus: "刷新状态",
            .helpHeroTitle: "SmartScribe 帮助",
            .helpHeroSubtitle: "在 Mac 的任何位置听写。语音通过 Whisper 在设备上转录；文本可保持原始、清理或重写 — 然后复制或输入到你正在使用的应用。",
            .helpStartTitle: "从这里开始（前 5 分钟）",
            .helpStart1: "当 macOS 询问时允许麦克风。没有它，录音无法开始。",
            .helpStart2: "打开「设置 → 本地模型」，下载一个 Whisper 模型（Large v3 Full 是最佳全能选择），然后按「使用」。",
            .helpStart3: "打开「设置 → 快捷键」并开启快捷键。主快捷键（默认 Option+S）用于听写。翻译窗口快捷键（默认 Option+1）打开完整的浮动翻译面板；快速翻译（默认 Option+2）仅显示结果；打开设置（默认 Option+~）打开偏好设置。听写时选择目标（原始 / 变体 1 / 变体 2）和模式（剪贴板或输入到当前 App）。",
            .helpStart4: "可选：在 API 提供商中添加云密钥（每个提供商可存储多个），选择模型，标星收藏，然后「使用」进行润色 — 或安装本地 MLX 模型。没有润色/翻译引擎时，变体 1/2 和非英语强制语言不会改进文本。",
            .helpStart5: "听写：聚焦任意 App → Option+S → 说话 → 再按 Option+S（红色 HUD = 录音中，绿色 = 处理中）。即时翻译：在别处选中文本 → Option+1 → 浮动面板捕获选区/剪贴板并翻译（Option+2 仅显示结果）。",
            .helpModesTitle: "四种工作方式",
            .helpModeWindowTitle: "主窗口",
            .helpModeWindowBody: "用于笔记的笔记本：录音或导入音频，查看 原始 / 变体 1 / 变体 2，润色、翻译和复制。适合需要编辑并保留历史时。",
            .helpModeHotkeyTitle: "快捷键 + 悬浮 HUD",
            .helpModeHotkeyBody: "留在其他应用内。主快捷键（Option+S）配合浮动 HUD 录音：语言模式（A / 字母）和输出目标（R / 1 / 2）。HUD 显示时，滚动可切换润色服务商，右键点按某个服务商可选择具体模型。听写时不会抢占键盘焦点。",
            .helpModeFloatTitle: "浮动翻译窗口",
            .helpModeFloatBody: "翻译窗口快捷键（默认 Option+1）打开始终置顶的翻译面板。它捕获当前应用中的选中文本（通过快速 Command-C），填充原文，并可立即翻译。适合无需完整听写的语言切换。",
            .helpWindowTitle: "主窗口",
            .helpWindowBody: "左侧：笔记列表。右侧：所选笔记 — 音频信息、润色提供商/模型菜单、文本标签页和操作栏。",
            .helpWindowNotes: "边栏：选择笔记、复制全部或清除全部（永久：删除每条笔记及磁盘上残留的录音文件）。",
            .helpWindowTabs: "标签页：原始 = 纯转录。变体 1 = 轻度清理（填充词、重复）。变体 2 = 更强的重写以提升清晰度。在润色标签页上使用 Markdown 操作来结构化文本。提示词槽位 D/1/2/3/4 切换该变体激活的自定义提示词。",
            .helpWindowActions: "底部栏：录音 / 停止、空白笔记、导入音频（或将文件拖入窗口）、翻译、润色、复制。「设置」打开偏好设置。",
            .helpWindowPolishingMenus: "在编辑器上方可切换润色提供商（禁用 / 快速清理 / 本地 MLX / 云）和润色模型（所选云提供商的模型，或本地 MLX 卡片）。这与「设置 → API 提供商 / 润色」一致，无需离开笔记。",
            .helpHUDTitle: "悬浮 HUD（浮动胶囊）",
            .helpHUDIntro: "按下全局快捷键时，一个小的浮动胶囊会出现在每个应用之上。它不是普通窗口：始终置顶、不抢占键盘焦点，仅显示状态 — 而非完整转录。",
            .helpHUDAnatomy: "布局 左 → 右：(1) 语言按钮 · (2) 中间的实时波形 · (3) 输出目标按钮。在你的屏幕上通常看起来像 [ A ] ≈≈≈ [ R ]。",
            .helpHUDColorRed: "麦克风录音时中间波形变红。红色时说话。",
            .helpHUDColorGreen: "停止后（再按快捷键），波形变绿：SmartScribe 正在转录、必要时润色并交付文本。等待 HUD 隐藏。",
            .helpHUDLeftTitle: "左按钮 — 语言模式（A ↔ 字母）",
            .helpHUDLeftA: "A = 自动。SmartScribe 保留 / 自动检测你所说的语言。不强制翻译。当你希望转录与语音同语言时使用。",
            .helpHUDLeftLetter: "字母而非 A 表示「强制目标语言」。字母是该语言英文名的首字母：E = English，S = Spanish，R = Russian，F = French，C = Chinese，G = German，依此类推。出现哪个字母取决于「设置 → 快捷键 → 转录语言」（或快捷键为自动时的术语表自动翻译语言）。",
            .helpHUDLeftTap: "点按左按钮一次切换 A → 字母（强制目标），再点按切换 字母 → A。该选择会在下次会话中记住。",
            .helpHUDRightTitle: "右按钮 — 输出目标（R → 1 → 2）",
            .helpHUDRightR: "R = 原始。交付纯转录，不做变体 1 / 变体 2 润色。最快路径；左按钮为 E 时仍可使用 Whisper 英语翻译。",
            .helpHUDRightCycle: "1 = 变体 1（轻度清理）。2 = 变体 2（更强重写）。这些需要激活的润色引擎（云或本地 MLX）。选择 1 或 2 会在润色被禁用时重新开启。",
            .helpHUDRightTap: "点按右按钮循环 R → 1 → 2 → R。该选择会成为快捷键设置中未来听写的新默认目标。",
            .helpHUDControlLanguage: "左：A = 自动 / 与语音同语言。字母（E、S、R、…）= 强制该目标语言。点按切换 A ↔ 字母。",
            .helpHUDControlTarget: "右：R = 原始转录，1 = 变体 1，2 = 变体 2。点按循环 R → 1 → 2 → R。",
            .helpHUDDrag: "拖动：在胶囊任意位置（不仅是按钮）点击并按住，移动到任意显示器的任意位置。放在角落附近、Dock 上方或你输入的应用旁边 — 随你喜欢。",
            .helpHUDSize: "大小与透明度：设置 → 通用 → 悬浮 HUD。「大小」滑块缩放整个胶囊（以及你看到的频谱条数量）。透明度淡化玻璃背景，使桌面内容透出更多或更少。",
            .helpHUDSound: "声音：同一「通用 → 悬浮 HUD」部分。切换「开始/结束时播放声音」，设置音量，并用「测试 HUD 声音」预览而无需录音。开始录音和处理结束时会播放提示音。",
            .helpHUDSettingsPath: "HUD 的所有外观都在「设置 → 通用 → 悬浮 HUD」下（大小、透明度、声音、音量）。拖动后位置会自动保存。",
            .helpHUDPosition: "拖动 HUD 后，SmartScribe 会记住该位置，下次在那里重新打开。",
            .helpHUDDuration: "对说话时长没有人为的短限制。波形为红色时继续说；完成后再次按快捷键。",
            .helpLangTitle: "语言模式详解",
            .helpLangIntro: "语言控制是 HUD 左按钮加「设置 → 快捷键 → 转录语言」。它们协同工作。",
            .helpLangAuto: "A（自动）：转录保持你所说的语言。适合母语笔记且无需翻译。",
            .helpLangForced: "字母（强制目标）：语音识别后，SmartScribe 瞄准特定输出语言。说俄语，得英语；说英语，得西班牙语 — 取决于配置的目标。",
            .helpLangEnglishNote: "目标英语 + 多语言 Whisper：原始使用 Whisper 内置的设备上翻译成英语（快速）。质量优先选 Large v3 Full；Turbo 更轻但在长语音或混合语音上较不可靠。",
            .helpLangOtherNote: "任何非英语目标始终需要在 Whisper 之后使用 LLM（云或本地 MLX）。没有激活的润色路径，强制西班牙语/俄语/… 无法转换语言。",
            .helpLangWhere: "在「快捷键 → 转录语言」下设置目标（English、Spanish、Russian、…）。若为自动，字母模式使用「术语表 → 自动翻译语言」，然后回退到英语。HUD 字母会根据该选择更新。",
            .helpModelsTitle: "本地转录模型",
            .helpModelsIntro: "「设置 → 本地模型」管理 WhisperKit Core ML 模型，在 Apple Silicon 上将音频转为文本。这与润色模型分开。",
            .helpModelsCatalog: "仅英语（Small/Medium .en）：只说英语时快速。多语言 Small/Medium：更轻的多语言。Large v3 Turbo（约 1.6 GB）：快速的大模型。Large v3 Full（约 3 GB，最佳质量）：推荐的默认，兼顾准确度与英语翻译。",
            .helpModelsRecommend: "对于混合语言和强制英语（HUD 字母 E），使用多语言模型 — 理想为 Large v3 Full。仅英语模型无法原生将其他语言翻译成英语。",
            .helpModelsUse: "下载 → 使用（仅一个激活）。删除会从此 Mac 移除文件。没有 Apple Speech 回退 — 选择本地 Whisper（带已下载模型）或 Cloud · Google Gemini（需要 Google API 密钥）。",
            .helpHotkeyTitle: "快捷键设置",
            .helpHotkeyIntro: "「设置 → 快捷键」启用四个独立的全局快捷键。在任一快捷键生效前先开启「启用快捷键」。",
            .helpHotkeyPrimary: "主快捷键（默认 Option+S（⌥S））：在悬浮 HUD 中开始/停止听写。第一次按录音（红色），第二次按处理（绿色）并交付 原始 / 变体 1 / 变体 2。",
            .helpHotkeySecondary: "翻译窗口（默认 Option+1）：打开完整的浮动翻译面板。不是录音快捷键 — 它捕获选区/剪贴板并翻译。重置箭头恢复 Option+1。",
            .helpHotkeyTertiary: "快速翻译（默认 Option+2）：打开仅含翻译结果的最小只读窗口。再按快捷键或 Esc 关闭。",
            .helpHotkeySettings: "打开设置（默认 Option+~）：从任何位置打开 SmartScribe 设置窗口，便于切换模型或语言而无需离开应用。",
            .helpModeQuickTitle: "快速翻译窗口",
            .helpModeQuickBody: "第三快捷键（默认 Option+2）打开一个最小的始终置顶窗口，仅显示翻译结果 — 无源文本窗格、无按钮。阅读后按 Esc 关闭。如需编辑或重新翻译，请改用完整的浮动翻译窗口。",
            .helpFloatQuick: "两个翻译窗口：浮动翻译窗口（Option+1）是包含源文本、提供商/模型菜单和控件的完整面板；快速翻译（Option+2）是仅显示结果的最小只读窗口。只需阅读翻译时使用快速翻译。",
            .helpHotkeyTarget: "听写目标：录音后交付哪个文本 — 原始、变体 1 或变体 2。与 HUD 右按钮（R / 1 / 2）相同。",
            .helpHotkeyMode: "听写模式：剪贴板复制结果供你粘贴；输入到当前 App 插入到录音开始时聚焦的字段。",
            .helpHotkeyAccess: "输入到当前 App 需要辅助功能权限（同一设置页）。剪贴板模式和浮动翻译窗口不需要辅助功能即可粘贴到面板 — 但通过 Command-C 从其他应用捕获文本在应用受信任时效果最佳。",
            .helpFloatTitle: "浮动翻译窗口",
            .helpFloatIntro: "一个可调整大小、始终置顶的工具面板（SmartScribe Translation），与主笔记本分开。适合在浏览器、邮件或聊天中快速切换语言。",
            .helpFloatHotkey: "用翻译窗口快捷键打开（设置 → 快捷键 → 翻译窗口，默认 Option+1）。也可从主窗口底部栏打开「翻译」；浮动面板共享相同界面。",
            .helpFloatCapture: "打开时，SmartScribe 会短暂向最前端应用发送 Command-C 以复制任何选区，然后若你在 SmartScribe 内则优先笔记选区，否则用剪贴板文本。若捕获到内容且已设置翻译提供商，翻译会自动开始。",
            .helpFloatPanel: "面板内：选择提供商和模型，设置目标语言，编辑原文，运行 翻译 / 再次翻译，或录制短片段进行翻译。面板保持浮在其他应用之上并可调整大小。",
            .helpFloatFavorites: "翻译界面中的模型列表优先你在「设置 → API 提供商」中标星的收藏模型（可搜索选择器 ★）。若该提供商没有收藏，则显示当前所选模型。",
            .helpFloatDoubleClick: "双击原文（源）文本区域可从剪贴板粘贴并立即翻译 — 在你自己复制文本后很方便。",
            .helpFloatEscape: "按 Esc 或关闭按钮关闭浮动面板。关闭不会退出 SmartScribe。",
            .helpCloudTitle: "云 API 提供商",
            .helpCloudIntro: "「设置 → API 提供商」配置用于润色和翻译的云 LLM — 不用于 Whisper 语音识别。布局：顶部提供商下拉菜单、详情卡片，然后是使用统计。",
            .helpCloudProviders: "下拉顺序：Google Gemini → OpenAI → Qwen → OpenRouter → Custom。（当前界面不显示 Anthropic。）激活徽章标记用于润色的引擎。",
            .helpCloudConfigure: "选择提供商，输入密钥，打开「浏览模型」（可搜索表单），选择文本模型，然后「使用」进行润色。「获取 API 密钥」在可用时打开提供商控制台。模型标签显示上下文长度，以及（若可用）输入/输出价格。",
            .helpCloudKeys: "多个 API 密钥：每个提供商最多可存储 10 个密钥（添加密钥）。眼睛图标显示/隐藏密钥。第一个非空密钥用于请求；额外的帮助你轮换或区分个人与工作密钥。",
            .helpCloudFavorites: "在模型选择器中，将模型标星为收藏（★）。收藏排在顶部，并在浮动翻译窗口的模型菜单中优先。收藏存储在此 Mac 上。",
            .helpCloudOpenRouter: "OpenRouter：实时账户余额（颜色编码的剩余美元）、带上下文和 $/M Token 价格的可搜索目录，以及刷新控件。长会话前检查余额。",
            .helpCloudBudget: "OpenRouter 预算滑块是设置中的个人软上限助手（关于你打算花费多少的视觉指引）— 它本身不会切断 API。关注真实余额横幅以了解剩余额度。",
            .helpCloudCustom: "Custom：任何 OpenAI 兼容的基础 URL + 密钥（代理、自托管或厂商端点）。设置密钥和 URL 后，模型从该端点加载。",
            .helpCloudStats: "API 提供商底部的使用统计：所选模型的上次交易 Token 和总计。「重置统计」清除这些计数器。",
            .helpPolishTitle: "润色、MLX 与提示词",
            .helpPolishIntro: "转录将语音转为文本。润色重写该文本。它们使用不同的模型和设置。",
            .helpPolishEngines: "引擎：润色禁用（仅原始）· 快速本地清理（规则，无 LLM，完全离线）· 本地 MLX 模型 · 来自 API 提供商的云提供商。你可以在主笔记工具栏以及设置中切换提供商/模型。",
            .helpPolishMLX: "「设置 → 润色」：下载目录模型或「扫描本地模型」查找磁盘上的模型。优先非推理 instruct 模型；推理/思考模型更慢，且可能将思维链泄漏到笔记中。",
            .helpPolishPrompts: "「设置 → 提示词」：编辑变体 1、变体 2 和 Markdown。每个提示词必须保留 \(PromptTemplate.transcriptionPlaceholder) 占位符。重置会恢复内置模板。",
            .helpMoreTitle: "术语表、导入与翻译",
            .helpMoreGlossary: "术语表是首选拼写和术语的本地词典（源 → 翻译、变体、类别）。它不重新训练 Whisper；而是在识别/翻译后重写文本。启用它、添加条目，或在笔记中选择文本 → 添加到术语表。清除前导出 JSON。此处的自动翻译语言在快捷键语言为自动时支持 HUD 字母模式。",
            .helpMoreImport: "导入音频或将文件拖到窗口上，用激活的语音模型创建转录笔记。",
            .helpMoreTranslate: "从主窗口或通过 Option+1 浮动面板翻译（Option+2 仅显示结果）：选区 / 剪贴板 / 实时听写 → 提供商 + 模型 + 目标语言。翻译有意改变语言；变体 1/2 保持相同语言。当目标不是英语时，HUD 字母模式使用翻译引擎。",
            .helpPrivacyTitle: "隐私、存储与诊断",
            .helpPrivacyLocal: "Whisper 转录、快速本地清理和本地 MLX 润色都保留在此 Mac 上。录音存储在应用的本地数据文件夹中。",
            .helpPrivacyCloud: "云润色和云翻译会将你的文本（和提示词）发送到所选提供商。当笔记需要保持私密时使用本地引擎。",
            .helpPrivacyClear: "清除全部会永久删除所有笔记并清空录音文件夹，包括中断会话遗留的孤立音频。如果在意内容，请先导出。",
            .helpPrivacyLogs: "「通用 → 导出系统日志」获取诊断文件。仅在排查问题时使用 Debug 日志级别。主题、界面缩放、HUD 大小/声音和界面语言也在「通用」下。",
            .helpTipsTitle: "常见技巧",
            .helpTipEnglish: "需要从其他语言输出英语？多语言 Whisper + HUD 字母 E（或转录语言 = English）+ Large v3 Full。",
            .helpTipNonEnglish: "需要西班牙语/俄语/… 输出？在「快捷键」下设置该语言，将 HUD 切换到字母，并保持云或 MLX 润色引擎激活。",
            .helpTipDisk: "磁盘被模型或录音占满？在「本地模型」中删除未使用的 Whisper 模型；仅在打算清除笔记和残留 .caf 文件时使用清除全部。",
            .helpTipStuck: "快捷键或输入卡住？确认快捷键已启用、麦克风在主窗口可用、输入模式已授予辅助功能，然后尝试「刷新状态」。若仍失败则导出日志。",
            .helpWelcomeTitle: "SmartScribe 帮助",
            .helpWelcomeBody: "在 Mac 的任何位置听写。语音通过 Whisper 在设备上转录；文本可保持原始、清理或重写 — 然后复制或输入到你正在使用的应用。",
            .helpQuickStart: "从这里开始（前 5 分钟）",
            .helpRecordStep: "点击进入其他应用 → 按快捷键（默认 Option+S）→ 说话 → 再按停止。红色 HUD = 录音中，绿色 = 处理中。",
            .helpVariantsStep: "原始是转录。变体 1 是轻度清理。变体 2 是更强的重写。Markdown 结构化润色文本。",
            .helpCopyStep: "复制当前标签页、从边栏复制全部笔记，或通过快捷键 剪贴板 / 输入到当前 App 交付。",
            .helpRecordingTitle: "悬浮 HUD",
            .helpHUDStep: "HUD：[A|字母] 波形 [R|1|2]。点按左侧 A↔E，右侧 R→1→2。任意拖动；大小/声音在「通用 → 悬浮 HUD」。",
            .helpOfflineTranscription: "本地转录模型",
