            .googleAPI: "Google API",
            .geminiModel: "Gemini モデル",
            .googleAPIBody: "音声は Google にアップロードされ、選択した Gemini モデルでまず軽く整えた Raw 文字起こしになります。HUD で Raw を選択できます。ターゲット 1 または 2 を選ぶと、「設定 → プロンプト」の対応プロンプトが別のテキスト専用リクエストとして続けて実行されます。",
            .scanForLocalModels: "ローカルモデルをスキャン",
