            .refreshPermissionStatus: "상태 새로 고침",
            .helpHeroTitle: "SmartScribe 도움말",
            .helpHeroSubtitle: "Mac 어디에서나 받아쓰기하세요. 음성은 Whisper로 기기에서 전사되며, 텍스트는 Raw로 유지하거나, 정리하거나, 다시 작성할 수 있고 — 그 후 복사하거나 사용 중이던 앱에 입력할 수 있습니다.",
            .helpStartTitle: "여기서 시작(첫 5분)",
            .helpStart1: "macOS가 요청하면 마이크를 허용하세요. 허용하지 않으면 녹음을 시작할 수 없습니다.",
            .helpStart2: "설정 → 로컬 모델을 열고, Whisper 모델을 다운로드(Large v3 Full이 가장 균형 잡힌 선택)한 후 '사용'을 누르세요.",
            .helpStart3: "설정 → 단축키를 열고 단축키를 켭니다. 기본(기본값 Option+S)은 받아쓰기입니다. 번역 창 단축키(기본값 Option+1)는 전체 플로팅 번역 패널을 열고, 빠른 번역(기본값 Option+2)은 결과만 표시하며, 설정 열기(기본값 Option+~)는 환경설정을 엽니다. 받아쓰기에서는 대상(Raw / 변형 1 / 변형 2)과 모드(클립보드 또는 활성 앱에 입력)를 선택하세요.",
            .helpStart4: "선택 사항: API 제공업체에서 클라우드 키를 추가(제공업체당 여러 개 저장 가능)하고, 모델을 선택하고, 즐겨찾기에 별표를 한 후 '사용'으로 다듬기 — 또는 로컬 MLX 모델을 설치하세요. 다듬기/번역 엔진이 없으면 변형 1/2과 비영어 강제 언어는 텍스트를 개선하지 않습니다.",
            .helpStart5: "받아쓰기: 아무 앱에 포커스 → Option+S → 말하기 → 다시 Option+S(빨간 HUD = 녹음 중, 초록 = 처리 중). 즉시 번역: 다른 곳에서 텍스트 선택 → Option+1 → 플로팅 패널이 선택/클립보드를 캡처해 번역(Option+2는 결과만 표시).",
            .helpModesTitle: "네 가지 작업 방식",
            .helpModeWindowTitle: "메인 창",
            .helpModeWindowBody: "메모를 위한 노트: 오디오를 녹음하거나 가져오고, Raw / 변형 1 / 변형 2를 검토하고, 다듬고, 번역하고, 복사합니다. 편집하고 기록을 남기고 싶을 때 최적입니다.",
            .helpModeHotkeyTitle: "단축키 + 오버레이 HUD",
            .helpModeHotkeyBody: "다른 앱 안에 머무릅니다. 기본 단축키(Option+S)는 플로팅 HUD로 녹음: 언어 모드(A / 글자)와 출력 대상(R / 1 / 2). HUD가 표시된 동안 스크롤하여 다듬기 제공자를 전환하고, 제공자를 오른쪽 클릭하여 특정 모델을 선택할 수 있습니다. 받아쓰는 동안 키보드 포커스를 빼앗지 않습니다.",
            .helpModeFloatTitle: "플로팅 번역 창",
            .helpModeFloatBody: "번역 창 단축키(기본값 Option+1)는 항상 맨 위의 번역 패널을 엽니다. 활성 앱에서 선택한 텍스트를 캡처(빠른 Command-C로)하고, 원본을 채우고, 즉시 번역할 수 있습니다. 전체 받아쓰기 없이 언어 전환이 필요할 때 유용합니다.",
            .helpWindowTitle: "메인 창",
            .helpWindowBody: "왼쪽: 메모 목록. 오른쪽: 선택한 메모 — 오디오 정보, 다듬기 제공업체/모델 메뉴, 텍스트 탭, 작업 막대.",
            .helpWindowNotes: "사이드바: 메모 선택, 모두 복사 또는 모두 지우기(영구적: 모든 메모와 디스크의 남은 녹음 파일 삭제).",
            .helpWindowTabs: "탭: Raw = 순수 전사. 변형 1 = 가벼운 정리(추임새, 반복). 변형 2 = 명확성을 위한 더 강한 재작성. 다듬은 탭에서 Markdown 작업으로 텍스트를 구조화. 프롬프트 슬롯 D/1/2/3/4로 해당 변형에 활성인 사용자 지정 프롬프트를 전환.",
            .helpWindowActions: "하단 막대: 녹음 / 중지, 빈 메모, 오디오 가져오기(또는 파일을 창에 드래그), 번역, 다듬기, 복사. 설정은 환경설정을 엽니다.",
            .helpWindowPolishingMenus: "편집기 위에서 다듬기 제공업체(비활성화 / 빠른 정리 / 로컬 MLX / 클라우드)와 다듬기 모델(선택한 클라우드 제공업체의 모델 또는 로컬 MLX 카드)을 전환할 수 있습니다. 이는 메모를 떠나지 않고 설정 → API 제공업체 / 다듬기와 일치합니다.",
            .helpHUDTitle: "오버레이 HUD(플로팅 캡슐)",
            .helpHUDIntro: "전역 단축키를 누르면 모든 앱 위에 작은 플로팅 캡슐이 나타납니다. 일반 창이 아니며 항상 맨 위에 머물고 키보드 포커스를 빼앗지 않으며 상태만 표시합니다 — 전체 전사가 아닙니다.",
            .helpHUDAnatomy: "레이아웃 왼쪽 → 오른쪽: (1) 언어 버튼 · (2) 가운데 실시간 파형 · (3) 출력 대상 버튼. 화면에서는 대개 [ A ] ≈≈≈ [ R ]처럼 보입니다.",
            .helpHUDColorRed: "마이크가 녹음하는 동안 가운데 파형이 빨간색이 됩니다. 빨간색일 때 말하세요.",
            .helpHUDColorGreen: "중지 후(다시 단축키), 파형이 초록색이 됩니다: SmartScribe가 전사하고, 필요하면 다듬고, 텍스트를 전달합니다. HUD가 숨겨질 때까지 기다리세요.",
            .helpHUDLeftTitle: "왼쪽 버튼 — 언어 모드(A ↔ 글자)",
            .helpHUDLeftA: "A = 자동. SmartScribe는 말한 언어를 유지 / 자동 감지합니다. 강제 번역 없음. 음성과 같은 언어로 전사하고 싶을 때 사용.",
            .helpHUDLeftLetter: "A 대신 글자는 '대상 언어 강제'를 의미합니다. 글자는 해당 언어 영어 이름의 첫 글자: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German 등. 어떤 글자가 나타나는지는 설정 → 단축키 → 전사 언어(또는 단축키가 자동일 때 용어집 자동 번역 언어)에 따라 다릅니다.",
            .helpHUDLeftTap: "왼쪽 버튼을 한 번 탭하여 A → 글자(강제 대상), 다시 탭하여 글자 → A로 전환. 선택은 다음 세션에 기억됩니다.",
            .helpHUDRightTitle: "오른쪽 버튼 — 출력 대상(R → 1 → 2)",
            .helpHUDRightR: "R = Raw. 변형 1 / 변형 2 다듬기 없이 순수 전사를 전달. 가장 빠른 경로; 왼쪽 버튼이 E일 때 Whisper 영어 번역을 여전히 사용 가능.",
            .helpHUDRightCycle: "1 = 변형 1(가벼운 정리). 2 = 변형 2(더 강한 재작성). 활성 다듬기 엔진(클라우드 또는 로컬 MLX)이 필요. 1 또는 2를 선택하면 비활성화되어 있던 다듬기가 다시 켜집니다.",
            .helpHUDRightTap: "오른쪽 버튼을 탭하여 R → 1 → 2 → R 순환. 선택은 향후 받아쓰기를 위해 단축키 설정의 새 기본 대상이 됩니다.",
            .helpHUDControlLanguage: "왼쪽: A = 자동 / 음성과 같은 언어. 글자(E, S, R, …) = 해당 대상 언어 강제. 탭하여 A ↔ 글자 전환.",
            .helpHUDControlTarget: "오른쪽: R = Raw 전사, 1 = 변형 1, 2 = 변형 2. 탭하여 R → 1 → 2 → R 순환.",
            .helpHUDDrag: "드래그: 캡슐의 아무 곳(버튼뿐 아니라)을 클릭하고 길게 눌러 아무 디스플레이의 아무 위치로 이동. 모서리 근처, Dock 위, 또는 입력하는 앱 옆에 — 원하는 곳에 두세요.",
            .helpHUDSize: "크기 및 투명도: 설정 → 일반 → 오버레이 HUD. 크기 슬라이더는 캡슐 전체(그리고 보이는 스펙트럼 막대 수)를 조절. 투명도는 유리 배경을 흐리게 하여 바탕화면 내용이 더 많이 또는 적게 비치게 합니다.",
            .helpHUDSound: "소리: 같은 일반 → 오버레이 HUD 섹션. '시작/종료 시 소리 재생'을 전환하고, 소리를 설정하고, 'HUD 소리 테스트'로 녹음 없이 미리보기. 녹음 시작 시와 처리 종료 시 신호음이 재생됩니다.",
            .helpHUDSettingsPath: "HUD의 모든 모양은 설정 → 일반 → 오버레이 HUD 아래(크기, 투명도, 소리, 음량). 위치는 드래그 후 자동 저장됩니다.",
            .helpHUDPosition: "HUD를 드래그하면 SmartScribe가 그 위치를 기억하고 다음에 거기서 다시 엽니다.",
            .helpHUDDuration: "말할 수 있는 길이에 짧은 인위적 제한이 없습니다. 파형이 빨간색인 동안 계속 말하세요; 끝나면 다시 단축키를 누릅니다.",
            .helpLangTitle: "언어 모드 상세",
            .helpLangIntro: "언어 제어는 HUD 왼쪽 버튼과 설정 → 단축키 → 전사 언어입니다. 함께 작동합니다.",
            .helpLangAuto: "A(자동): 전사는 말한 언어로 유지. 번역 없이 모국어 메모에 최적.",
            .helpLangForced: "글자(강제 대상): 음성 인식 후 SmartScribe는 특정 출력 언어를 목표로 합니다. 러시아어를 말하면 영어를, 영어를 말하면 스페인어를 — 구성된 대상에 따라.",
            .helpLangEnglishNote: "대상 영어 + 다국어 Whisper: Raw는 Whisper 내장 기기 위 영어 번역 사용(빠름). 품질에는 Large v3 Full 권장; Turbo는 더 가볍지만 길거나 혼합된 음성에서는 신뢰도가 낮음.",
            .helpLangOtherNote: "비영어 대상은 항상 Whisper 뒤에 LLM이 필요(클라우드 또는 로컬 MLX). 활성 다듬기 경로가 없으면 강제 스페인어/러시아어/…는 언어를 변환할 수 없습니다.",
            .helpLangWhere: "대상은 단축키 → 전사 언어(English, Spanish, Russian, …)에서 설정. 자동이면 글자 모드는 용어집 → 자동 번역 언어를 사용한 뒤 영어로 폴백. HUD 글자는 그 선택에서 업데이트됩니다.",
            .helpModelsTitle: "로컬 전사 모델",
            .helpModelsIntro: "설정 → 로컬 모델은 Apple Silicon에서 오디오를 텍스트로 변환하는 WhisperKit Core ML 모델을 관리합니다. 이는 다듬기 모델과 별개입니다.",
            .helpModelsCatalog: "영어 전용(Small/Medium .en): 영어만 말할 때 빠름. 다국어 Small/Medium: 더 가벼운 다국어. Large v3 Turbo(~1.6 GB): 빠른 대형 모델. Large v3 Full(~3 GB, 최고 품질): 정확도와 영어 번역에 권장되는 기본값.",
            .helpModelsRecommend: "혼합 언어와 강제 영어(HUD 글자 E)에는 다국어 모델을 사용 — 이상적으로는 Large v3 Full. 영어 전용 모델은 다른 언어를 영어로 네이티브 번역할 수 없습니다.",
            .helpModelsUse: "다운로드 → 사용(하나만 활성). 삭제는 이 Mac에서 파일을 제거. Apple Speech 폴백은 없습니다 — 로컬 Whisper(다운로드한 모델과 함께) 또는 Cloud · Google Gemini(Google API 키 필요)를 선택.",
            .helpHotkeyTitle: "단축키 설정",
            .helpHotkeyIntro: "설정 → 단축키는 네 개의 독립적인 전역 단축키를 활성화. 어떤 것이든 발동하려면 먼저 '단축키 활성화'를 켜세요.",
            .helpHotkeyPrimary: "기본(기본값 Option+S(⌥S)): 오버레이 HUD로 받아쓰기 시작/중지. 첫 번째 누름은 녹음(빨강), 두 번째 누름은 처리(초록)하고 Raw / 변형 1 / 변형 2를 전달.",
            .helpHotkeySecondary: "번역 창(기본값 Option+1): 전체 플로팅 번역 패널을 엽니다. 녹음 단축키가 아님 — 선택/클립보드를 캡처해 번역. 재설정 화살표는 Option+1을 복원.",
            .helpHotkeyTertiary: "빠른 번역(기본값 Option+2): 번역 결과만 있는 최소 읽기 전용 창을 엽니다. 다시 단축키 또는 Escape로 닫기.",
            .helpHotkeySettings: "설정 열기(기본값 Option+~): 어디서나 SmartScribe 설정 창을 열어 앱을 떠나지 않고 모델이나 언어를 전환할 수 있습니다.",
            .helpModeQuickTitle: "빠른 번역 창",
            .helpModeQuickBody: "세 번째 단축키(기본값 Option+2)는 번역 결과만 표시하는 최소 항상 맨 위 창을 엽니다 — 원본 창도 버튼도 없음. 읽고 Escape로 닫기. 편집이나 재번역에는 전체 플로팅 번역 창을 사용하세요.",
            .helpFloatQuick: "두 개의 번역 창: 플로팅 번역 창(Option+1)은 원본 텍스트, 제공업체/모델 메뉴, 컨트롤이 있는 전체 패널; 빠른 번역(Option+2)은 결과만 표시하는 최소 읽기 전용 창. 번역을 읽기만 하면 될 때 빠른 번역을 사용.",
            .helpHotkeyTarget: "받아쓰기 대상: 녹음 후 어떤 텍스트를 전달할지 — Raw, 변형 1 또는 변형 2. HUD 오른쪽 버튼(R / 1 / 2)과 같은 선택.",
            .helpHotkeyMode: "받아쓰기 모드: 클립보드는 결과를 복사하여 붙여넣을 수 있게; 활성 앱에 입력은 녹음 시작 시 포커스되어 있던 필드에 삽입.",
            .helpHotkeyAccess: "활성 앱에 입력은 손쉬운 사용 권한이 필요(같은 설정 페이지). 클립보드 모드와 플로팅 번역 창은 패널에 붙여넣기에 손쉬운 사용이 필요 없음 — 단 Command-C로 다른 앱에서 텍스트 캡처는 앱이 신뢰될 때 가장 잘 작동.",
            .helpFloatTitle: "플로팅 번역 창",
            .helpFloatIntro: "크기 조절 가능한 항상 맨 위 유틸리티 패널(SmartScribe Translation), 메인 노트와 별개. 브라우저, 메일, 채팅에 머무르며 빠른 언어 전환에 이상적.",
            .helpFloatHotkey: "번역 창 단축키로 열기(설정 → 단축키 → 번역 창, 기본값 Option+1). 메인 창 하단 막대에서 번역을 열 수도 있음; 플로팅 패널은 같은 UI를 공유.",
            .helpFloatCapture: "열면 SmartScribe는 맨 앞 앱에 잠깐 Command-C를 보내 선택을 복사하고, SmartScribe 안이면 메모 선택을 우선, 아니면 클립보드 텍스트. 무언가 캡처되고 번역 제공업체가 설정되어 있으면 번역이 자동 시작.",
            .helpFloatPanel: "패널 안에서: 제공업체와 모델 선택, 대상 언어 설정, 원본 편집, 번역 / 다시 번역 실행, 또는 번역용 짧은 클립 녹음. 패널은 다른 앱 위에 떠 있고 크기 조절 가능.",
            .helpFloatFavorites: "번역 UI의 모델 목록은 설정 → API 제공업체에서 즐겨찾기로 별표한 모델을 우선(검색 가능한 선택기 ★). 해당 제공업체에 즐겨찾기가 없으면 현재 선택한 모델이 표시.",
            .helpFloatDoubleClick: "원본(소스) 텍스트 영역을 더블클릭하면 클립보드에서 붙여넣고 즉시 번역 — 직접 텍스트를 복사한 후 편리.",
            .helpFloatEscape: "Escape 또는 닫기 버튼으로 플로팅 패널을 닫기. 닫아도 SmartScribe가 종료되지 않음.",
            .helpCloudTitle: "클라우드 API 제공업체",
            .helpCloudIntro: "설정 → API 제공업체는 다듬기와 번역용 클라우드 LLM을 구성 — Whisper 음성 인식용이 아님. 레이아웃: 상단에 제공업체 드롭다운, 세부 카드, 그리고 사용 통계.",
            .helpCloudProviders: "드롭다운 순서: Google Gemini → OpenAI → Qwen → OpenRouter → Custom. (Anthropic은 현재 UI에 표시되지 않음.) 활성 배지는 다듬기에 사용되는 엔진을 표시.",
            .helpCloudConfigure: "제공업체를 선택하고, 키를 입력하고, 모델 찾아보기(검색 가능한 시트)를 열고, 텍스트 모델을 선택한 후 '사용'으로 다듬기. 'API 키 얻기'는 가능할 때 제공업체 콘솔을 엽니다. 모델 칩은 컨텍스트 길이와, 가능한 경우 입력/출력 가격을 표시.",
            .helpCloudKeys: "여러 API 키: 각 제공업체는 최대 10개 키를 저장 가능(키 추가). 눈 아이콘으로 키 표시/숨김. 첫 번째 비어있지 않은 키가 요청에 사용; 추가 키는 로테이션이나 개인/업무 키 분리에 도움.",
            .helpCloudFavorites: "모델 선택기에서 모델을 즐겨찾기로 별표(★). 즐겨찾기는 위로 정렬되고 플로팅 번역 창 모델 메뉴에서 우선. 즐겨찾기는 이 Mac에 저장.",
            .helpCloudOpenRouter: "OpenRouter: 실시간 계정 잔액(색상 코딩된 잔여 USD), 컨텍스트와 $/M 토큰 가격이 있는 검색 가능한 카탈로그, 새로 고침 컨트롤. 긴 세션 전에 잔액 확인.",
            .helpCloudBudget: "OpenRouter 예산 슬라이더는 설정의 개인적 소프트 한도 도우미(얼마를 쓸지에 대한 시각적 안내) — 그 자체로 API를 차단하지 않음. 실제 잔액 배너로 잔여 크레딧을 주시.",
            .helpCloudCustom: "Custom: 모든 OpenAI 호환 기본 URL + 키(프록시, 자체 호스팅 또는 벤더 엔드포인트). 키와 URL 설정 후 모델은 해당 엔드포인트에서 로드.",
            .helpCloudStats: "API 제공업체 하단의 사용 통계: 선택한 모델의 마지막 거래 토큰과 합계. 통계 재설정은 해당 카운터를 지움.",
            .helpPolishTitle: "다듬기, MLX, 프롬프트",
            .helpPolishIntro: "전사는 음성을 텍스트로 변환. 다듬기는 그 텍스트를 재작성. 서로 다른 모델과 설정을 사용.",
            .helpPolishEngines: "엔진: 다듬기 비활성화(Raw만) · 빠른 로컬 정리(규칙, LLM 없음, 완전 오프라인) · 로컬 MLX 모델 · API 제공업체의 클라우드 제공업체. 메인 메모 도구막대와 설정 양쪽에서 제공업체/모델 전환 가능.",
            .helpPolishMLX: "설정 → 다듬기: 카탈로그 모델을 다운로드하거나 '로컬 모델 검색'으로 디스크에서 검색. 비추론 instruct 모델을 권장; 추론/생각 모델은 더 느리고 생각의 연쇄를 메모에 유출할 수 있음.",
            .helpPolishPrompts: "설정 → 프롬프트: 변형 1, 변형 2, Markdown 편집. 모든 프롬프트는 \(PromptTemplate.transcriptionPlaceholder) 자리 표시자를 유지해야 함. 재설정은 내장 템플릿을 복원.",
            .helpMoreTitle: "용어집, 가져오기, 번역",
            .helpMoreGlossary: "용어집은 선호 철자와 용어의 로컬 사전(소스 → 번역, 변형, 카테고리). Whisper를 재학습시키지 않음; 인식/번역 후 텍스트를 재작성. 활성화하고, 항목을 추가하거나, 메모에서 텍스트 선택 → 용어집에 추가. 지우기 전에 JSON 내보내기. 여기의 자동 번역 언어는 단축키 언어가 자동일 때 HUD 글자 모드를 지원.",
            .helpMoreImport: "오디오를 가져오거나 파일을 창에 놓아 활성 음성 모델로 전사된 메모를 생성.",
            .helpMoreTranslate: "메인 창에서 또는 Option+1 플로팅 패널로 번역(Option+2는 결과만 표시): 선택 / 클립보드 / 라이브 받아쓰기 → 제공업체 + 모델 + 대상 언어. 번역은 의도적으로 언어를 변경; 변형 1/2은 같은 언어 유지. 대상이 영어가 아닐 때 HUD 글자 모드는 번역 엔진을 사용.",
            .helpPrivacyTitle: "개인 정보 보호, 저장, 진단",
            .helpPrivacyLocal: "Whisper 전사, 빠른 로컬 정리, 로컬 MLX 다듬기는 이 Mac에 머무릅니다. 녹음은 앱의 로컬 데이터 폴더에 저장됩니다.",
            .helpPrivacyCloud: "클라우드 다듬기와 클라우드 번역은 텍스트(와 프롬프트)를 선택한 제공업체로 보냅니다. 메모를 비공개로 유지해야 할 때는 로컬 엔진을 사용하세요.",
            .helpPrivacyClear: "모두 지우기는 모든 메모를 영구 삭제하고, 중단된 세션이 남긴 고아 오디오를 포함해 녹음 폴더를 비웁니다. 내용이 중요하면 먼저 내보내세요.",
            .helpPrivacyLogs: "일반 → 시스템 로그 내보내기로 진단 파일을 얻습니다. 디버그 로그 수준은 문제 해결 중에만 사용. 테마, UI 스케일, HUD 크기/소리, 인터페이스 언어도 일반 아래에 있습니다.",
            .helpTipsTitle: "일반적인 팁",
            .helpTipEnglish: "다른 언어에서 영어 출력이 필요? 다국어 Whisper + HUD 글자 E(또는 전사 언어 = English) + Large v3 Full.",
            .helpTipNonEnglish: "스페인어/러시아어/… 출력이 필요? 단축키에서 해당 언어를 설정하고, HUD를 글자로 전환하고, 클라우드 또는 MLX 다듬기 엔진을 활성으로 유지.",
            .helpTipDisk: "디스크가 모델이나 녹음으로 가득? 로컬 모델에서 사용하지 않는 Whisper 모델을 삭제; 메모와 남은 .caf 파일을 지우려는 경우에만 모두 지우기를 사용.",
            .helpTipStuck: "단축키나 입력이 멈춤? 단축키가 활성화되어 있고, 메인 창에서 마이크가 작동하고, 입력 모드에 손쉬운 사용이 허용되었는지 확인한 후 상태 새로 고침을 시도. 그래도 실패하면 로그를 내보내기.",
            .helpWelcomeTitle: "SmartScribe 도움말",
            .helpWelcomeBody: "Mac 어디에서나 받아쓰기하세요. 음성은 Whisper로 기기에서 전사되며, 텍스트는 Raw로 유지하거나, 정리하거나, 다시 작성할 수 있고 — 그 후 복사하거나 사용 중이던 앱에 입력할 수 있습니다.",
            .helpQuickStart: "여기서 시작(첫 5분)",
            .helpRecordStep: "다른 앱을 클릭 → 단축키(기본값 Option+S) → 말하기 → 다시 눌러 중지. 빨간 HUD = 녹음 중, 초록 = 처리 중.",
            .helpVariantsStep: "Raw는 전사. 변형 1은 가벼운 정리. 변형 2는 더 강한 재작성. Markdown은 다듬은 텍스트를 구조화.",
            .helpCopyStep: "현재 탭 복사, 사이드바에서 모든 메모 복사, 또는 단축키 클립보드 / 활성 앱에 입력으로 전달.",
            .helpRecordingTitle: "오버레이 HUD",
            .helpHUDStep: "HUD: [A|글자] 파형 [R|1|2]. 왼쪽 탭 A↔E, 오른쪽 탭 R→1→2. 아무 데나 드래그; 크기/소리는 일반 → 오버레이 HUD.",
            .helpOfflineTranscription: "로컬 전사 모델",
            .helpOfflineModelStep: "설정 → 로컬 모델: WhisperKit 모델을 다운로드. 품질과 영어 번역에는 Large v3 Full 권장.",
            .helpOfflineActivateStep: "다운로드한 모델에서 '사용'을 누릅니다. 삭제는 디스크 공간을 확보. 폴백: Apple Speech.",
            .helpImportTitle: "가져오기 및 번역",
            .helpImportStep: "오디오를 가져오거나 파일을 창에 드래그하여 새 메모로 전사.",
            .helpTranslateStep: "번역 모달: 선택, 클립보드 또는 짧은 녹음 → 제공업체 + 대상 언어.",
            .helpPolishingProviders: "다듬기 엔진",
            .helpPolishingProviderStep: "비활성화, 빠른 로컬 정리, 로컬 MLX, 또는 API 제공업체의 클라우드 API 제공업체.",
            .helpPromptsStep: "설정 → 프롬프트에서 변형 1, 변형 2, Markdown. 전사 자리 표시자를 유지.",
            .helpHotkeyStep: "설정 → 단축키: Option+S 활성화, 대상과 모드 선택, 앱에 입력에만 손쉬운 사용 허용.",
