            .onboardingGlossaryExplanation: "يساعد المسرد SmartScribe على كتابة الأسماء والمصطلحات المتخصصة والاختصارات والكلمات التي يكثر التعرّف عليها بشكل خاطئ بالطريقة التي تفضلها. أضف الكتابة الصحيحة والصيغ الشائعة؛ وبعد النسخ أو الترجمة يستبدل SmartScribe هذه الصيغ تلقائيًا بالشكل الذي اخترته. يبقى المسرد على هذا الـ Mac ويمكن تعديله في أي وقت من الإعدادات.",
