            .refreshPermissionStatus: "स्थिति रीफ़्रेश करें",
            .helpHeroTitle: "SmartScribe सहायता",
            .helpHeroSubtitle: "अपने Mac पर कहीं भी डिक्टेट करें। वाणी Whisper से डिवाइस पर प्रतिलिपित होती है; टेक्स्ट Raw रह सकता है, साफ़ किया जा सकता है, या फिर से लिखा जा सकता है — फिर कॉपी या आपके उपयोग किए ऐप में टाइप किया जा सकता है।",
            .helpStartTitle: "यहाँ से शुरू करें (पहले 5 मिनट)",
            .helpStart1: "जब macOS पूछे तो माइक्रोफ़ोन की अनुमति दें। इसके बिना रिकॉर्डिंग शुरू नहीं हो सकती।",
            .helpStart2: "सेटिंग्स → स्थानीय मॉडल खोलें, Whisper मॉडल डाउनलोड करें (Large v3 Full सबसे अच्छा सर्वोत्तम विकल्प है), फिर “उपयोग करें” दबाएँ।",
            .helpStart3: "सेटिंग्स → हॉटकी खोलें और हॉटकी चालू करें। प्राथमिक (डिफ़ॉल्ट Option+S) डिक्टेशन है। अनुवाद विंडो हॉटकी (डिफ़ॉल्ट Option+1) पूर्ण फ़्लोटिंग अनुवाद पैनल खोलती है; त्वरित अनुवाद (डिफ़ॉल्ट Option+2) केवल परिणाम दिखाता है; सेटिंग्स खोलें (डिफ़ॉल्ट Option+~) प्राथमिकताएँ खोलता है। डिक्टेशन के लिए लक्ष्य (Raw / वेरिएंट 1 / वेरिएंट 2) और मोड (क्लिपबोर्ड या सक्रिय ऐप में टाइप करें) चुनें।",
            .helpStart4: "वैकल्पिक: API प्रदाता में क्लाउड कुंजी जोड़ें (प्रति प्रदाता कई रख सकते हैं), मॉडल चुनें, पसंदीदा पर स्टार लगाएँ, फिर परिष्करण के लिए “उपयोग करें” — या स्थानीय MLX मॉडल स्थापित करें। परिष्करण/अनुवाद इंजन के बिना, वेरिएंट 1/2 और गैर-अंग्रेज़ी बाध्य भाषा टेक्स्ट नहीं सुधारेंगे।",
            .helpStart5: "डिक्टेशन: किसी ऐप पर फ़ोकस करें → Option+S → बोलें → फिर Option+S (लाल HUD = रिकॉर्डिंग, हरा = प्रसंस्करण)। तत्काल अनुवाद: कहीं टेक्स्ट चुनें → Option+1 → फ़्लोटिंग पैनल चयन/क्लिपबोर्ड कैप्चर कर अनुवाद करता है (Option+2 केवल परिणाम दिखाता है)।",
            .helpModesTitle: "काम करने के चार तरीके",
            .helpModeWindowTitle: "मुख्य विंडो",
            .helpModeWindowBody: "नोट्स के लिए नोटबुक: ऑडियो रिकॉर्ड या आयात करें, Raw / वेरिएंट 1 / वेरिएंट 2 देखें, परिष्करण करें, अनुवाद करें और कॉपी करें। जब संपादन और इतिहास रखना हो तो सर्वोत्तम।",
            .helpModeHotkeyTitle: "हॉटकी + ओवरले HUD",
            .helpModeHotkeyBody: "दूसरे ऐप के अंदर रहें। प्राथमिक हॉटकी (Option+S) फ़्लोटिंग HUD से रिकॉर्ड करती है: भाषा मोड (A / अक्षर) और आउटपुट लक्ष्य (R / 1 / 2)। HUD दिखते समय, स्क्रॉल करके पॉलिशिंग प्रदाता बदलें, और किसी प्रदाता पर राइट-क्लिक करके विशिष्ट मॉडल चुनें। डिक्टेट करते समय कीबोर्ड फ़ोकस नहीं छीनता।",
            .helpModeFloatTitle: "फ़्लोटिंग अनुवाद विंडो",
            .helpModeFloatBody: "अनुवाद विंडो हॉटकी (डिफ़ॉल्ट Option+1) हमेशा-शीर्ष अनुवाद पैनल खोलती है। यह सक्रिय ऐप से चयनित टेक्स्ट कैप्चर करती है (त्वरित Command-C से), मूल भरती है, और तुरंत अनुवाद कर सकती है। पूर्ण डिक्टेशन के बिना भाषा परिवर्तन के लिए उपयोगी।",
            .helpWindowTitle: "मुख्य विंडो",
            .helpWindowBody: "बाएँ: नोट सूची। दाएँ: चयनित नोट — ऑडियो जानकारी, परिष्करण प्रदाता/मॉडल मेनू, टेक्स्ट टैब और क्रिया बार।",
            .helpWindowNotes: "साइडबार: नोट चुनें, सभी कॉपी करें, या सभी साफ़ करें (स्थायी: हर नोट और डिस्क पर बची रिकॉर्डिंग फ़ाइलें हटाता है)।",
            .helpWindowTabs: "टैब: Raw = शुद्ध प्रतिलेख। वेरिएंट 1 = हल्की सफ़ाई (फ़िलर, दोहराव)। वेरिएंट 2 = स्पष्टता के लिए मज़बूत पुनर्लेखन। परिष्कृत टैब पर Markdown क्रिया से टेक्स्ट संरचित करें। प्रॉम्प्ट स्लॉट D/1/2/3/4 उस वेरिएंट के लिए सक्रिय कस्टम प्रॉम्प्ट बदलते हैं।",
            .helpWindowActions: "निचला बार: रिकॉर्ड / रोकें, खाली नोट, ऑडियो आयात करें (या फ़ाइल विंडो पर खींचें), अनुवाद करें, परिष्करण करें, कॉपी करें। सेटिंग्स प्राथमिकताएँ खोलती है।",
            .helpWindowPolishingMenus: "संपादक के ऊपर आप परिष्करण प्रदाता (अक्षम / त्वरित सफ़ाई / स्थानीय MLX / क्लाउड) और परिष्करण मॉडल (चयनित क्लाउड प्रदाता के मॉडल, या स्थानीय MLX कार्ड) बदल सकते हैं। यह नोट छोड़े बिना सेटिंग्स → API प्रदाता / परिष्करण से मेल खाता है।",
            .helpHUDTitle: "ओवरले HUD (फ़्लोटिंग कैप्सूल)",
            .helpHUDIntro: "जब आप वैश्विक हॉटकी दबाते हैं, तो हर ऐप के ऊपर एक छोटा फ़्लोटिंग कैप्सूल दिखता है। यह सामान्य विंडो नहीं: यह शीर्ष पर रहता है, कीबोर्ड फ़ोकस नहीं छीनता, और केवल स्थिति दिखाता है — पूर्ण प्रतिलेख नहीं।",
            .helpHUDAnatomy: "लेआउट बाएँ → दाएँ: (1) भाषा बटन · (2) बीच में लाइव तरंग · (3) आउटपुट-लक्ष्य बटन। आपकी स्क्रीन पर अक्सर [ A ] ≈≈≈ [ R ] जैसा दिखता है।",
            .helpHUDColorRed: "माइक्रोफ़ोन रिकॉर्ड करते समय बीच की तरंग लाल हो जाती है। लाल रहते बोलें।",
            .helpHUDColorGreen: "रोकने के बाद (फिर हॉटकी), तरंग हरी हो जाती है: SmartScribe प्रतिलेखन कर रहा है, ज़रूरत पर परिष्करण कर रहा है, और टेक्स्ट पहुँचा रहा है। जब तक HUD छिप न जाए प्रतीक्षा करें।",
            .helpHUDLeftTitle: "बायाँ बटन — भाषा मोड (A ↔ अक्षर)",
            .helpHUDLeftA: "A = स्वतः। SmartScribe आपके बोली भाषा को रखता / स्वतः पहचानता है। कोई बाध्य अनुवाद नहीं। जब प्रतिलेख अपनी वाणी जैसी भाषा में चाहिए तब उपयोग करें।",
            .helpHUDLeftLetter: "A के बजाय अक्षर का अर्थ है “लक्ष्य भाषा बाध्य करें”। अक्षर उस भाषा के अंग्रेज़ी नाम का पहला अक्षर है: E = English, S = Spanish, R = Russian, F = French, C = Chinese, G = German, आदि। कौन-सा अक्षर दिखता है यह सेटिंग्स → हॉटकी → प्रतिलेखन भाषा (या हॉटकी स्वतः होने पर शब्दावली स्वतः अनुवाद भाषा) पर निर्भर करता है।",
            .helpHUDLeftTap: "बाएँ बटन को एक बार टैप कर A → अक्षर (बाध्य लक्ष्य) बदलें, फिर टैप कर अक्षर → A बदलें। चयन अगले सत्र के लिए याद रहता है।",
            .helpHUDRightTitle: "दायाँ बटन — आउटपुट लक्ष्य (R → 1 → 2)",
            .helpHUDRightR: "R = Raw। वेरिएंट 1 / वेरिएंट 2 परिष्करण के बिना सादा प्रतिलेख पहुँचाता है। सबसे तेज़ पथ; बायाँ बटन E होने पर भी Whisper अंग्रेज़ी-अनुवाद उपयोग कर सकता है।",
            .helpHUDRightCycle: "1 = वेरिएंट 1 (हल्की सफ़ाई)। 2 = वेरिएंट 2 (मज़बूत पुनर्लेखन)। इन्हें सक्रिय परिष्करण इंजन (क्लाउड या स्थानीय MLX) चाहिए। 1 या 2 चुनने से परिष्करण फिर चालू हो जाता है यदि अक्षम था।",
            .helpHUDRightTap: "दाएँ बटन टैप कर R → 1 → 2 → R चक्र चलाएँ। चयन भविष्य के डिक्टेशन के लिए हॉटकी सेटिंग्स में नया डिफ़ॉल्ट लक्ष्य बन जाता है।",
            .helpHUDControlLanguage: "बायाँ: A = स्वतः / वाणी जैसी भाषा। अक्षर (E, S, R, …) = उस लक्ष्य भाषा को बाध्य करें। A ↔ अक्षर टॉगल के लिए टैप करें।",
            .helpHUDControlTarget: "दायाँ: R = Raw प्रतिलेख, 1 = वेरिएंट 1, 2 = वेरिएंट 2। R → 1 → 2 → R चक्र के लिए टैप करें।",
            .helpHUDDrag: "खींचें: कैप्सूल पर कहीं भी (केवल बटन नहीं) क्लिक करके दबाए रखें और किसी भी डिस्प्ले पर कहीं भी ले जाएँ। कोने के पास, डॉक के ऊपर, या उस ऐप के बगल में जिसमें आप टाइप करते हैं — जहाँ चाहें रखें।",
            .helpHUDSize: "आकार और पारदर्शिता: सेटिंग्स → सामान्य → ओवरले HUD। आकार स्लाइडर पूरे कैप्सूल (और कितनी स्पेक्ट्रम पट्टियाँ दिखती हैं) को स्केल करता है। पारदर्शिता काँच की पृष्ठभूमि को धुँधला करती है ताकि डेस्कटॉप सामग्री अधिक या कम दिखे।",
            .helpHUDSound: "ध्वनियाँ: वही सामान्य → ओवरले HUD अनुभाग। “प्रारंभ/समापन पर ध्वनि चलाएँ” टॉगल करें, ध्वनि वॉल्यूम सेट करें, और रिकॉर्डिंग के बिना पूर्वावलोकन के लिए HUD ध्वनियाँ आज़माएँ उपयोग करें। रिकॉर्डिंग शुरू होने और प्रसंस्करण समाप्त होने पर संकेत बजते हैं।",
            .helpHUDSettingsPath: "HUD का सारा रूप-रंग सेटिंग्स → सामान्य → ओवरले HUD के अंतर्गत है (आकार, पारदर्शिता, ध्वनि, वॉल्यूम)। खींचने के बाद स्थिति स्वतः सहेजी जाती है।",
            .helpHUDPosition: "HUD खींचने के बाद, SmartScribe उस स्थान को याद रखता है और अगली बार वहीं खोलता है।",
            .helpHUDDuration: "आप कितनी देर बोल सकते हैं इस पर कोई छोटी कृत्रिम सीमा नहीं। तरंग लाल रहते बोलते रहें; समाप्त होने पर फिर हॉटकी दबाएँ।",
            .helpLangTitle: "विस्तार से भाषा मोड",
            .helpLangIntro: "भाषा नियंत्रण HUD बायाँ बटन और सेटिंग्स → हॉटकी → प्रतिलेखन भाषा है। ये साथ काम करते हैं।",
            .helpLangAuto: "A (स्वतः): प्रतिलेख आपकी बोली भाषा में रहता है। बिना अनुवाद के अपनी मातृभाषा में नोट्स के लिए सर्वोत्तम।",
            .helpLangForced: "अक्षर (बाध्य लक्ष्य): वाणी पहचान के बाद, SmartScribe एक विशिष्ट आउटपुट भाषा लक्ष्य करता है। रूसी बोलें, अंग्रेज़ी पाएँ; अंग्रेज़ी बोलें, स्पेनिश पाएँ — कॉन्फ़िगर किए लक्ष्य के अनुसार।",
            .helpLangEnglishNote: "लक्ष्य अंग्रेज़ी + बहुभाषी Whisper: Raw डिवाइस पर Whisper के अंतर्निहित अंग्रेज़ी-में-अनुवाद का उपयोग करता है (तेज़)। गुणवत्ता के लिए Large v3 Full बेहतर; Turbo हल्का है पर लंबी या मिश्रित वाणी पर कम विश्वसनीय।",
            .helpLangOtherNote: "कोई भी गैर-अंग्रेज़ी लक्ष्य हमेशा Whisper के बाद LLM चाहता है (क्लाउड या स्थानीय MLX)। सक्रिय परिष्करण पथ के बिना, बाध्य स्पेनिश/रूसी/… भाषा नहीं बदल सकता।",
            .helpLangWhere: "लक्ष्य हॉटकी → प्रतिलेखन भाषा (English, Spanish, Russian, …) के अंतर्गत सेट करें। यदि स्वतः है, तो अक्षर मोड शब्दावली → स्वतः अनुवाद भाषा उपयोग करता है, फिर अंग्रेज़ी पर फ़ॉलबैक। HUD अक्षर उस चयन से अपडेट होता है।",
            .helpModelsTitle: "स्थानीय प्रतिलेखन मॉडल",
            .helpModelsIntro: "सेटिंग्स → स्थानीय मॉडल WhisperKit Core ML मॉडल प्रबंधित करता है जो Apple Silicon पर ऑडियो को टेक्स्ट में बदलते हैं। यह परिष्करण मॉडल से अलग है।",
            .helpModelsCatalog: "केवल अंग्रेज़ी (Small/Medium .en): जब आप केवल अंग्रेज़ी बोलते हों तो तेज़। बहुभाषी Small/Medium: हल्का बहु-भाषा। Large v3 Turbo (~1.6 GB): तेज़ बड़ा मॉडल। Large v3 Full (~3 GB, सर्वोत्तम गुणवत्ता): सटीकता और अंग्रेज़ी अनुवाद के लिए अनुशंसित डिफ़ॉल्ट।",
            .helpModelsRecommend: "मिश्रित भाषाओं और बाध्य अंग्रेज़ी (HUD अक्षर E) के लिए बहुभाषी मॉडल उपयोग करें — आदर्शतः Large v3 Full। केवल-अंग्रेज़ी मॉडल अन्य भाषाओं को अंग्रेज़ी में मूल रूप से अनुवाद नहीं कर सकते।",
            .helpModelsUse: "डाउनलोड → उपयोग करें (केवल एक सक्रिय)। हटाएँ इस Mac से फ़ाइलें हटाता है। कोई Apple Speech फ़ॉलबैक नहीं — स्थानीय Whisper (डाउनलोड किए मॉडल के साथ) या Cloud · Google Gemini (Google API कुंजी आवश्यक) चुनें।",
            .helpHotkeyTitle: "हॉटकी सेटिंग्स",
            .helpHotkeyIntro: "सेटिंग्स → हॉटकी चार स्वतंत्र वैश्विक शॉर्टकट सक्षम करता है। किसी के सक्रिय होने से पहले हॉटकी सक्षम करें चालू करें।",
            .helpHotkeyPrimary: "प्राथमिक (डिफ़ॉल्ट Option+S (⌥S)): ओवरले HUD में डिक्टेशन प्रारंभ/रोकें। पहला दबाना रिकॉर्ड करता है (लाल), दूसरा दबाना संसाधित करता है (हरा) और Raw / वेरिएंट 1 / वेरिएंट 2 पहुँचाता है।",
            .helpHotkeySecondary: "अनुवाद विंडो (डिफ़ॉल्ट Option+1): पूर्ण फ़्लोटिंग अनुवाद पैनल खोलता है। रिकॉर्डिंग हॉटकी नहीं — यह चयन/क्लिपबोर्ड कैप्चर कर अनुवाद करता है। रीसेट तीर Option+1 बहाल करता है।",
            .helpHotkeyTertiary: "त्वरित अनुवाद (डिफ़ॉल्ट Option+2): केवल अनुवाद परिणाम वाली न्यूनतम केवल-पठन विंडो खोलता है। बंद करने के लिए फिर हॉटकी या Escape दबाएँ।",
            .helpHotkeySettings: "सेटिंग्स खोलें (डिफ़ॉल्ट Option+~): कहीं से भी SmartScribe सेटिंग्स विंडो खोलता है, ताकि आप ऐप छोड़े बिना मॉडल या भाषाएँ बदल सकें।",
            .helpModeQuickTitle: "त्वरित अनुवाद विंडो",
            .helpModeQuickBody: "तृतीयक हॉटकी (डिफ़ॉल्ट Option+2) एक न्यूनतम हमेशा-शीर्ष विंडो खोलती है जो केवल अनुवाद परिणाम दिखाती है — कोई स्रोत फलक नहीं, कोई बटन नहीं। पढ़ें, फिर हटाने के लिए Escape दबाएँ। संपादन या पुनः अनुवाद के लिए पूर्ण फ़्लोटिंग अनुवाद विंडो उपयोग करें।",
            .helpFloatQuick: "दो अनुवाद विंडो: फ़्लोटिंग अनुवाद विंडो (Option+1) स्रोत टेक्स्ट, प्रदाता/मॉडल मेनू और नियंत्रणों वाला पूर्ण पैनल है; त्वरित अनुवाद (Option+2) केवल परिणाम दिखाने वाली न्यूनतम केवल-पठन विंडो है। जब केवल अनुवाद पढ़ना हो तो त्वरित अनुवाद उपयोग करें।",
            .helpHotkeyTarget: "डिक्टेशन लक्ष्य: रिकॉर्डिंग के बाद कौन-सा टेक्स्ट पहुँचाया जाए — Raw, वेरिएंट 1, या वेरिएंट 2। HUD दाएँ बटन (R / 1 / 2) जैसा ही चयन।",
            .helpHotkeyMode: "डिक्टेशन मोड: क्लिपबोर्ड परिणाम कॉपी करता है ताकि आप पेस्ट कर सकें; सक्रिय ऐप में टाइप करें उस फ़ील्ड में डालता है जो रिकॉर्डिंग शुरू होने पर फ़ोकस में था।",
            .helpHotkeyAccess: "सक्रिय ऐप में टाइप करें को ऐक्सेसिबिलिटी अनुमति चाहिए (वही सेटिंग्स पृष्ठ)। क्लिपबोर्ड मोड और फ़्लोटिंग अनुवाद विंडो को पैनल में पेस्ट के लिए ऐक्सेसिबिलिटी नहीं चाहिए — पर Command-C से अन्य ऐप्स से टेक्स्ट कैप्चर तब सबसे अच्छा काम करता है जब ऐप विश्वसनीय हो।",
            .helpFloatTitle: "फ़्लोटिंग अनुवाद विंडो",
            .helpFloatIntro: "एक आकार-परिवर्तनीय, हमेशा-शीर्ष उपयोगिता पैनल (SmartScribe Translation), मुख्य नोटबुक से अलग। ब्राउज़र, मेल या चैट में रहते हुए त्वरित भाषा परिवर्तन के लिए आदर्श।",
            .helpFloatHotkey: "इसे अनुवाद विंडो हॉटकी से खोलें (सेटिंग्स → हॉटकी → अनुवाद विंडो, डिफ़ॉल्ट Option+1)। आप मुख्य विंडो निचले बार से भी अनुवाद खोल सकते हैं; फ़्लोटिंग पैनल वही UI साझा करता है।",
            .helpFloatCapture: "खोलने पर, SmartScribe संक्षेप में सबसे आगे के ऐप को Command-C भेजता है ताकि कोई चयन कॉपी हो, फिर यदि आप SmartScribe के अंदर हैं तो नोट चयन को प्राथमिकता देता है, अन्यथा क्लिपबोर्ड टेक्स्ट। यदि कुछ कैप्चर हुआ और अनुवाद प्रदाता सेट है, तो अनुवाद स्वतः शुरू होता है।",
            .helpFloatPanel: "पैनल के अंदर: प्रदाता और मॉडल चुनें, लक्ष्य भाषा सेट करें, मूल संपादित करें, अनुवाद करें / फिर अनुवाद करें चलाएँ, या अनुवाद के लिए छोटी क्लिप रिकॉर्ड करें। पैनल अन्य ऐप्स के ऊपर फ़्लोटिंग रहता है और आकार बदला जा सकता है।",
            .helpFloatFavorites: "अनुवाद UI में मॉडल सूची उन मॉडलों को प्राथमिकता देती है जिन्हें आपने सेटिंग्स → API प्रदाता में पसंदीदा के रूप में स्टार किया (खोजने योग्य पिकर ★)। यदि उस प्रदाता के लिए कोई पसंदीदा नहीं, तो वर्तमान चयनित मॉडल दिखाया जाता है।",
            .helpFloatDoubleClick: "मूल (स्रोत) टेक्स्ट क्षेत्र पर डबल-क्लिक कर क्लिपबोर्ड से पेस्ट करें और तुरंत अनुवाद करें — स्वयं टेक्स्ट कॉपी करने के बाद सुविधाजनक।",
            .helpFloatEscape: "फ़्लोटिंग पैनल हटाने के लिए Escape या बंद करें बटन दबाएँ। बंद करने से SmartScribe बंद नहीं होता।",
            .helpCloudTitle: "क्लाउड API प्रदाता",
            .helpCloudIntro: "सेटिंग्स → API प्रदाता परिष्करण और अनुवाद के लिए क्लाउड LLM कॉन्फ़िगर करता है — Whisper वाणी पहचान के लिए नहीं। लेआउट: शीर्ष पर प्रदाता ड्रॉपडाउन, विवरण कार्ड, फिर उपयोग आँकड़े।",
            .helpCloudProviders: "ड्रॉपडाउन क्रम: Google Gemini → OpenAI → Qwen → OpenRouter → Custom। (Anthropic वर्तमान UI में नहीं दिखाया जाता।) सक्रिय बैज परिष्करण के लिए उपयोग किए इंजन को चिह्नित करता है।",
            .helpCloudConfigure: "प्रदाता चुनें, कुंजी(याँ) दर्ज करें, मॉडल ब्राउज़ करें (खोजने योग्य शीट) खोलें, टेक्स्ट मॉडल चुनें, फिर परिष्करण के लिए “उपयोग करें”। API कुंजी प्राप्त करें उपलब्ध होने पर प्रदाता का कंसोल खोलता है। मॉडल चिप संदर्भ लंबाई और, उपलब्ध होने पर, इनपुट/आउटपुट मूल्य दिखाते हैं।",
            .helpCloudKeys: "कई API कुंजियाँ: प्रत्येक प्रदाता अधिकतम 10 कुंजियाँ रख सकता है (कुंजी जोड़ें)। आँख आइकन कुंजी दिखाता/छिपाता है। पहली गैर-रिक्त कुंजी अनुरोधों के लिए उपयोग होती है; अतिरिक्त कुंजियाँ घुमाने या व्यक्तिगत बनाम कार्य कुंजियाँ अलग रखने में मदद करती हैं।",
            .helpCloudFavorites: "मॉडल पिकर में, मॉडलों को पसंदीदा के रूप में स्टार करें (★)। पसंदीदा शीर्ष पर क्रमबद्ध होते हैं और फ़्लोटिंग अनुवाद विंडो मॉडल मेनू में प्राथमिकता पाते हैं। पसंदीदा इस Mac पर संग्रहीत होते हैं।",
            .helpCloudOpenRouter: "OpenRouter: लाइव खाता शेष (रंग-कोडित शेष USD), संदर्भ और $/M टोकन मूल्यों वाला खोजने योग्य कैटलॉग, और रीफ़्रेश नियंत्रण। लंबे सत्रों से पहले शेष जाँचें।",
            .helpCloudBudget: "OpenRouter बजट स्लाइडर सेटिंग्स में व्यक्तिगत सॉफ़्ट-लिमिट सहायक है (आप कितना खर्च करना चाहते हैं इसका दृश्य मार्गदर्शन) — यह स्वयं API नहीं काटता। शेष क्रेडिट के लिए वास्तविक शेष बैनर देखें।",
            .helpCloudCustom: "Custom: कोई भी OpenAI-संगत बेस URL + कुंजी (प्रॉक्सी, स्व-होस्टेड, या विक्रेता एंडपॉइंट)। कुंजी और URL सेट होने के बाद मॉडल उस एंडपॉइंट से लोड होते हैं।",
            .helpCloudStats: "API प्रदाता के निचले भाग में उपयोग आँकड़े: चयनित मॉडल के लिए अंतिम लेन-देन टोकन और कुल। आँकड़े रीसेट करें उन काउंटरों को साफ़ करता है।",
            .helpPolishTitle: "परिष्करण, MLX और प्रॉम्प्ट",
            .helpPolishIntro: "प्रतिलेखन वाणी को टेक्स्ट में बदलता है। परिष्करण उस टेक्स्ट को फिर से लिखता है। ये अलग मॉडल और सेटिंग्स उपयोग करते हैं।",
            .helpPolishEngines: "इंजन: परिष्करण अक्षम (केवल Raw) · त्वरित स्थानीय सफ़ाई (नियम, कोई LLM नहीं, पूरी तरह ऑफ़लाइन) · स्थानीय MLX मॉडल · API प्रदाता से क्लाउड प्रदाता। आप मुख्य नोट टूलबार और सेटिंग्स दोनों से प्रदाता/मॉडल बदल सकते हैं।",
            .helpPolishMLX: "सेटिंग्स → परिष्करण: कैटलॉग मॉडल डाउनलोड करें या डिस्क पर स्थानीय मॉडल स्कैन करें। गैर-रीज़निंग instruct मॉडल बेहतर; रीज़निंग/थिंकिंग मॉडल धीमे होते हैं और नोट में विचार-शृंखला लीक कर सकते हैं।",
            .helpPolishPrompts: "सेटिंग्स → प्रॉम्प्ट: वेरिएंट 1, वेरिएंट 2 और Markdown संपादित करें। हर प्रॉम्प्ट को \(PromptTemplate.transcriptionPlaceholder) प्लेसहोल्डर रखना होगा। रीसेट अंतर्निहित टेम्पलेट बहाल करता है।",
            .helpMoreTitle: "शब्दावली, आयात और अनुवाद",
            .helpMoreGlossary: "शब्दावली पसंदीदा वर्तनी और शब्दों का स्थानीय शब्दकोश है (स्रोत → अनुवाद, वेरिएंट, श्रेणियाँ)। यह Whisper को पुनः प्रशिक्षित नहीं करता; पहचान/अनुवाद के बाद टेक्स्ट फिर से लिखता है। इसे सक्षम करें, प्रविष्टियाँ जोड़ें, या नोट में टेक्स्ट चुनें → शब्दावली में जोड़ें। साफ़ करने से पहले JSON निर्यात करें। यहाँ की स्वतः अनुवाद भाषा हॉटकी भाषा स्वतः होने पर HUD अक्षर मोड का समर्थन करती है।",
            .helpMoreImport: "ऑडियो आयात करें या सक्रिय वाणी मॉडल से प्रतिलिखित नोट बनाने के लिए विंडो पर फ़ाइल छोड़ें।",
            .helpMoreTranslate: "मुख्य विंडो से या Option+1 फ़्लोटिंग पैनल से अनुवाद करें (Option+2 केवल परिणाम दिखाता है): चयन / क्लिपबोर्ड / लाइव डिक्टेशन → प्रदाता + मॉडल + लक्ष्य भाषा। अनुवाद जानबूझकर भाषा बदलता है; वेरिएंट 1/2 वही भाषा रखते हैं। लक्ष्य अंग्रेज़ी न होने पर HUD अक्षर मोड अनुवाद इंजन उपयोग करता है।",
            .helpPrivacyTitle: "गोपनीयता, भंडारण और निदान",
            .helpPrivacyLocal: "Whisper प्रतिलेखन, त्वरित स्थानीय सफ़ाई और स्थानीय MLX परिष्करण इस Mac पर रहते हैं। रिकॉर्डिंग ऐप के स्थानीय डेटा फ़ोल्डरों में संग्रहीत होती हैं।",
            .helpPrivacyCloud: "क्लाउड परिष्करण और क्लाउड अनुवाद आपका टेक्स्ट (और प्रॉम्प्ट) चयनित प्रदाता को भेजते हैं। जब नोट्स निजी रहने चाहिए तो स्थानीय इंजन उपयोग करें।",
            .helpPrivacyClear: "सभी साफ़ करें सभी नोट्स स्थायी रूप से हटाता है और रिकॉर्डिंग फ़ोल्डर खाली करता है, जिसमें बाधित सत्रों से बचा अनाथ ऑडियो शामिल है। यदि सामग्री महत्वपूर्ण है तो पहले निर्यात करें।",
            .helpPrivacyLogs: "निदान फ़ाइल के लिए सामान्य → सिस्टम लॉग निर्यात करें। समस्या निवारण के दौरान ही डीबग लॉग स्तर उपयोग करें। थीम, UI स्केल, HUD आकार/ध्वनियाँ और इंटरफ़ेस भाषा भी सामान्य के अंतर्गत हैं।",
            .helpTipsTitle: "सामान्य सुझाव",
            .helpTipEnglish: "अन्य भाषाओं से अंग्रेज़ी आउटपुट चाहिए? बहुभाषी Whisper + HUD अक्षर E (या प्रतिलेखन भाषा = English) + Large v3 Full।",
            .helpTipNonEnglish: "स्पेनिश/रूसी/… आउटपुट चाहिए? हॉटकी के अंतर्गत वह भाषा सेट करें, HUD को अक्षर पर स्विच करें, और क्लाउड या MLX परिष्करण इंजन सक्रिय रखें।",
            .helpTipDisk: "डिस्क मॉडलों या रिकॉर्डिंग से भरी? स्थानीय मॉडल में अप्रयुक्त Whisper मॉडल हटाएँ; नोट्स और बची .caf फ़ाइलें मिटाने के इरादे से ही सभी साफ़ करें उपयोग करें।",
            .helpTipStuck: "हॉटकी या टाइपिंग अटकी? पुष्टि करें कि हॉटकी सक्षम है, मुख्य विंडो में माइक्रोफ़ोन काम करता है, टाइप मोड के लिए ऐक्सेसिबिलिटी प्रदान की गई है, फिर स्थिति रीफ़्रेश करें आज़माएँ। फिर भी विफल हो तो लॉग निर्यात करें।",
            .helpWelcomeTitle: "SmartScribe सहायता",
            .helpWelcomeBody: "अपने Mac पर कहीं भी डिक्टेट करें। वाणी Whisper से डिवाइस पर प्रतिलिपित होती है; टेक्स्ट Raw रह सकता है, साफ़ किया जा सकता है, या फिर से लिखा जा सकता है — फिर कॉपी या आपके उपयोग किए ऐप में टाइप किया जा सकता है।",
            .helpQuickStart: "यहाँ से शुरू करें (पहले 5 मिनट)",
            .helpRecordStep: "दूसरे ऐप में क्लिक करें → हॉटकी दबाएँ (डिफ़ॉल्ट Option+S) → बोलें → रोकने के लिए फिर दबाएँ। लाल HUD = रिकॉर्डिंग, हरा = प्रसंस्करण।",
            .helpVariantsStep: "Raw प्रतिलेख है। वेरिएंट 1 हल्की सफ़ाई है। वेरिएंट 2 मज़बूत पुनर्लेखन है। Markdown परिष्कृत टेक्स्ट संरचित करता है।",
            .helpCopyStep: "वर्तमान टैब कॉपी करें, साइडबार से सभी नोट्स कॉपी करें, या हॉटकी क्लिपबोर्ड / सक्रिय ऐप में टाइप करें से पहुँचाएँ।",
            .helpRecordingTitle: "ओवरले HUD",
            .helpHUDStep: "HUD: [A|अक्षर] तरंग [R|1|2]। बाएँ टैप A↔E, दाएँ R→1→2। कहीं भी खींचें; आकार/ध्वनि सामान्य → ओवरले HUD में।",
            .helpOfflineTranscription: "स्थानीय प्रतिलेखन मॉडल",
            .helpOfflineModelStep: "सेटिंग्स → स्थानीय मॉडल: WhisperKit मॉडल डाउनलोड करें। गुणवत्ता और अंग्रेज़ी अनुवाद के लिए Large v3 Full बेहतर।",
            .helpOfflineActivateStep: "डाउनलोड किए मॉडल पर “उपयोग करें” दबाएँ। हटाएँ डिस्क स्थान मुक्त करता है। फ़ॉलबैक: Apple Speech।",
            .helpImportTitle: "आयात और अनुवाद",
            .helpImportStep: "ऑडियो आयात करें या नए नोट के रूप में प्रतिलेखन के लिए फ़ाइल विंडो पर खींचें।",
            .helpTranslateStep: "अनुवाद मोडल: चयन, क्लिपबोर्ड, या छोटी रिकॉर्डिंग → प्रदाता + लक्ष्य भाषा।",
            .helpPolishingProviders: "परिष्करण इंजन",
            .helpPolishingProviderStep: "अक्षम, त्वरित स्थानीय सफ़ाई, स्थानीय MLX, या API प्रदाता से क्लाउड API प्रदाता।",
            .helpPromptsStep: "वेरिएंट 1, वेरिएंट 2 और Markdown के लिए सेटिंग्स → प्रॉम्प्ट। प्रतिलेखन प्लेसहोल्डर रखें।",
            .helpHotkeyStep: "सेटिंग्स → हॉटकी: Option+S सक्षम करें, लक्ष्य और मोड चुनें, केवल ऐप्स में टाइपिंग के लिए ऐक्सेसिबिलिटी प्रदान करें।",
            .helpPermissionsTitle: "अनुमतियाँ",
            .helpMicrophoneStep: "विंडो में और HUD से रिकॉर्डिंग के लिए माइक्रोफ़ोन आवश्यक है।",
            .helpAccessibilityStep: "ऐक्सेसिबिलिटी केवल सक्रिय ऐप में टाइप करें के लिए आवश्यक है।",
            .helpPermissionRefreshStep: "यदि टाइपिंग विफल हो, तो हॉटकी सेटिंग्स में ऐक्सेसिबिलिटी रीफ़्रेश करें या सिस्टम सेटिंग्स खोलें।",
            .helpPrivacyLocalStep: "स्थानीय Whisper और स्थानीय परिष्करण डिवाइस पर रहते हैं।",
            .helpLogsStep: "निदान फ़ाइल चाहिए होने पर सामान्य → सिस्टम लॉग निर्यात करें।",
