            .onboardingGlossaryExplanation: "शब्दावली SmartScribe को नाम, विशेष शब्द, संक्षिप्त रूप और अक्सर गलत पहचाने जाने वाले शब्द आपकी पसंद के अनुसार लिखने में मदद करती है। सही वर्तनी और आम रूप जोड़ें; प्रतिलेखन या अनुवाद के बाद SmartScribe उन रूपों को आपकी चुनी हुई वर्तनी से अपने-आप बदल देगा। शब्दावली इसी Mac पर रहती है और इसे सेटिंग्स में कभी भी संपादित किया जा सकता है।",
